INSERT INTO data.data_tbl_quest (id, a_script_text, at, award_exp_re, color, complete_text, finish_npc, gender, info, is_rebirth, lm, max_level, min_level, money_num, money_type, name, pre_quest_type, qtest, req_class, rn, rt, script_give_up, start_npc, start_text, sub_type, type, start_grant_item, start_grant_qty) VALUES
	(4, NULL, 1, 62, 0, 'Chỉ cần nhấp vào nút Bắt trong lúc chiến đấu, sau đó nhấp vào quái vật thì sẽ có khả năng bắt được. Chú ý là lượng máu của quái vật càng thấp thì sẽ càng dễ bắt!', 237, 2, 'Mỹ Mỹ ở tiệm pet có một món quà tặng bạn, hãy mau đến tìm cô ấy đi.', NULL, -1, 160, 2, 150, 1, 'Nhận Pet', 1, NULL, 'all', 0, 0, NULL, 238, 'Pet chính là trợ thủ đắc lực nhất của ngươi! Quái vật trên Vô Ưu Đại Lục đều có thể bắt được và mang về huấn luyện để trở thành pet! Chỉ cần trong lúc chiến đấu nhấp vào nút Bắt thì sẽ có cơ hội bắt được. Chú ý là lượng máu của quái vật càng thấp thì sẽ càng dễ bắt!', '-1', 1, NULL, NULL),
	(19, NULL, 1, 1734, 0, 'Ha ha, chào các ngươi, hoan nghênh các ngươi đến với Đông Huyền Thành.', 272, 2, 'Đến Đông Huyền Thành báo cáo với Tộc trưởng Bối Tư', NULL, -1, 160, 10, 100, 1, 'Xuất Phát Về Đông Huyền Thành', 1, NULL, 'all', 0, 0, NULL, 231, 'Ha ha, nhanh thế đã đạt được cấp 10 rồi, đây là chứng chỉ, có nó ngươi có thể đến thành Đông Huyền báo cáo với Tộc trưởng Bối Tư rồi. Ông ấy sẽ dạy ngươi nhiều kiến thức hơn nữa.', '-1', 1, NULL, NULL),
	(23, NULL, 1, 1891, 0, 'Rất vui được làm quen với ngươi!', 299, 2, 'Tìm Ryan để học cách dịch chuyển', NULL, -1, 160, 10, 500, 1, 'Hướng Dẫn Của Tộc Trưởng', 1, NULL, 'all', 0, 0, NULL, 272, 'Ngươi có thể đến nhờ Ryan hướng dẫn cách dịch chuyển, Ryan đứng ngay cạnh ta đây.', '-1', 1, NULL, NULL),
	(30, NULL, 2, 2000, 0, 'Đây quả thật là nguyên liệu mới, ta phải chạy nhanh đi chế tạo. Mấy viên bảo thạch này cho ngươi, mau đi rèn trang bị đi.', 373, 2, 'Thu thập 3 Gỗ Thô Đẹp trên người Tiểu Cổ Thụ ở Vân Đài rồi giao cho Mary ở tiệm quần áo.', NULL, -1, 160, 10, 400, 1, 'Nhu Cầu Của Mary', 1, NULL, 'all', 0, 0, NULL, 412, 'Gần đây có rất nhiều thành viên mới, trang bị trong tiệm không đủ dùng, cần ngươi giúp ta thu thập 3 Gỗ Thô Đẹp, đi mau lên, việc làm ăn của ta bận lắm', '-1', 1, NULL, NULL),
	(35, NULL, 1, 2206, 0, 'Hoan nghênh các ngươi đến với gia tộc của chúng ta, ngươi sẽ học ở đây trong một thời gian dài, vì thế đừng có mà lười biếng nhé!', 639, 2, 'Về việc thăng cấp kỹ năng và nghề nghiệp.', NULL, -1, 160, 10, 500, 1, 'Chỉ Dạy Của Tiền Bối', 2, NULL, '|6|', 0, 0, NULL, 640, 'Hiệp sĩ là người kế thừa võ thuật cổ, họ mang theo dòng máu sục sôi xông pha trận mạc, quyết hoàn thành sứ mệnh của mình. Họ chính là thử thách lớn với quân địch. Sau khi đạt đủ điều kiện, ngươi có thể tới chỗ ta thăng cấp kỹ năng. Bây giờ hãy đi bái kiến đạo sư đi!', '-1', 1, NULL, NULL),
	(37, NULL, 1, 2364, 0, 'Sau khi đạt cấp 20 thì ngươi có thể đến gặp ta để nhận nhiệm vụ gia tộc.', 272, 2, 'Nghe Đạo Sư giới thiệu.', NULL, -1, 160, 10, 500, 1, 'Quay Về Đông Huyền', 2, NULL, '|3|', 0, 0, NULL, 311, 'Linh Vũ Tộc do Đạo Sư Bullonh sáng lập, nổi tiếng vì đào tạo nhân tài lễ nghĩa xã hội. Mỗi thành viên của gia tộc có thể coi là điển phạm lễ nghĩa, luôn có cử chỉ và biểu hiện rất nghiêm túc chừng mực. Ha ha, có cảm thấy gia tộc của ta rất vĩ đại, được rồi, đi về nói với tộc trưởng Bối Tư đi. Sau khi đạt cấp độ 20 ngươi có thể đên chỗ ta lĩnh một it nhiệm vụ để làm rồi.', '-1', 1, NULL, NULL),
	(3051, NULL, 1, 108167, 0, 'Có điều còn có một việc rất kỳ quái.', 288, 2, 'Băng Xuyên Thiên Thư ghi lại ảnh hưởng của Trí thạch lên các sinh vật', NULL, -1, 160, 91, 50000, 2, 'Câu Đố Băng Xuyên Thiên Thư', 1, NULL, 'all', 0, 0, NULL, 288, 'Ta đã nghiên cứu Băng Xuyên Thiên Thư suốt mấy ngày nay rồi. Trong đó chủ yếu nói về ảnh hưởng của Trí Thạch lên các sinh vật, trong đó có 1 ảnh hưởng rất nghiêm trọng là khiến cho sinh vật trở nên cuồng bạo. Thảo nào gần đây bọn quái vật ở khắp nơi đều trở nên hung hăng. Xem ra có người đã dùng Trí thạch để ảnh hưởng lên quái vật, thực hiện âm mưu gì đó.', '-1', 2, NULL, NULL),
	(5418, 'Phần thưởng không rõ', 1, 0, 3, 'Ha ha, ngươi đã có thể tiếp tục bước xuống tầng tiêp theo rồi, hãy nhớ cho kỹ quy luật dịch chuyển giữa các ma pháp trận, tránh bị lạc đường, hãy đi đi…', 1706, 2, 'Tìm và tiêu diệt Đồng Bì Thiết Vệ và Hướng Dẫn Vong Hồn trong Thạch Quan ở tầng 3 (Nhắc nhở quan trọng: 1. Có thể di chuyển qua lại giữa các Ma Pháp Trận giống nhau2. Hai Người Thần Bí sẽ xuất hiện ở gần Đồng Bì Thiết Vệ và Hướng Dẫn Vong Hồn, sau khi tiêu diệt chúng có thể trả nhanh nhiệm vụ', NULL, -1, 160, 60, 0, 2, 'Kho Báu Đại Mạc (6)', 1, NULL, 'all', 0, 0, NULL, 192, 'Quả nhiên đã đến rồi… Ha ha, đừng hỏi ta là ai, chỉ cần biết là ta đến để giúp ngươi, nghe đây, đường đi ở tầng 3 rất phức tạp, ngườ nào nắm phương hướng không tốt sẽ rất dễ bị lạc. Tầng này có 2 loại quái vật là Giáp Giác Tinh và Vong Hồn Mê Muội, trước tiên phải nghĩ cách tiêu diệt chúng. Nhớ rằng có thể dịch chuyển giữa các ma pháp trận giống nhau.', '-1', 6, NULL, NULL),
	(45, NULL, 1, 5673, 0, 'Chào mừng người đến với thành Đông Huyền xinh đẹp!', 343, 2, 'Hãy đến gặp Đông Huyền Sứ để được hướng dẫn về các nhiệm vụ treo thưởng.', NULL, -1, 160, 11, 500, 1, 'Gặp Đông Huyền Sứ', 2, NULL, 'all', 0, 0, NULL, 280, 'Bên cạnh Đông Huyền Sứ là một tấm bảng dùng để đăng các nhiệm vụ treo thưởng. Trên đó có dán rất nhiều nhiệm vụ treo thưởng có thể nhận. Trước tiên hãy đến chỗ của Đông Huyền Sứ để được hướng dẫn cụ thể hơn nhé.', '-1', 1, NULL, NULL),
	(47, NULL, 1, 391, 0, 'Hãy cẩn thận nhé, nếu bị thương thì có thể đến chỗ của ta để điều trị.', 430, 2, 'Đi Vân Đài thu thập 1 Cành Cây Khiết Tịnh trên thân Tiểu Cổ Thụ.', NULL, -1, 160, 3, 300, 1, 'Thu Thập Cành Cây', 1, NULL, 'all', 0, 0, NULL, 430, 'Cành Cây Khiết Tịnh trên người Tiểu Cổ Thụ có thể dùng làm nguyên liệu chế tạo, tượng trưng cho tâm linh hoàn mỹ.', '-1', 1, NULL, NULL),
	(48, NULL, 1, 430, 0, 'Rất tốt.', 430, 2, 'Đi Vân Đài thu thập 1 sợi lông của Thất Vị Kê.', NULL, -1, 160, 3, 300, 1, 'Thu Thập Lông Vũ', 1, NULL, 'all', 0, 0, NULL, 430, 'Nguyên liệu thứ hai là Lông của Thất Vị Kê, nó tượng trưng cho sức mạnh vô tận.', '-1', 1, NULL, NULL),
	(49, NULL, 1, 469, 0, 'Nguyên liệu đã đủ, chúng ta bắt tay vào làm huy hiệu thôi.', 430, 2, 'Đi Vân Đài thu thập 1 Bào Tử Nấm Lục.', NULL, -1, 160, 3, 300, 1, 'Thu Thập Bào Tử', 1, NULL, 'all', 0, 0, NULL, 430, 'Nguyên liệu thứ ba là Bào Tử Nấm Lục, tượng trưng cho sinh mệnh mạnh mẽ.', '-1', 1, NULL, NULL),
	(267, NULL, 1, 4618, 0, 'Ha ha, ngư phu nuôi cá, chuyện mới, Ngươi đợi đã', 288, 2, 'Đến thư viện Đông Huyền mượn sách nuôi cá', NULL, -1, 160, 26, 1500, 1, 'Ngư Phu Mua Cá 11-9', 1, NULL, 'all', 0, 0, NULL, 438, 'Hỏi một chút, những cá này ăn gì? Có lẽ ta cần một quyển sách dạy nuôi cá', '-1', 4, NULL, NULL),
	(51, NULL, 1, 1576, 0, 'Lại gặp lại con rồi.', 231, 2, 'Đến Xuất Vân Thôn tìm Thôn Trưởng.', NULL, -1, 160, 9, 1000, 1, 'Báo Cáo Thôn Trưởng', 2, NULL, 'all', 0, 0, NULL, 434, 'Vệ Sĩ quả đã tiến cử cho ta một thành viên ưu tú! Tương lai ngươi nhất định sẽ rất xán lạn, ta đảm bảo đấy! Giờ ngươi hãy về báo cho Thôn Trưởng biết việc bọn Tiểu Sơn Quái lộng hành ở đây.', '-1', 1, NULL, NULL),
	(53, NULL, 1, 1239, 0, 'Tạm thời trước mắt không còn vấn đề gì lớn.', 456, 2, 'Tiêu diệt 3 Thỏ Lưu Manh ở gần Đông Xuất Vân.', NULL, -1, 160, 7, 1500, 1, 'Quét Sạch Răng Cửa', 1, NULL, 'all', 0, 0, NULL, 456, 'Khá lắm, rất có dũng khí! Thôi không nói nhiều nữa, hãy mau đi tiêu diệt chúng đi!', '-1', 1, NULL, NULL),
	(56, NULL, 1, 10326, 0, 'Ha ha, không thể không thừa nhận răng cửa của nó rất to.', 433, 2, 'Đánh thắng Bang Chủ Răng Cửa ở đông Xuất Vân.', NULL, -1, 160, 8, 3500, 1, 'Đánh Bại Bang Chủ Răng Cửa', 1, NULL, 'all', 0, 0, NULL, 433, '“Răng đẹp thì ăn cơm sẽ ngon”, khẩu lệnh gì mà kỳ quái, tạm thời không cần để ý đến nó, nhiệm vụ quan trọng của chúng ta là lật đổ bang chủ Răng Cửa, mau hành động thôi.', '-1', 1, NULL, NULL),
	(58, NULL, 1, 482, 0, 'Hi vọng việc này sẽ sớm kết thúc.', 434, 2, 'Mọi việc đã gần xong rồi, để xem trưởng lão Vô Ưu có ý kiến gì', NULL, -1, 160, 9, 1500, 1, 'Hỏa Kê Đáng Thương', 1, NULL, 'all', 0, 0, NULL, 434, 'Bọn Hỏa Kê sau khi ăn phải những cây nấm quái dị này thì cũng trở nên điên loạn, việc này e rằng lại cần nhờ đến sự giúp sức của ngươi rồi.', '-1', 1, NULL, NULL),
	(60, NULL, 1, 39392, 0, 'Bia kỉ niệm xuất hiện một dòng chữ mà lúc nãy không có: Khi ngươi gặp khó khăn, hãy nhớ đến lòng can đảm mà ngươi vừa có!', 476, 2, 'Đánh bại Thủ Vệ Grama.', NULL, -1, 160, 9, 5000, 1, 'Truyền Thụ Dũng Khí', 1, NULL, 'all', 0, 0, NULL, 476, '(Bạn sờ vào bia kỉ niệm, đột nhiên cảm thấy trời đất xoay chuyển… Khi bạn định thần lại thì thấy trước mặt là một Thủ Vệ khổng lồ)', '-1', 1, NULL, NULL),
	(65, NULL, 1, 636, 0, 'Là Thuốc Thử Nghiệm Yêu Lực à, đợi nhé, ta tìm xem sao.', 481, 2, 'Thuốc Thử Nghiệm Yêu Lực đã dùng hết rồi, Quan Sát Viên hy vọng bạn giúp ông ấy đến chỗ ông chủ hiệu thuốc Bàng Bối mua loại thuốc này.', NULL, -1, 160, 16, 1000, 1, 'Đại Địa Than Khóc 10-4', 1, NULL, 'all', 0, 0, NULL, 436, 'Tốt, chúng ta bắt đầu nào….Thuốc hết rồi, chết rồi, chết rồi, ngươi đi mua cho ta Thuốc Thử Nghiệm Yêu Lực ở chỗ ông chủ tiệm thuốc nhé. Ta đợi ngươi ở đây.', '-1', 4, NULL, NULL),
	(67, NULL, 1, 689, 0, 'Ha, cuối cùng ngươi cũng về rồi, chúng ta lập tức tiến hành đo thêm bước nữa, kết quả phân tích một lát là có.', 436, 2, 'Đưa Thuốc Thử Nghiệm Yêu Lực cho Quan Sát Viên ở Thiên Lục Châu.', NULL, -1, 160, 16, 1000, 1, 'Đại Địa Than Khóc 10-6', 1, NULL, 'all', 0, 0, NULL, 481, 'Đợi lâu rồi, đây là thuốc đo yêu lực mà ngươi cần, nếu không đủ thì chỗ ta vẫn còn.', '-1', 4, NULL, NULL),
	(69, NULL, 1, 6883, 0, 'Được, để xem anh bạn mà ngươi mang về nào, chân tướng của mọi việc chỉ còn cách chúng ta mội bước, để ta xem nó có cho chúng ta biết thông tin nào có lợi không.', 436, 2, 'Quan Sát Viên hy vọng bạn bắt 1 Độc Nhãn Ốc Đảo ở ốc đảo Thiên Lục Châu về.', NULL, -1, 160, 16, 2000, 1, 'Đại Địa Than Khóc 10-8', 1, NULL, 'all', 0, 0, NULL, 436, 'Đúng rồi, ngươi có thể bắt cho ta tên Độc Nhãn Tinh còn sống về đây không, ta sẽ nghĩ cách “nói chuyện” với chúng, có thể biết được nguyên nhân tại sao chúng lại làm như vậy.', '-1', 4, NULL, NULL),
	(71, NULL, 1, 742, 0, 'Là thật à, thật là ngoài sức tưởng tượng, lần này nhờ biểu hiện kiệt xuất của ngươi mà đã giải quyết cho chúng ta nguy cơ sa mạc hóa,  ta xin thay mặt nhân dân Bàng Bối vô cùng cảm ơn ngươi.', 435, 2, 'Về thành Bàng Bối báo cáo kết quả hành động lần này.', NULL, -1, 160, 16, 1000, 1, 'Đại Địa Than Khóc 10-10', 1, NULL, 'all', 0, 0, NULL, 436, 'Biểu hiện của ngươi thật không chê vào đâu được, hãy về nói với thành chủ ngươi đã hoàn thành xuất sắc nhiệm vụ này.', '-1', 4, NULL, NULL),
	(11139, NULL, 1, 0, 0, 'Đa tạ ngươi!', 573, 2, 'Bắt 1 con Ếch Độc Đầm Lầy', NULL, -1, 160, 101, 0, 2, 'Bắt Ếch Độc Đầm Lầy', 1, NULL, 'all', 0, 0, NULL, -1, 'Tiểu Hoa muốn có 1 con Ếch Độc Đầm Lầy, hãy giúp cô ấy bắt chúng!', '7-9', 7, NULL, NULL),
	(77, NULL, 1, 6000, 0, 'Ồ ồ, đây là móng chân của Mèo Kính Đen, thật hoàn hảo.', 377, 2, 'Lấy 10 Móng của Mèo Kính Đen ở Anh Vũ Cảnh.', NULL, -1, 160, 31, 8000, 2, 'Ảo Tưởng Của Tiến Sĩ Điên 17-6', 1, NULL, 'all', 0, 0, NULL, 377, 'Đúng rồi, ta hiện đang thiếu nguyên liệu nghiên cứu quan trọng, chính là móng chân của Mèo Kính Đen, Anh Vũ Cảnh đối với người như ta có thể là cấm địa, ngươi có thể lấy giúp ta 10 móng chân về không.', '-1', 4, NULL, NULL),
	(79, NULL, 1, 6000, 0, 'Chính xác, đúng là cái này, để ta lắp vào xem nào.', 437, 2, 'Lấy 5 viên Đá Pháp Thuật trên người Gấu Trúc ở Trầm Thụy Lâm.', NULL, -1, 160, 31, 8000, 2, 'Ảo Tưởng Của Tiến Sĩ Điên 17-8', 1, NULL, 'all', 0, 0, NULL, 437, 'A a a, ta thật ngốc, tại sao không nghĩ ra, Đá Pháp Thuật, Đá Pháp Thuật, ở đâu có, ta nghĩ xem, mau đi Trầm Thụy Lâm, trên thân Gấu Trúc ở đấy có Đá Pháp Thuật mà ta cần.', '-1', 4, NULL, NULL),
	(82, NULL, 1, 3000, 0, 'Này, ta vừa nhìn thấy một việc rất kỳ quái.', 439, 2, 'Đến Kỵ Bình Nguyên nghe ngóng xem có ai nhìn thấy người máy không.', NULL, -1, 160, 31, 3000, 2, 'Ảo Tưởng Của Tiến Sĩ Điên 17-11', 1, NULL, 'all', 0, 0, NULL, 437, 'Tác phẩm của ta, ngươi giúp ta tìm nó về, không được làm hỏng nó, ta muốn nó nguyên vẹn. Đi ra khỏi cửa mà tìm.', '-1', 4, NULL, NULL),
	(3690, NULL, 1, 261339, 0, 'Hay lắm, thành công rồi!', 892, 2, 'Mang Thần Phách về', NULL, -1, 160, 110, 50000, 2, 'Trấn Hồn Kiếm 19-18', 1, NULL, 'all', 0, 0, NULL, 889, '……', '-1', 4, NULL, NULL),
	(83, NULL, 1, 3000, 0, 'Ngươi đến mua cá à?', 438, 2, 'Đến Lê Dương đảo tìm tung tích người máy.', NULL, -1, 160, 31, 3000, 2, 'Ảo Tưởng Của Tiến Sĩ Điên 17-12', 1, NULL, 'all', 0, 0, NULL, 439, 'Lúc nãy ta nhìn thấy một thứ bay qua đầu, ta không biết đó là thứ gì, ồ, có thể là người, nhưng người không thể bay trên không, thứ đó bay đến hồ Lê Dương rồi.', '-1', 4, NULL, NULL),
	(85, NULL, 1, 61200, 0, 'Ồ, Ginny, Ginny yêu dấu của ta, sao thế?', 437, 2, 'Mục tiêu là (110, 56) ở Anh Vũ Cảnh, người máy có khả năng đã đến đó, hãy tìm nó và đem về cho tiến sĩ.', NULL, -1, 160, 31, 48960, 2, 'Ảo Tưởng Của Tiến Sĩ Điên 17-14', 1, NULL, 'all', 0, 0, NULL, -1, '(Đây là bản đồ đại lục Vô Ưu vẽ bằng máy, bên trên chỉ vẽ một đường thẳng, nơi đến là Anh Vũ Cảnh)', '-1', 4, NULL, NULL),
	(681, NULL, 1, 0, 0, 'Đa tạ ngươi', 403, 2, 'Tiêu diệt 45 con Nấm Huyết Sắc', NULL, 3, 45, 41, 4500, 2, 'Truy Nã Nấm Huyết Sắc', 1, NULL, 'all', 0, 0, NULL, 403, 'tiêu diệt 45 con Nấm Huyết Sắc', '-1', 6, NULL, NULL),
	(88, NULL, 2, 3000, 0, 'Hãy sống lại đi Ginny yêu dấu của ta, tốt quá, cảm ơn ngươi, à mà ngươi là ai?', 437, 2, 'Tim Nằm Yên đã làm xong, hãy đưa cho tiến sĩ Harry', NULL, -1, 160, 31, 3000, 2, 'Ảo Tưởng Của Tiến Sĩ Điên 17-17', 1, NULL, 'all', 0, 0, NULL, 412, 'Ha ha, lâu lắm không làm rồi, may mà tay nghề vẫn chưa giảm, chắc là không có vấn đề gì?', '-1', 4, NULL, NULL),
	(90, NULL, 1, 35000, 0, 'Làm phiền ngươi khuya rồi phải chạy một vòng, thật ngại quá.', 442, 2, 'Đến Hư Không Mạc tìm Thủ Hoang Nhân và đưa đồ dùng sinh hoạt cho họ.', NULL, -1, 160, 56, 10000, 2, 'Thủ Hoang Nhân Nguy Cấp 13-1', 1, NULL, 'all', 0, 0, NULL, 275, 'Xin chào chàng trai trẻ, ngươi muốn đi Hư Không Mạc à, nếu thật thì mang hộ ta hòm đồ này cho Thủ Hoang Nhân được không, ta thật sự không có thời gian để đi.', '-1', 4, NULL, NULL),
	(92, NULL, 1, 35000, 0, '\"Ảo Ảnh Sa Mạc\" đúng không? Để ta đi lấy cho ngươi.', 288, 2, 'Đến thư viện Đông Huyền mượn "Ảo Ảnh Sa Mạc"', NULL, -1, 160, 56, 10000, 2, 'Thủ Hoang Nhân Nguy Cấp 13-3', 1, NULL, 'all', 0, 0, NULL, 442, 'Đúng rồi, trên đường về ngươi có thể tạt qua thư viện được không? Đi mượn cuốn \"Ảo Ảnh Sa Mạc\" cho ta.', '-1', 4, NULL, NULL),
	(93, NULL, 1, 35000, 0, 'Không ngờ ngươi còn nhã ý mang sách đến hộ ta, cảm ơn nhiều', 442, 2, 'Đưa "Ảo Ảnh Sa Mạc" cho Thủ Hoang Nhân.', NULL, -1, 160, 56, 10000, 2, 'Thủ Hoang Nhân Nguy Cấp 13-4', 1, NULL, 'all', 0, 0, NULL, 288, 'Xin lỗi đã để ngươi chờ lâu, đây là sách ngươi cần, xin hãy ký tên ở đây, giữ cẩn thận nhé.', '-1', 4, NULL, NULL),
	(97, NULL, 1, 100000, 0, 'Lâu lắm rồi không chiến đấu, không đánh được như xưa rồi.', 442, 2, 'Tiêu diệt 30 Khổng Lồ ở Hư Không Mạc.', NULL, -1, 160, 56, 40000, 2, 'Thủ Hoang Nhân Nguy Cấp 13-8', 1, NULL, 'all', 0, 0, NULL, 442, 'Đấy là chuyện ta không muốn nhắc tới… Cẩn thận, bầy Khổng Lồ đang phát động tấn công chúng ta kìa, mau đánh đuổi bọn chúng.', '-1', 4, NULL, NULL),
	(98, NULL, 1, 800000, 0, 'Thế nào? Cầm được đoạn ký ức đấy chưa.', 442, 2, 'Tìm cách đánh bại tạp niệm của Thủ Hoang Nhân trong ký ức của anh ta.', NULL, -1, 160, 56, 640000, 2, 'Thủ Hoang Nhân Nguy Cấp 13-9', 1, NULL, 'all', 0, 0, NULL, 442, 'Ta đã phong ấn ký ức sâu trong tâm linh, bây giờ ta sẽ sử dụng sức mạnh của trí thạch để đưa ngươi vào ký ức quá khứ ấy. Hãy chuẩn bị tốt rồi đến tìm ta, thành hay bại phải tự xem vào khả năng của chính mình', '-1', 4, NULL, NULL),
	(102, NULL, 1, 1000000, 0, 'Bùa Trấn Yêu, ngươi nên giữ cẩn thận, sẽ có lúc ta nói cho ngươi biết một bí mật', 442, 2, 'Đánh bại Cương Thi Vương, lấy Bùa Trấn Yêu trên người nó.', NULL, -1, 160, 56, 800000, 2, 'Thủ Hoang Nhân Nguy Cấp 13-13', 1, NULL, 'all', 0, 0, NULL, 442, 'Để đảm bảo thành công, ta cần công cụ để tăng cường sức mạnh cho đá trí tuệ, hãy đi lấy cho ta Bùa Trấn Yêu của Cương Thi Vương lại đây.', '-1', 4, NULL, NULL),
	(103, NULL, 1, 1648, 0, 'Thật tốt, ngươi là người Đông Huyền cử đến chi viện cho chúng ta đúng không?', 446, 2, 'Đến Tiên Lạp thành tìm Trưởng Cận Vệ ở đó.', NULL, -1, 160, 21, 1200, 1, 'Quái Vật Da Xanh 12-1', 1, NULL, 'all', 0, 0, NULL, 277, 'Nhận được tín hiệu viện trợ khẩn cấp của Tiên Lạp, mau đi cứu viện.', '-1', 4, NULL, NULL),
	(104, NULL, 1, 16478, 0, 'Làm tốt lắm', 446, 2, 'Đánh đuổi 10 Độc Nhãn Da Xanh ở Lạp Tuyết Địa.', NULL, -1, 160, 21, 2400, 1, 'Quái Vật Da Xanh 12-2', 1, NULL, 'all', 0, 0, NULL, 446, 'Mau, Độc Nhãn Da Xanh đang tiền công chúng ta, đánh đuổi bọn chúng', '-1', 4, NULL, NULL),
	(105, NULL, 1, 18125, 0, 'Rất tốt!', 446, 2, 'Quay lại Lạp Tuyết Địa đánh đuổi 15 Độc Nhãn Da Xanh.', NULL, -1, 160, 21, 2400, 1, 'Quái Vật Da Xanh 12-3', 1, NULL, 'all', 0, 0, NULL, 446, 'Độc Nhãn Da Xanh bắt đầu một vòng tiến công mới, nhanh chóng chuẩn bị nào.', '-1', 4, NULL, NULL),
	(108, NULL, 1, 19773, 0, 'Được, hãy mang Độc Nhãn Da Xanh đến trước mặt ta.', 448, 2, 'Tìm một Độc Nhãn Da Xanh ở Tiên Lạp cho Lão Thợ Săn.', NULL, -1, 160, 21, 2400, 1, 'Quái Vật Da Xanh 12-6', 1, NULL, 'all', 0, 0, NULL, 448, 'Hóa ra là như vậy, ngươi giúp ta “mời” một Độc Nhãn Da Xanh về đây, ta phụ trách “nói chuyện” với nó một chút.', '-1', 4, NULL, NULL),
	(112, NULL, 1, 82386, 0, 'Vâng, để chúng ta chuẩn bị một chút rồi sẽ đi nói chuyện với Độc Nhãn', 446, 2, 'Đánh bại Độc Nhãn Xanh Thủ Lĩnh ở Lạp Tuyết Địa.', NULL, -1, 160, 21, 15000, 1, 'Quái Vật Da Xanh 12-10', 1, NULL, 'all', 0, 0, NULL, 446, 'Độc Nhãn Xanh Thủ Lĩnh cũng ở trong bầy quái thú, trước tiên hãy nghĩ cách để nó bình tĩnh lại.', '-1', 4, NULL, NULL),
	(115, NULL, 1, 5000, 0, 'Ngươi đến giúp ta điều tra à?', 295, 2, 'Đi báo cáo với Trưởng Cận Vệ ở thành Tinh Linh.', NULL, -1, 160, 41, 5000, 2, 'Âm Thanh Lạ Trong Rừng 10-1', 1, NULL, 'all', 0, 0, NULL, 290, 'Xin chào người lữ hành, ngươi đến để giúp chúng ta à, gần đây thường nghe thấy âm thanh kêu gào từ rừng sâu. Ta đã bảo Trưởng Cận Vệ triển khai điều tra rồi, ngươi đi tìm Trưởng Cận Vệ mà nói chuyện.', '-1', 4, NULL, NULL),
	(117, NULL, 1, 20000, 0, 'Ngươi đợi 1 chút, ta bỏ nấm vào nồi, xong ngay thôi.', 403, 2, 'Giúp thợ săn Luca bắt một cây Nấm Huyết Sắc ở Trầm Thụy Lâm.', NULL, -1, 160, 41, 5000, 2, 'Âm Thanh Lạ Trong Rừng 10-3', 1, NULL, 'all', 0, 0, NULL, 403, 'Ta đi săn cả ngày rồi, bây giờ mới chuẩn bị cơm tối, ngươi giúp ta đi hái Nấm Huyết Sắc về làm rau, chúng ta vừa ăn cơm vừa nói chuyện.', '-1', 4, NULL, NULL),
	(119, NULL, 1, 5000, 0, 'Bụi thủy tinh trong tay ngươi ư? Ừ… để ta xem.', 288, 2, 'Mang Bụi Thủy Tinh Thần Bí đến tìm thủ thư Đông Huyền.', NULL, -1, 160, 41, 5000, 2, 'Âm Thanh Lạ Trong Rừng 10-5', 1, NULL, 'all', 0, 0, NULL, 0, '(Bạn cầm bụi thủy tinh lấy từ người quái vật quan sát thật kỹ nhưng không thể nào phân tích được là thứ gì, có lẽ có thể đến thư viện tìm chân tướng)', '-1', 4, NULL, NULL),
	(650, NULL, 1, 0, 0, 'Đa tạ ngươi', 468, 2, 'Tiêu diệt 25 con Bạch Tuộc Ma', NULL, 3, 25, 21, 2500, 1, 'Lê Dương Xoáy Ngầm', 1, NULL, 'all', 0, 0, NULL, 468, 'Gần đây Bạch Tuộc Ma ngày càng nhiều, giúp ta tiêu diệt chúng', '-1', 6, NULL, NULL),
	(121, NULL, 1, 5000, 0, 'Điều này là thật à? Vậy chúng ta phải triển khai hành động.', 290, 2, 'Nói nguyên nhân yêu quái cuồng bạo cho thành chủ Tinh Linh', NULL, -1, 160, 41, 5000, 2, 'Âm Thanh Lạ Trong Rừng 10-7', 1, NULL, 'all', 0, 0, NULL, 272, 'Năng lượng phát ra ở trong này không ổn định, khiến người cảm thấy bất an, động vật nếu động vào nó sẽ trở nên hung ác, mau đi thông báo Tinh Linh thành, quái vật có thể phát động tiến công bất cứ lúc nào.', '-1', 4, NULL, NULL),
	(268, NULL, 1, 4926, 0, 'Nhanh nhanh nhanh, ta xem, bước một là…', 438, 2, 'Đưa cho Ngư Dân Lão Kim  đảo Lê Dương cuốn "Tri âm của nước"', NULL, -1, 160, 26, 1500, 1, 'Ngư Phu Mua Cá 11-10', 1, NULL, 'all', 0, 0, NULL, 288, 'Cầm lấy, quyển này có thể đến từ thế giới bên ngoài đại lục Vô Ưu, bảo quản cẩn thận', '-1', 4, NULL, NULL),
	(124, NULL, 1, 30784, 0, 'Cảm ơn …', 450, 2, 'Tìm lại túi bưu kiện từ trên thân Lang Bì Dương ở Quang Bình Nguyên.', NULL, -1, 160, 26, 3000, 1, 'Gặp Người Đưa Thư 8-2', 1, NULL, 'all', 0, 0, NULL, 450, 'Khi ta từ Quang Bình Nguyên về gặp bầy Lang Bì Dương, không hiểu sao chúng lại tấn công ta, túi bưu kiện của ta đã bị chúng lấy đi rồi, giúp ta lấy lại nó nha, trong đó còn rất nhiều thư.', '-1', 4, NULL, NULL),
	(126, NULL, 1, 3695, 0, 'Cảm ơn!', 423, 2, 'Đưa thư đến tiệm Pet của Amy.', NULL, -1, 160, 26, 1500, 1, 'Gặp Người Đưa Thư 8-4', 1, NULL, 'all', 0, 0, NULL, 423, '(Bạn lấy một lá thư trong túi bưu kiện ra, đây là thư gửi cho tiệm Pet Amy.)', '-1', 4, NULL, NULL),
	(127, NULL, 1, 4002, 0, 'Vất vả quá!', 307, 2, 'Đưa thư đến tiệm trang sức Văn Văn.', NULL, -1, 160, 26, 1500, 1, 'Gặp Người Đưa Thư 8-5', 1, NULL, 'all', 0, 0, NULL, 307, '(Bạn lấy một lá thư trong túi bưu kiện ra, đây là thư gửi cho tiệm trang sức Văn Văn.)', '-1', 4, NULL, NULL),
	(129, NULL, 1, 4618, 0, 'Cảm ơn, ngươi vất vả quá', 422, 2, 'Thư gửi tiên tử trị thương.', NULL, -1, 160, 26, 1500, 1, 'Gặp Người Đưa Thư 8-7', 1, NULL, 'all', 0, 0, NULL, 422, '(Bạn lấy một phong thư từ trong túi bưu kiện, đây là thư gửi tiên tử trị thương)', '-1', 4, NULL, NULL),
	(132, NULL, 1, 5542, 0, 'Xin lỗi, ta nghĩ ngươi tìm nhầm người rồi, ta không biết ngươi đang nói gì, càng không gặp cô gái nào.', 451, 2, 'Đến Quang Bình Nguyên tìm manh mối.', NULL, -1, 160, 26, 1500, 1, 'Gặp Người Đưa Thư 8-10', 1, NULL, 'all', 0, 0, NULL, 425, 'Hôm đó con gái ta cùng bạn học đi đến Quang Bình Nguyên thu thập mẫu thực vật thì bị nhóm người bịt mặt tấn công, chỉ có bạn của nó trốn thoát trở về. Nhóm người bịt mặt đó chắc còn ở Quang Bình Nguyên.', '-1', 4, NULL, NULL),
	(133, NULL, 1, 123134, 0, 'Dừng tay, ta đầu hàng!', 451, 2, 'Bắt Jia thật thà ở Quang Bình Nguyên gật đầu nhận tội.', NULL, -1, 160, 26, 24000, 1, 'Gặp Người Đưa Thư 8-11', 1, NULL, 'all', 0, 0, NULL, 451, 'Không biết là không biết, Linh Linh không ở đây, hãy cút khỏi nhà ta (chưa khảo đã xưng, xem ra cần cho hắn biết thế nào là lễ độ)', '-1', 4, NULL, NULL),
	(134, NULL, 1, 5849, 0, 'Cảm ơn ngươi, ta không biết nên báo đáp ngươi như thế nào, Linh Linh con không sao là tốt rồi.', 425, 2, 'Báo cáo với Trưởng Thương Hội Tinh Linh thành tin con gái bình an', NULL, -1, 160, 26, 1500, 1, 'Gặp Người Đưa Thư 8-12', 1, NULL, 'all', 0, 0, NULL, 451, 'Linh Linh bị ta nhốt ở trong lồng tại nhà, ta sẽ thả cô ấy, anh hùng tha mạng.', '-1', 4, NULL, NULL),
	(137, NULL, 1, 44880, 0, 'Ra đằng sau Tiêu diệt gà rồi rửa sạch nấm và cắt ra.', 452, 2, 'Đi Vân Đài bắt 1 con Thất Vị Kê và 1 Nấm Đông Cô.', NULL, -1, 160, 46, 32000, 2, 'Dạ Dày Thực Thần 7-2', 1, NULL, 'all', 0, 0, NULL, 452, 'Trẻ con gần đây toàn là con một, đều không biết làm chuyện nhà, cần dạy cho chúng biết nấu một món ăn, ngươi hãy đi thu thập thực phẩm, nguyên liệu làm món gà hầm nấm là Thất Vị Kê và Nấm Đông Cô, ngươi biết đi đâu tìm rồi.', '-1', 4, NULL, NULL),
	(139, NULL, 1, 44880, 0, 'May mà ngươi không nhầm lẫn chân trái và chân phải', 452, 2, 'Lấy 1 bàn chân phải của Gấu Mật ở Lạp Tuyết Địa, đi Tháp Khắc Nguyên lấy 1 chân trái của Gấu Bùn.', NULL, -1, 160, 46, 32000, 2, 'Dạ Dày Thực Thần 7-4', 1, NULL, 'all', 0, 0, NULL, 452, 'Thế nào? Có tìm được cảm giác nấu nướng không. Tiếp theo chúng ta phải làm tiếp, nguyên liệu lần này cần là chân phải của Gấu Mật và chân trái Gấu Bùn, xuất phát đi', '-1', 4, NULL, NULL),
	(141, NULL, 1, 44880, 0, 'Xem ra ngươi đã lấy được mật của yêu hoa rồi', 452, 2, 'Đến Anh Vũ Cảnh thu thập mật Yêu Hoa Thất Hồn, mật Yêu Hoa Diệp Hồn, và mật Yêu Hoa Mê Hoặc, mỗi loại 3 cái.', NULL, -1, 160, 46, 32000, 2, 'Dạ Dày Thực Thần 7-6', 1, NULL, 'all', 0, 0, NULL, 452, 'Là một Thực Thần, tại sao lại không có cơm bi thương, nhớ năm đó trong cuộc tranh bá Thực Thần, món cơm …….hình như ta lạc đề rồi, đã là buồn thương, thì phải có nguyên liệu buồn thương, mật yêu hoa trên Anh vũ là không thể thiếu.', '-1', 4, NULL, NULL),
	(10641, NULL, 1, 0, 0, 'Đa tạ ngươi!', 573, 2, 'Bắt 1 Thợ Săn Cá Mập', NULL, -1, 160, 101, 0, 2, 'Bắt Thợ Săn Cá Mập', 1, NULL, 'all', 0, 0, NULL, -1, 'Tiểu Hoa muốn có 1 Thợ Săn Cá Mập, hãy giúp cô ấy bắt chúng!', '7-9', 7, NULL, NULL),
	(146, NULL, 1, 583, 0, 'Anh bạn này thật đáng yêu, ha ha … chỉ là hơi ngốc nhưng không vấn đề gì, nhìn ta này.', 280, 2, 'Đưa Ốc Tiểu Binh đến tiệm Pet Tôn Lệ ở Đông Huyền.', NULL, -1, 160, 16, 1000, 1, 'Chìa Khóa Kỳ Dị 5-3', 1, NULL, 'all', 0, 0, NULL, 453, 'Gã đó nói gì chúng ta căn bản nghe không hiểu? ! nghe nói Tôn Lệ ở tiệm Pet nghe hiểu lời Pet, mặc dù ta không hiểu gã này có coi là Pet không, nhưng mà cú thử xem.', '-1', 4, NULL, NULL),
	(148, NULL, 1, 31766, 0, 'Lần này thì chúng ta có thể yên tâm bắt cá rồi.', 453, 2, 'Sau khi tìm được bạch tuộc Alumo ở Lê Dương Bắc, nghĩ cách tiêu diệt  nó.', NULL, -1, 160, 16, 10000, 1, 'Chìa Khóa Kỳ Dị 5-5', 1, NULL, 'all', 0, 0, NULL, 453, 'Buổi trưa hàng ngày, nước hồ lên cao nhất, có thể là lúc nó ăn thức ăn? Ta nghĩ Alumo nhất định sẽ tự hiện thân.', '-1', 4, NULL, NULL),
	(151, NULL, 1, 795, 0, 'Titan luyện rất phức tạp', 416, 2, 'Tìm Tiến Sĩ Ultra ở thành Đông Huyền, hy vọng ông ấy có thể giúp có được titan', NULL, -1, 160, 16, 1000, 1, 'Chìa Khóa Kỳ Dị 5-8', 1, NULL, 'all', 0, 0, NULL, 377, 'Nghe nói tiến sĩ Ultra biết làm titan.', '-1', 4, NULL, NULL),
	(152, NULL, 1, 848, 0, 'Bây giờ nguyên liệu lên giá, vốn đắt bây giờ lại càng đắt, nên ta không thể dễ dàng bán cho ngươi được', 274, 2, 'Giúp tiến sĩ điên có được 1 hòm đồng( cái này tiệm vũ khí chắc là có)', NULL, -1, 160, 16, 1000, 1, 'Chìa Khóa Kỳ Dị 5-9', 1, NULL, 'all', 0, 0, NULL, 416, 'Ta bây giờ đang nghiên cứu lò điện gọi là “lò đồng làm lạnh bằng nước”, thiếu rất nhiều đồng, ngươi có thể đi lấy cho ta không?', '-1', 4, NULL, NULL),
	(153, NULL, 1, 5295, 0, 'Mau đưa cho tiến sĩ đi.', 274, 2, 'Giúp ông chủ tiệm vũ khí bắt 1 Thủy Lam Bọt ở Lê Dương Bắc.', NULL, -1, 160, 16, 2000, 1, 'Chìa Khóa Kỳ Dị 5-10', 1, NULL, 'all', 0, 0, NULL, 274, 'Nhà ta đang tu sửa, nghe nói thủy lam bọt rất đẹp, không biết để trong nhà có đẹp không?', '-1', 4, NULL, NULL),
	(7583, NULL, 1, 0, 0, 'Cảm ơn ngươi', 304, 2, 'Tìm Hamburger ', NULL, -1, 160, 40, 0, 2, 'Tìm Hamburger', 1, NULL, 'all', 0, 0, NULL, -1, 'Ta hơi đói, ngươi có thể giúp ta kiếm chút thức ăn được không?', '7-5', 7, NULL, NULL),
	(155, NULL, 1, 953, 0, 'Sách kỹ năng làm chìa khóa, để ta tìm xem sao.', 288, 2, 'Đến thủ thư để tìm bản vẽ thiết kế có liên quan đến chiếc chìa khóa này.', NULL, -1, 160, 16, 1000, 1, 'Chìa Khóa Kỳ Dị 5-12', 1, NULL, 'all', 0, 0, NULL, 377, 'Ừ, đúng là làm từ titan thật, đến thủ thư tìm bản vẽ thiết kế liên quan đến chiếc chiếc khóa này, để chúng ta làm lại một cái mới.', '-1', 4, NULL, NULL),
	(158, NULL, 1, 1112, 0, 'Xin chào, ta có thể giúp gì ngươi không?', 277, 2, 'Nghe ngóng tin tức của nhà sưu tầm từ Cận Vệ  ngày ngày xem người ra ra vào vào .', NULL, -1, 160, 16, 1000, 1, 'Chìa Khóa Kỳ Dị 5-15', 1, NULL, 'all', 0, 0, NULL, 272, 'Nhìn hình dáng, rất giống với chìa khóa mê cung trong thế giới đáy hồ trong truyền thuyết, cùng với chiếc chìa khóa này còn có một bản vẽ, nghe nói nhà sưu tầm biết bản vẽ ở đâu, anh đi hỏi thăm xem tung tích của ông ấy.', '-1', 4, NULL, NULL),
	(161, NULL, 1, 63, 0, 'Làm khá lắm! Với khả năng của ngươi, sau này ắt sẽ thành công!', 430, 2, 'Đến Vân Đài tìm Sứ Giả Viên để bắt đầu rèn luyện', NULL, -1, 160, 3, 300, 1, 'Rèn Luyện Ở Khu Hoang Dã', 1, NULL, 'all', 0, 0, 'delBuffBid(cid, 313);', 239, 'Những thử thách thực sự đã chính thức bắt đầu, ngươi có thấy hồi hộp không? Đừng lo, ngươi có thể nhấp vào nút Auto ở góc phải bên dưới, hệ thống sẽ tự động giúp ngươi đánh quái.', '-1', 1, NULL, NULL),
	(163, NULL, 1, 345, 0, 'Ta cũng chẳng biết nói gì hơn.', 456, 2, 'Báo chân tướng sự việc cho Edward ở Đông Xuất Vân.', NULL, -1, 160, 8, 200, 1, 'Âm Mưu Bại Lộ', 1, NULL, 'all', 0, 0, NULL, 433, 'Thì ra là thế… Chất độc của bọn Nấm độc có khả năng hóa giải cà rốt, khiến cho thức ăn của Bang Răng Cửa trở nên ngon hơn… Ngươi hãy đi báo cho Edward biết đi.', '-1', 1, NULL, NULL),
	(165, NULL, 1, 114, 0, 'Nhớ đọc cho kỹ phần giới thiệu nhiệm vụ đấy.', 233, 2, 'Nhận sự ủy thác điều tra thực phẩm nhiễm độc và đi hỏi ông chủ tiệm thuốc tình hình cụ thể.', NULL, -1, 160, 6, 200, 1, 'Điều Tra Chất Độc', 2, NULL, 'all', 0, 0, NULL, 233, 'Đợi ta giám định xem sao… Hả? Nấm Lục sao lại có độc? Mà lại còn là loại độc tính rất kỳ là nữa! Xem ra việc này không thể xem thường.', '-1', 1, NULL, NULL),
	(169, NULL, 1, 135, 0, 'Không hổ danh là thành viên Đông Huyền, ta phục rồi.', 456, 2, 'Đợi thợ săn Edward suy nghĩ xong rồi trò chuyện với ông ta', NULL, -1, 160, 6, 1500, 1, 'Đánh Đuổi Bọn Phá Hoại', 1, NULL, 'all', 0, 0, NULL, 456, 'Sao nhanh vậy? Ta vẫn còn cần thêm thời gian suy nghĩ. Hay là ngươi giúp ta đánh đuổi thêm bọn Thỏ Lưu Manh, Nấm Bướm Hồng và Nấm Xanh nhé, ta nghĩ chúng cũng có liên quan đến bọn Lang Thang đấy.', '-1', 1, NULL, NULL),
	(171, NULL, 1, 379, 0, 'Bột phấn thần bí? Để ta xem một chút.', 233, 2, 'Đến chỗ ông chủ Vương tiệm thuốc ở Xuất Vân Thôn hỏi thăm về phấn rơi ra từ Nấm Vương.', NULL, -1, 160, 8, 200, 1, 'Hỏi Chủ Tiệm Thuốc', 1, NULL, 'all', 0, 0, NULL, 456, 'Cái gì? Cái nấm to thế đã bị ngươi đánh bại rồi à?Ngươi quả thật không đơn giản. Phải rồi, cái bột kỳ quái trên người ngươi là thứ gì thế? Mau đến tiệm thuốc của ông chủ Vương, chắc chắn sẽ có câu trả lời.', '-1', 1, NULL, NULL),
	(173, NULL, 1, 448, 0, 'Cháu, chắc là tân thủ trong Xuất Vân Thôn cử đến, thật may đúng lúc ông đang có việc cần nhờ.', 434, 2, 'Đến Thiện Tĩnh Địa tìm trưởng lão Vô Ưu,nghe nói ông ấy cần giúp đỡ.', NULL, -1, 160, 8, 200, 1, 'Gặp Mặt Tộc Trưởng', 1, NULL, 'all', 0, 0, NULL, 455, 'Thì ra là thế! Ta phải thông báo ngay cho mọi người, gặp nấm lục vân đỏ thì tuyệt đối không được ăn, hy vọng thời gian sau sẽ chuyển biến tốt hơn. Phải rồi, trưởng lão ở Thiện Tĩnh Địa đang cần người, ta giới thiệu ngươi qua đó, thể hiện tốt vào nhé, nếu được trưởng lão yêu quý nhất nhì thì võ công của ngươi quả là vô tận.', '-1', 1, NULL, NULL),
	(10642, NULL, 1, 0, 0, 'Đa tạ ngươi!', 573, 2, 'Bắt 1 Xà Yêu Hắc Ám', NULL, -1, 160, 101, 0, 2, 'Bắt Xà Yêu Hắc Ám', 1, NULL, 'all', 0, 0, NULL, -1, 'Tiểu Hoa muốn có 1 Xà Yêu Hắc Ám, hãy giúp cô ấy bắt chúng!', '7-9', 7, NULL, NULL),
	(179, NULL, 1, 2128, 0, 'Thương hội bị cươp ở Thiên Lục Châu à, ghê gớm quá.', 462, 2, 'Giúp Phụ Trách Thương Đội báo cáo tin tức hàng hóa bị đánh cắp cho Vệ Sĩ Bàng Bối.', NULL, -1, 160, 15, 2000, 1, 'Thương Đội Bị Cướp', 1, NULL, 'all', 0, 0, NULL, 459, 'Ờ… thôi được rồi! Hàng hóa của thương hội mất sạch rồi. Hôm qua trên đường rất tốt, đột nhiên nổi trận gió to, ta đi tìm chỗ để nấp, kết quả khi quay lại không thấy hàng hóa đâu; đến lạc đà kéo xe cũng bị cuốn đi, ngươi đã thấy trận gió nào cuốn cả lạc đà đi chưa? Ta nghĩ chắc chắn có người cố ý làm thế để cướp hàng. Có thể giúp ta báo tin cho Cận Vệ thành Bàng Bối không? Để ông ta cho người đến điều tra.', '-1', 2, NULL, NULL),
	(183, NULL, 1, 19501, 0, 'ừ, cuối cùng hết tức giận rồi, suýt nữa thì quên mất không xem hàng hóa trong hòm có bị hỏng không.', 459, 2, 'giúp người thương nhân dạy cho Độc Nhãn Ốc Đảo một bài học vì đã cướp bóc thương đội, tiêu diệt xong 5 con thì quay về báo cáo với thương nhân.', NULL, -1, 160, 16, 10000, 1, 'Giáo Huấn Độc Nhãn Tinh', 1, NULL, 'all', 0, 0, NULL, 459, 'Tất cả là do bọn Độc Nhãn Ốc Đảo đáng chết, ta biết ngay là đám người nhảy nhót này lấy hàng mà, báo hại ta lo lắng suýt phát điên. Người anh em, giúp ta trị cho bọn nó một bài học. Khi về ta đãi ngươi món thịt thỏ rừng tươi ngon.', '-1', 2, NULL, NULL),
	(184, NULL, 1, 2660, 0, 'Ngươi tại sao lại quay lại ? Chẳng lẽ thương hội muốn ngươi trao phần thưởng cho ta?Ha Ha, đấy là ý gì vậy?', 458, 2, 'Giúp thương nhân hỏi thăm người hướng đạo lục châu về tập tính sinh hoạt của Độc Nhãn Ốc Đảo', NULL, -1, 160, 16, 2000, 1, 'Rương Rỗng', 1, NULL, 'all', 0, 0, NULL, 459, 'Lạy thánh thần! Ta đã nhìn thấy gì chứ nhỉ? Cái hòm trống không? Chuyện gì thế? Chẳng lẽ đám người đó giấu hết hàng hóa đi. Thiên Lục Châu rộng lớn như thế này,liệu có tìm ra được không? Này ngươi,ngươi nhất định phải giúp ta đi hỏi người hướng đạo kia. Anh ta chắc chắn biết bọn người đó giấu hàng hóa ở đâu.', '-1', 2, NULL, NULL),
	(189, NULL, 1, 3547, 0, 'a, cảm ơn thánh thần , cảm ơn công chúa Tuyết Liên phù hộ, cuối cùng không bị mất việc rồi,mau mau lại đối chiếu danh sách vật phẩm.', 459, 2, 'Đưa hàng hóa của thương hội đến cho Phụ Trách Thương Đội ở Thiên Lục Châu.', NULL, -1, 160, 16, 2000, 1, 'Nhận Được Hàng Hóa', 1, NULL, 'all', 0, 0, NULL, 460, 'Hàng hóa lấy được từ sa tặc? Ngươi nói là đống rác này hả? Còn nguyên ở đây này, mau cầm hết đi! Thật đáng kinh tởm, quả nhiên đi cướp một đống rác về. Lấy hết đồ rồi nhanh biến đi! Thật là tốn công tốn sức .', '-1', 2, NULL, NULL),
	(10640, NULL, 1, 0, 0, 'Đa tạ ngươi!', 573, 2, 'Bắt 1 con Dơi U Minh', NULL, -1, 160, 101, 0, 2, 'Bắt Dơi U Minh', 1, NULL, 'all', 0, 0, NULL, -1, 'Tiểu Hoa muốn có 1 con Đơi U Minh, hãy giúp cô ấy bắt chúng!', '7-9', 7, NULL, NULL),
	(682, NULL, 1, 0, 0, 'Đa tạ ngươi', 336, 2, 'Tiêu diệt 50 con Thủ Vệ Sói Mẹ', NULL, 3, 49, 46, 5000, 2, 'Truy Nã Thủ Vệ Sói Mẹ', 1, NULL, 'all', 0, 0, NULL, 336, 'tiêu diệt 50 con Thủ Vệ Sói Mẹ', '-1', 6, NULL, NULL),
	(191, NULL, 1, 3901, 0, 'Tiểu quỷ, ta biết ngươi sẽ không đến nữa, xem ra ngươi không hiểu Khổng Lồ chúng ta.', 461, 2, 'Đòi Thủ Lĩnh Sa Tặc ở Thiên Lục Châu Kiếm Mật Thuật Kiếm bị mất.', NULL, -1, 160, 16, 2000, 1, 'Gặp Lại Sa Tặc', 1, NULL, 'all', 0, 0, NULL, 460, 'Hỡi loài người! Hên cho ngươi là hôm nay ta rất vui nên không Tiêu diệt ngươi, cảnh cáo các ngươi một lần nữa, ta không thấy bất kỳ cái thuật mật kiếm nào của các ngươi.Ngươi nên đi tìm Thủ Lĩnh Sa Tặc khôn ranh đi!', '-1', 2, NULL, NULL),
	(193, NULL, 1, 88639, 0, 'Ta đã nói với ngươi bao nhiêu lần rồi, đừng có bị sa tặc xảo trá lừa! Tại sao ngươi lại không tin, vũ khí của chúng ta đều là trượng đá, vũ khí của các ngươi thì có tác dụng gì với chúng ta.', 460, 2, 'Sau khi đánh bại Thủ Lĩnh Khổng Lồ, nói chuyện với Thủ Lĩnh Sa Tặc', NULL, -1, 160, 16, 35000, 1, 'Đánh Bại Thủ Lĩnh Khổng Lồ', 1, NULL, 'all', 0, 0, NULL, 461, 'Vậy thì giúp ta xử lý Thủ Lĩnh Khổng Lồ đi, lão gia ta từ lâu thấy hắn chướng mắt lắm rồi. Ngươi yên tâm, làm cho đẹp, ta sẽ tiết lộ tin tức cho ngươi.', '-1', 2, NULL, NULL),
	(194, NULL, 1, 3170, 0, '(cơ quan mở ra, để lộ một thanh kiếm) Mau giao cho thương nhân đi.', 701, 2, 'Sách da dê chỉ rõ đến Thiên Lục Châu ( 213,74) tìm mật thuật kiếm đã mất.', NULL, -1, 160, 16, 2000, 1, 'Kiếm Bị Giấu', 1, NULL, 'all', 0, 0, NULL, -1, '0', '-1', 2, NULL, NULL),
	(198, NULL, 1, 34866, 0, 'Làm rất tốt, số hải tinh còn lại ta sẽ thuê người xử lý tiếp.', 411, 2, 'Tiêu diệt 10 con Tiểu Hải Tinh ở Lê Dương Bắc, sau đó báo cáo với Trưởng Thương Hội Đông Huyền.', NULL, -1, 160, 16, 10000, 1, 'Thông Thoáng Thương Lộ', 1, NULL, 'all', 0, 0, NULL, 411, 'Dù gì ngươi cũng lợi hại như thế, đám quái vật Lê Dương Bắc tuyệt đối không phải là đối thủ của ngươi rồi. Nói thật nhé, gần đây thuyền của thương hội ta bị bắt nạt rất thê thảm. Nhất là đám hải tinh,chúng nó giơ tay ra một cái là cả thuyền bị thủng. Thuyền cứ thế chìm dần xuống, ngươi coi thế có tức không?Mong ngươi tiêu diệt đám hải tinh đó đi, cũng coi như giúp đỡ mọi người mà.', '-1', 2, NULL, NULL),
	(201, NULL, 1, 38036, 0, 'Rất cảm ơn sự giúp đỡ của ngươi, nhờ có ngươi mà chúng ta  mới dẹp được sự uy hiếp của đám Ốc Tiểu Binh.', 277, 2, 'Giúp Cận Vệ Đông Huyền tiêu diệt 30 Ốc Tiểu Binh ở Lê Dương Bắc,  sau đó quay về tìm gặp Cận Vệ.', NULL, -1, 160, 16, 10000, 1, 'Giúp Đỡ Vệ Sĩ', 1, NULL, 'all', 0, 0, NULL, 277, 'Xin lỗi, việc này ta không thể giúp ngươi được. Tuy ta rất tự tin vào thân thủ của mình, nhưng ta phải chịu trách nhiệm trước mạng sống binh lính của ta. Nếu như ngươi thật sự hạ quyết tâm thì hai ta cùng làm, tiêu diệt đám Ốc Tiểu Binh đe dọa an ninh trong thành,sau đó ta sẽ giúp ngươi thuyết phục vợ ta.', '-1', 2, NULL, NULL),
	(203, NULL, 1, 5072, 0, 'Lợi hại thật, đến chủ tiệm quần áo cũng bị ngươi thuyết phục rồi.', 411, 2, 'Đưa tin tốt lành đến Trưởng Thương Hội Đông Huyền.', NULL, -1, 160, 16, 2000, 1, 'Nhận Đơn Hàng', 1, NULL, 'all', 0, 0, NULL, 373, 'Được rồi, ta nhận đơn hàng của thương hội, về nói với Trưởng Thương Hội, qua thứ 2 thì đến lấy nhé.', '-1', 2, NULL, NULL),
	(208, NULL, 1, 6340, 0, 'Mùi thơm này… woa.., rượu mật ong lâu lắm không gặp, ô la ô la ô la, hít một cái thật là đã', 464, 2, 'Đưa rượu mật ong cho Thợ Mỏ ở Lạp Tuyết Địa', NULL, -1, 160, 16, 2000, 1, 'Giao Rượu Mật Ong', 1, NULL, 'all', 0, 0, NULL, 465, 'Của ông này, rượu mật ong thơm lừng nóng hổi, rượu ngon nhất của tiệm rượu Lạp Tuyết Địa', '-1', 2, NULL, NULL),
	(211, NULL, 1, 158480, 0, 'Áh… Cái … cái …cáo chương nhạc đấy ở chỗ ta, không phải Hổ Bì Dương lấy', 466, 2, 'Đánh bại Hổ Bì Dương Thích Hát ở Lạp Tuyết Địa, giúp Nghệ Nhân Lữ Hành lấy lại Chương Nhạc Cuối Cùng.', NULL, -1, 160, 16, 35000, 1, 'Chương Nhạc Cuối Cùng', 1, NULL, 'all', 0, 0, NULL, 466, 'Cái gì, ngươi đồng ý giúp ta, cảm ơn, cảm ơn, cảm ơn ngươi nhiêu lắm. Nghe ta nói tối qua khi ta ngồi viết nhạc có một Hổ Bì Dương cứ nhìn ta làm cho ta không được tự nhiên. Theo phản ánh linh cảm của nhà nghệ thuật , ta cho rằng có đến tám chín phần là do co dê đó đã lấy mất bản nhạc của ta.', '-1', 2, NULL, NULL),
	(213, NULL, 1, 47544, 0, 'Lần này hết bực rồi. Nhưng công cụ đào mỏ không còn, cần nghĩ cách làm một bộ công cụ mới', 464, 2, 'Giáo huấn 10 Độc Nhãn Xanh ở Lạp Tuyết Địa, sau đó báo cho Thợ Mỏ.', NULL, -1, 160, 16, 10000, 1, 'Lại Là Rương Rỗng', 1, NULL, 'all', 0, 0, NULL, 464, 'Thật không hổ danh là người của gia tộc, làm rất cừ. Đợi đã! Cái hòm này sao mà nhẹ thế? Là hòm không? Ngươi nói là Độc Nhãn Xanh chôn nó, thật là lũ người đáng chết. Mặc dù đã tìm được hòm bảo bối của ta…Nhưng không được. Không thể dung tha cho chúng, phiền ngươi hãy cho chúng một bài học.', '-1', 2, NULL, NULL),
	(216, NULL, 1, 7608, 0, 'Cái này rốt cuộc là do ai làm! Lại đào bới lung tung hết mỏ, vết tích này rỏ ràng là vết cuốc của ta, …lại còn chùy đá, chết rồi, rõ ràng là có ai đã dùng trộm công cụ của ta.', 464, 2, 'Đưa công cụ mới cho Thợ Mỏ', NULL, -1, 160, 16, 2000, 1, 'Giao Công Cụ Mới', 1, NULL, 'all', 0, 0, NULL, 467, 'Được rồi, xong rồi, một công cụ mỏ mới tinh, Này ngươi, gã không nỡ để anh tự móc túi đấy chứ, Cái này rất đắt, ha ha, yên tâm, không tính trên đầu ngươi đâu, đợi gã về ta sẽ đi tính nợ, lần này phải lấy đầy sọt quặng mới được.', '-1', 2, NULL, NULL),
	(219, NULL, 1, 3645, 0, 'Hóa ra bên trong lại có nhiều việc không thuận lợi như vậy, xem ra điều người đi quả là sự lựa chọng sáng suốt.', 411, 2, 'Đưa tin tức cho Trưởng Thương Hội Đông Huyền', NULL, -1, 160, 16, 2000, 1, 'Hoàn Thành ủy Thác', 1, NULL, 'all', 0, 0, NULL, 463, 'Ây à, người xem ta đã nói thì nói không dứt, ngươi hãy mau về nói với tiền bối thành Đông Huyền, ba hôm nữa bảo đảm quặng sẽ chở tới nơi.', '-1', 2, NULL, NULL),
	(223, NULL, 1, 4308, 0, 'Việc thay đổi khác thường của  đảo Lê Dương ta đã nghe qua, Ta đã điều động người đi hết rồi…', 277, 2, 'Giúp quan tuần tra chuyển lời đến Trưởng Cận Vệ Đông Huyền', NULL, -1, 160, 16, 2000, 1, 'Cầu Cứu Chi Viện', 1, NULL, 'all', 0, 0, NULL, 468, 'Không được, cần bình tĩnh, bình tĩnh một chút…Thì ra việc này không đơn gỉan như ta nghĩ, cần cầu cứu sự trợ giúp của qua trị an thôi. Này người bạn trẻ, việc của thương hội giờ ta không giúp được. Nếu như ngươi muốn giúp, ta nghĩ ngươi nên lấp tức thông báo cho Vệ Sĩ, để ông áy cử người đến điều tra trước.', '-1', 2, NULL, NULL),
	(7584, NULL, 1, 0, 0, 'Cảm ơn ngươi', 304, 2, 'Tìm Nem ', NULL, -1, 160, 40, 0, 2, 'Tìm Nem', 1, NULL, 'all', 0, 0, NULL, -1, 'Ta hơi đói, ngươi có thể giúp ta kiếm chút thức ăn được không?', '7-5', 7, NULL, NULL),
	(227, NULL, 1, 4971, 0, 'Thật là nước Lê Dương, thế mỗi ngày ta uống thứ gì đây, hix', 377, 2, 'Đưa Mẫu Nước Hồ cho nghiên cứu viên ở Đông Huyền Thành.', NULL, -1, 160, 16, 2000, 1, 'Lấy Mẫu Nước', 1, NULL, 'all', 0, 0, NULL, 468, 'Nguy hiểm quá, chút xíu nữa đã bị bạch tuộc nhấn chìm rồi, đợi giải quyết xong việc ta có thể cho ngươi thành món bạch tuộc nướng! Mau đưa mẫu nước này cho nghiên cứu viên, bảo ông ấy nhanh chóng tìm ra chân tướng.', '-1', 2, NULL, NULL),
	(230, NULL, 1, 49703, 0, 'Là bình thuốc, tại sao ốc đồng lại có thứ này?', 468, 2, 'Theo manh mối mà Quan Tuần Tra cung cấp, có thể tìm thấy gì đó trên người Ốc Vệ Sĩ ở Lê Dương Đảo, sau đó lập tức mang đến cho Quan Tuần Tra.', NULL, -1, 160, 16, 10000, 1, 'Thuốc Thần Bí', 1, NULL, 'all', 0, 0, NULL, 468, 'Nói đến việc kỳ quặc…đúng rồi, ta nghĩ ra rồi! trước đây không lâu, Cận Vệ ốc đồng bắt đầu tập trung thành bầy thành đội lại vất đồ xuống hồ, ta cứ nghĩ rằng là bọn chúng thả bùn xuống cơ! Được ngươi nhắc nhở, ta mới nhớ ra, hình như chất lượng nước thay đổi cũng là từ khi đấy! Xin ngươi hãy điều tra xem, có lẽ vấn đề nằm ở thứ mà Cận Vệ ốc đồng vất xuống.', '-1', 2, NULL, NULL),
	(231, NULL, 1, 5633, 0, 'Bình thuốc thần bí? Nhanh , nhanh nhanh nhanh cầm lại đây, việc có cảm hứng lại đến rồi, ha ha', 377, 2, 'Đưa bình thuốc thần bí cho nghiên cứu viên ở Đông Huyền Thành.', NULL, -1, 160, 16, 2000, 1, 'Tạm Biệt Nghiên Cứu Viên', 1, NULL, 'all', 0, 0, NULL, 468, 'Mau! Mau đưa thứ này cho nghiên cứu viên, để anh ấy mau chóng nghiên cứu', '-1', 2, NULL, NULL),
	(241, NULL, 1, 7621, 0, 'Sống rất tươi tốt? Ta nghĩ .', 470, 2, 'Lại đi tìm Người Chăn Cừu để lấy tin tức', NULL, -1, 160, 16, 2000, 1, 'Nguyên Nhân Héo Tàn', 1, NULL, 'all', 0, 0, NULL, 469, 'Hóa ra là như vậy..... Theo tình hình này cho thấy, hình như có một sinh vật hùng mạnh đã xâm chiếm năng lượn sinh tồn của chúng! Đúng rồi, Cây La Khắc Khắc chính là một loại! Tình hình cụ thể phải hỏi Người Chăn Cừu mới được, cần hỏi ông ta gần đây loài sinh vật nào sống tươi tốt nhất.', '-1', 2, NULL, NULL),
	(245, NULL, 1, 66269, 0, 'Làm rất tốt', 469, 2, 'Để pha chế thuốc giải, đầu tiên cần 10 Cành Cây Khiết Tịnh giao cho Dược Sĩ, bạn có thể lấy trên thân Cổ Thụ Lão Yêu tại Quang Bình Nguyên ', NULL, -1, 160, 16, 10000, 1, 'Cành Cây Thuần Khiết', 1, NULL, 'all', 0, 0, NULL, 469, 'Sự việc đã được giải quyết rồi, như vậy ta tuân thủ lời thề của ta, trước tiên phân tích cho anh thành phần của lọ thuốc này. Theo hiểu biết của ta đối với dược phẩm, thì nó được làm từ rất nhiều loại sinh vật tiến hóa, nhưng không có sức sống ổn định. Kết quả đem lại là nâng cao sức phân liệt tế bào trong thời gian ngắn, như vậy cũng có nghĩa là sẽ chết trong thời gian ngắn. Dùng thuốc này có thể đạt được năng lượng lớn rất nhanh, hoặc nhiều đơn vị sức mạnh khác. Thôi không phải nhiều lời, đàu tiên anh phải làm là lấy 10 phần Cành Cây Khiết Tịnh trên Cổ Thụ Lão Yêu. Đấy là các thứ cơ bản để làm thuốc giải độc.', '-1', 2, NULL, NULL),
	(248, NULL, 1, 8616, 0, 'Người đã về rồi, có lây được thuốc giải đặc chế không? Đây là tin tốt nhất trong mấy ngày hôm nay', 468, 2, 'Đưa thuốc giải đặc chế cho quan tuần tra Lê Dương ', NULL, -1, 160, 16, 2000, 1, 'Thuốc Giải', 1, NULL, 'all', 0, 0, NULL, 469, 'Cho anh, đây là lọ thuốc giải độc kỳ quái do Dược Sĩ chuyên tạo ra đừng lo không có hiệu quả, người làm ra lọ thuốc này rất giỏi, nhưng bản đại gia càng là thiên tài! Ha ha, chỉ cần bỏ thuốc vào nơi ngươi cần nó sẽ phát huy hết tác dụng! Tất nhiên trước khi bỏ thuốc ra dùng cần phải mở nút. ha ha', '-1', 2, NULL, NULL),
	(250, NULL, 1, 9278, 0, 'Người bạn trẻ, có vấn đề gì vậy, hộp kim loại, thật là thứ ít nhìn thấy, ta phải nhĩn kỹ một chút.', 416, 2, 'Đưa hộp kim loại kỳ dị cho Tiến Sĩ Điên Harry thành Đông Huyền', NULL, -1, 160, 16, 2000, 1, 'Lần Đầu Gặp Tiến Sĩ', 1, NULL, 'all', 0, 0, NULL, 468, 'Cái đồ này nhìn rất kỳ quái, chắc chỉ có chuyên gia mới biết dùng. Cầm nó đếnTiến Sĩ Điên Harry thành Đông Huyền thôi, ông ấy là người am tường về máy móc và kim loại.', '-1', 2, NULL, NULL),
	(253, NULL, 1, 9610, 0, 'Thấy ngươi trưởng thành nhiều như vậy, hóa ra bên trong có nhiều việc phát sinh như thế, mặc dù nói như thế nào chúng ta vẫn nhớ những việc ngươi đã làm cho chúng ta.', 411, 2, 'Thông báo cho Trưởng Thương Hội Đông Huyền tin tức về thương lộ do đảo Lê Dương chuyển đi', NULL, -1, 160, 16, 2000, 1, 'Thông Đường Hoàn Tất', 1, NULL, 'all', 0, 0, NULL, 468, 'Việc điều tra thế lực hung ác cứ để cho ta làm, ta thề sẽ để chúng chịu tất cả nỗ khí của tộc Vô Ưu, đi báo cáo với hội Trưởng Thương Hội đi, nạo vét thương lộ hồ Lê Dương đã hoàn thành, có thể lập tức xuất phát rồi.', '-1', 2, NULL, NULL),
	(259, NULL, 1, 3079, 0, 'Cái gì, ta không nghe nhầm đấy chứ, một ngư phu hỏi mua cá?', 376, 2, 'Giúp ngư phu đến Nhà hàng Âu Dương thành Đông Huyền mua cá', NULL, -1, 160, 26, 1500, 1, 'Ngư Phu Mua Cá 11-1', 1, NULL, 'all', 0, 0, NULL, 438, 'Ta muốn ăn cá,a a a, ta muốn ăn cá, a a a a. Giúp ta đến chỗ Âu Dương thành Đông Huyền mua cá, ngoài bạch tuộc ra, cá gì cũng đươc, ta muốn ăn cá, a a a a.', '-1', 4, NULL, NULL),
	(260, NULL, 1, 3387, 0, 'Đen quá! (Còn đang nóng mau bảo Ngư Đân Tiểu Kim mang đi)', 438, 2, 'Tặng cá chép tây hồ cho Ngư Dân Lão Kim ở đảo Lê Dương', NULL, -1, 160, 26, 1500, 1, 'Ngư Phu Mua Cá 11-2', 1, NULL, 'all', 2666, 0, NULL, 376, 'Đây là cá chép ngon nhất của tiệm, giảm 20%, chỉ lấy 2666 bạc', '-1', 4, NULL, NULL),
	(652, NULL, 1, 0, 0, 'Cám ơn sự giúp đỡ của ngươi', 448, 2, 'Tiêu diệt 25 con Hổ Bì Dương', NULL, 3, 25, 21, 2500, 1, 'Mối Nguy Tiên Lạp', 1, NULL, 'all', 0, 0, NULL, 448, 'Gần đây Hổ Bì Dương thường đến làm loạn, giúp ta tiêu dịêt chúng', '-1', 6, NULL, NULL),
	(263, NULL, 1, 33862, 0, 'Gấu ở đây ăn chay, nhất định đầu có vấn đề.', 438, 2, 'Giúp Ngư Dân Lão Kim đi Tiên Lạp Thành điều tra xem trên thân Gấu Tuyết có cá không', NULL, -1, 160, 26, 3000, 1, 'Ngư Phu Mua Cá 11-5', 1, NULL, 'all', 0, 0, NULL, 438, 'Ta đã chịu đủ cái hồ này rồi, lúc thì bị đầu độc, lúc thì bị nhiễm đen, giúp ta đến Tiên Lạp Thành xem ở đấy có cá không. Có thể anh sẽ tìm được manh mối gì đó trên người Gấu Tuyết', '-1', 4, NULL, NULL),
	(265, NULL, 1, 4310, 0, 'Nhanh nhanh đưa ta, ta xem cá bột như thế nào.', 438, 2, 'Hỏa tốc đưa cá bột về cho Tiểu Kim  đảo Lê Dương', NULL, -1, 160, 26, 1500, 1, 'Ngư Phu Mua Cá 11-7', 1, NULL, 'all', 20000, 2, NULL, 275, 'Đây là 200 con cá bột mà như yêu cầu, mỗi con 100 lạng bạc, tổng cộng 20000 bạc', '-1', 4, NULL, NULL),
	(271, NULL, 1, 3481, 0, 'Thật hay quá, như vậy lần này chúng ta sẽ không sợ không có MP nữa rồi.', 277, 2, 'Thu  thập 9 Thuốc Viên Hồi Lực đưa cho đội Trưởng Cận Vệ thành Đông Huyền. Thuốc có thể mua ở tiệm thuốc', NULL, -1, 19, 10, 0, 1, 'Thuốc Viên Khẩn Cấp', 1, NULL, 'all', 0, 0, NULL, -1, 'Quái vật đột nhiên điên cuồng khiến người bị thương tăng cao, thuốc Cận Vệ không cung cấp đủ, đội Trưởng Cận Vệ thành Đông Huyền sưu tầm một số thuốc', '9-1', 9, NULL, NULL),
	(273, NULL, 1, 3481, 0, 'Người bạn trẻ, ngươi thật lợi hại, đến đội canh gác chúng ta cũng đều phục ngươi.', 277, 2, 'Tiêu diệt 20 Tiểu Sơn Quái . Sau đó  đến đội Cận Vệ thành Đông Huyền để lĩnh thưởng', NULL, -1, 19, 10, 0, 1, 'Bảo Vệ Người Chơi Mới', 1, NULL, 'all', 0, 0, NULL, -1, 'Để đảm bảo an toàn về sức khỏe và đi lại của quảng đại thành viên, chúng ta tuyển mộ chí sĩ và người tài giỏi tiễn trừ quái vật ở khu thành viên mới', '9-1', 9, NULL, NULL),
	(277, NULL, 1, 3481, 0, 'Thật là sự giúp đỡ lớn khi khó khăn', 275, 2, 'Thu được 19 miếng Da Động Vật từ thân Thỏ Lưu Manh và Bạch Tuộc Lục đưa cho chủ tiệm tạp hóa thành Đông Huyền', NULL, -1, 19, 10, 0, 1, 'Cung Không Đủ Cầu', 1, NULL, 'all', 0, 0, NULL, -1, 'Giúp chủ tiệm tạp hóa thành Đông Huyền sưu tầm da lông động vật, gần đây thành viên mới tăng nhiều không đủ da dê làm sách. Nhưng lông của động vật tất nhiên đều nằm trên thân thú rừng, haha', '9-1', 9, NULL, NULL),
	(279, NULL, 1, 3481, 0, 'Thật là sự giúp đỡ lớn khi khó khăn', 274, 2, 'Thu 18 Kim Loại Gỉ trên người Sa Tặc Cuồng Phong và Kẻ Lang Thang đưa cho Mark tiệm vũ khí thành Đông Huyền', NULL, -1, 19, 10, 0, 1, 'Thỉnh Cầu Của Mark', 1, NULL, 'all', 0, 0, NULL, -1, 'Giúp Mark tiệm vũ khí thành Đông Huyền sưu tầm một ít kim loại, gần đây thành viên mới tăng nhiều kim loại luyện vũ khí không đủ dùng', '9-1', 9, NULL, NULL),
	(280, NULL, 1, 3481, 0, 'Thật là sự giúp đỡ lớn khi khó khăn', 304, 2, 'Thu thập 19 Ngọc Vụn đưa cho Khả Vi Nhi tiệm trang sức thành Đông Huyền, nghe nói trên thân Tiểu Hải Tinh ở Lê Dương Bắc và Cát Hải Tinh ở Thiên Lục Châu cũng có ngọc này.', NULL, -1, 19, 10, 0, 1, 'Xin Giúp Đỡ Khẩn Cấp', 1, NULL, 'all', 0, 0, NULL, -1, 'Giúp Khả Vi  tiệm trang sức thành Đông Huyền sưu tầm một ít ngọc vụn, gần đây thành viên mới tăng nhiều ngọc làm trang sức không đủ dùng', '9-1', 9, NULL, NULL),
	(282, NULL, 1, 3481, 0, 'Rất nhiều thú cưng đáng yêu', 280, 2, 'Giúp Tôn Lệ ở tiệm Pet bắt 1 Nấm Đông Cô ở Vân Đài, Hỏa Kê ở Thiện Tĩnh Địa', NULL, -1, 19, 10, 0, 1, 'Nhà Của Pet', 1, NULL, 'all', 0, 0, NULL, -1, 'Tôn Lệ ở tiệm Pet thành Đông Huyền cần một số thú cưng mới để đáp ứng được nhu cầu của thành viên mới', '9-1', 9, NULL, NULL),
