	(749, 'Ngẫu nhiên nhận được 2 nguyên liệu và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím<cam) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 18200, 0, 'Vất vả rồi, nhờ có bằng hữu mà Lê Dương Thôn có thể khôi phục lại được thanh bình.', 454, 2, 'Tiêu diệt Hồ Tặc ở Lê Dương Thôn, đồng thời mang theo vật chứng giao cho Vệ Sĩ để chứng minh. Tiêu diệt Hồ Tặc Lê Dương và thu thập 20 Huy Hiệu của Hồ Tặc.', NULL, -1, 59, 50, 0, 2, 'Hồ Tặc Hung Dữ', 1, NULL, 'all', 0, 0, NULL, -1, 'Lẽ ra Lê Dương Thôn rất yên tĩnh bỗng nhiên xuất hiện rất nhiều hồ tặc, chúng ta cần phải tiêu dịêt chúng, bọn hồ tặc này giống sa tặc của Thiên Lục Châu', '9-5', 9, NULL, NULL),
	(1093, NULL, 1, 6000, 0, 'Đa tạ ngươi..hihi…', 603, 2, '  Đoạt lại Máy Thăm Dò từ Thỏ Hoang Điên Loạn ở Kỵ Bình Nguyên.', NULL, -1, 160, 31, 8000, 2, 'Cát Bụi Đường Xa 9-2', 1, NULL, 'all', 0, 0, NULL, 603, 'A A A. thì ta thành chủ phái đến, thành thật xin lổi, trước khi ngươi đến đây, lMáy thăm dò của ta đã bi bọn Thỏ Hoang Điên Loạn cướp đi,thế...ngươi giúp ta được chứ...', '-1', 4, NULL, NULL),
	(750, 'Ngẫu nhiên nhận được 2 nguyên liệu trang bị và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 18200, 0, 'Chúng ta nhất định phải cho bọn yêu quái này một đả kích thật lớn để chúng biết chúng ta cũng không phải dễ bị khi dễ', 454, 2, 'Tiêu diệt 15 con Hấp Huyết Hải Tinh ở Lê Dương Thôn và 15 con U Hồn Ma Nữ ở Hư Không Mạc, sau đó đến chỗ Vệ Sĩ nhận thưởng.', NULL, -1, 59, 50, 0, 2, 'Tiên Phát Chế Nhân', 1, NULL, 'all', 0, 0, NULL, -1, 'Hiện nay chúng ta đã bị mai phục, chúng ta cần phải tiêu diệt bọn quái vật này trước', '9-5', 9, NULL, NULL),
	(752, 'Ngẫu nhiên nhận được 2 nguyên liệu và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím<cam) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 18200, 0, 'Mặc dù đào mộ cổ nhân không phải là việc tốt lành gì, nhưng tội cũng không đến nỗi phải chết!', 454, 2, 'Tiêu diệt Tiểu Cương Thi ở Hư Không Mạc, sau đó đến chỗ Vệ Sĩ Lê Dương Thôn nhận thưởng.', NULL, -1, 59, 50, 0, 2, 'Gieo Gió Gặt Bão', 1, NULL, 'all', 0, 0, NULL, -1, 'Tiểu Cương Thi ở Hư Không Mạc, đã có 1 đội ngũ thám hiểm chết trong tay hắn, chúng ta cần phải tiêu diệt chúng để không làm nguy hại', '9-5', 9, NULL, NULL),
