	(1443, 'Ngẫu nhiên nhận được 2 nguyên liệu trang bị và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 29537, 0, 'Cám ơn, bây giờ những con Pet đáng yêu, càng ngày càng được hoan nghênh a!', 523, 2, 'Bắt 1 Ong Cửu Li, 1 Hồ Điệp, 1 Xương Rồng Tinh và 1 Hổ Ruồi, sau khi hoàn thành thì đem giao cho chủ tiệm Pet Tiên Lạp.', NULL, -1, 79, 70, 0, 2, 'Nhu Cầu Của Tiệm Pet', 1, NULL, 'all', 0, 0, NULL, -1, 'Tiệm Pet ở Tiên Lạp cần dùng quái vật của Ngọc Phong Lâm để hóa thành Pet, nhờ các dũng sĩ đi bắt chúng về giao cho ông chủ tiệm Pet.', '9-7', 9, NULL, NULL),
	(1444, 'Ngẫu nhiên nhận được 2 nguyên liệu trang bị và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 29537, 0, 'Khá lắm khá lắm, quả không hỗ danh một chức học trưởng, ha ha!', 272, 2, 'Giúp thành viên mới tiêu diệt 1 Thủ Lĩnh Khổng Lồ, 1 Thủ Lĩnh Sa Tặc và 1 Hổ Bì Dương Thích Hát, sau khi hoàn thành thì báo cho tộc trưởng Bối Tư.', NULL, -1, 200, 200, 0, 2, 'Giúp Đỡ Người Khác Là Niềm Vui', 1, NULL, 'all', 0, 0, NULL, -1, 'Tộc trưởng Bối Tư hy vọng ngươi sẽ có kinh nghiệm mới trong phương diện chiến thuật.', '9-7', 9, NULL, NULL),
	(1446, NULL, 1, 36870, 0, 'Ngươi rốt cuộc đã tới', 435, 2, 'Tới Bàng Bối tìm Bàng Bối thành chủ.', NULL, -1, 160, 66, 40000, 2, 'Một Dòng Suối Khác 11-1', 1, NULL, 'all', 0, 0, NULL, 435, 'Bàng Bối thành lại gặp rắc rối, trong tất cả thành viên của Bàng Bối chỉ định ngươi phải đi hổ trợ, xem ra rất coi trọng ngươi, hãy thể hiện tốt nhé.', '-1', 4, NULL, NULL),
	(1447, NULL, 1, 36870, 0, 'Đã rất lâu không gặp bằng hữu của ta', 509, 2, 'Tới gặp danh y ở Bàng Bối thành để tìm hiểu tình hình của thuốc giải.', NULL, -1, 160, 66, 40000, 2, 'Một Dòng Suối Khác 11-2', 1, NULL, 'all', 0, 0, NULL, 435, 'Vấn đề lần này thật khó khăn, đêm qua thức uống trong thành phát hiện có vấn đề, ai uống nước đều bị ngộ độc, nguồn nước ở khu vực Bàng Bối rất quý giá, không biết ai làm thủ đoạn này, ngươi hãy tìm dược sư  để lấy thuốc giải về phối thuốc.', '-1', 4, NULL, NULL),
	(1448, NULL, 1, 221223, 0, 'Động tác của ngươi cũng còn nhanh chóng như trước', 509, 2, 'Giúp y sĩ thu thập đuôi xà vương và mũi của Hề Ác Ma ở Cổ Đạo.', NULL, -1, 160, 66, 120000, 2, 'Một Dòng Suối Khác 11-3', 1, NULL, 'all', 0, 0, NULL, 509, 'Hmm … Ta dám khẳng định, ngộ độc lần này không phải do tự nhiên gây ra, chúng ta đã bỏ qua 1 điều, chúng ta nên phối thuốc giải, Ta cần có đuôi của xà vương và 10 cái mũi của Hề Ác Ma', '-1', 4, NULL, NULL),
	(1450, NULL, 1, 36870, 0, 'Giải dược đã không thành vấn đề', 462, 2, 'Đi tìm đội Trưởng Cận Vệ hỏi về tình hình ô nhiễm nguồn nước.', NULL, -1, 160, 66, 40000, 2, 'Một Dòng Suối Khác 11-5', 1, NULL, 'all', 0, 0, NULL, 462, 'Cận vệ đối với cuộc điều tra ô nhiễm đã có tiến triễn, hãy đi gặp hắn thẳm vấn xem sao.', '-1', 4, NULL, NULL),
	(1452, NULL, 1, 36870, 0, 'Để ta nghĩ lại xem', 311, 2, 'Đến Linh Vũ Tộc hỏi về phương pháp làm sạch nguồn nước.', NULL, -1, 160, 66, 40000, 2, 'Một Dòng Suối Khác 11-7', 1, NULL, 'all', 0, 0, NULL, 462, 'Tuy đạo mộc tặc đã diệt, nhưng nguồn nước ô nhiễm vẫn chưa hồi phục, Ta phải đi 1 chuyến Linh Vũ , hỏi trưởng lão coi có cách nào hồi phục nguồn nước tinh khiết .', '-1', 4, NULL, NULL),
	(1455, NULL, 1, 368706, 0, 'Ân, ta xác định Xà Yêu nhất định đang giữ thủy nguyên.', 4, 2, 'Thu thập 5 túi nước trên người Xà vương', NULL, -1, 160, 66, 120000, 2, 'Một Dòng Suối Khác 11-10', 1, NULL, 'all', 0, 0, NULL, 4, 'Ta đã điều tra, phát hiện bọn xà vương này đã ẩn giấu 1 nguồn nước, hãy tìm từ trên thân nó, sẽ có được manh mối gì.', '-1', 4, NULL, NULL),
	(1457, 'Phần thưởng không rõ', 1, 0, 3, 'Được, làm khá lắm, hãy mau đi tìm lối lên tầng 2, ta sẽ đợi ngươi ở đó.', 190, 2, 'Tiêu diệt Bất Tử Vương và Độc Xà Lãnh Chúa ở tầng 1', NULL, -1, 160, 60, 0, 2, 'Kho Báu Đại Mạc (1)', 1, NULL, 'all', 0, 0, NULL, 190, 'Dũng sĩ, rốt cuộc thì ngươi cũng đã vào bên trong Kim Tự Tháp, đây là tầng 1, nơi có sự xuất hiện của Bất Tử Vương và Độc Xà Lãnh Chúa, hãy giúp ta tiêu diệt chúng, chứng tỏ thực lực của ngươi.', '-1', 6, NULL, NULL),
	(1462, 'Phần thưởng không rõ', 1, 0, 1, 'Nếu đã chuẩn bị kỹ thì hãy bắt đầu vào tầng 5 đi, tốt nhất hãy đi cùng bạn bè của ngươi', 193, 2, 'Tìm Mảnh Vỡ Chìa Khóa ở tầng 4 giao cho Thị Nữ sửa chữa', NULL, -1, 160, 60, 0, 2, 'Kho Báu Đại Mạc (7)', 1, NULL, 'all', 0, 0, NULL, 193, 'Ngươi chính là dũng sĩ mà mọi người đang đồn đại đó ư? Lăng mộ chính của Lão Pháp Vương ở tầng 5, tiếng khóc của công chúa cũng phát ra từ đó, ngươi phải hết sức cẩn thận... À phải rồi, nếu muốn mở Thạch Quan thì phải có chìa khóa tương ứng, chài khóa này có ở tầng 4 nhưng đã bị vỡ thành nhiều mảnh, hãy đi tìm và giao cho ta. ta sẽ giúp ngươi sửa nó', '-1', 6, NULL, NULL),
	(3195, NULL, 1, 4255, 0, 'Nhớ xem cho kỹ đấy nhé!', 280, 2, 'Học các tri thứcliên quan đến việc phóng sinh pet. Các pet bắt được có loại tốt loại xấu, những pet không cần dùng đương nhiên phải thả đi để tránh chiếm chỗ trong túi pet. Thao tác rất đơn giản, nhấp vào nút Pet, sau đó chọn Pet muốn thả trong danh sách ', NULL, -1, 160, 11, 500, 1, 'Học Thả Pet', 1, NULL, 'all', 0, 0, NULL, 280, 'Các pet bắt được có loại tốt loại xấu, những pet không cần dùng đương nhiên phải thả đi để tránh chiếm chỗ trong túi pet. Thao tác rất đơn giản, nhấp vào nút Pet, sau đó chọn Pet muốn thả trong danh sách rồi nhấp nút Thả, tức thì pet này sẽ lập tức trở về với tự nhiên. Nếu là pet có phẩm chất 1.6 trở lên, hệ thống sẽ yêu cầu phải nhập mật khẩu cấp 2 thì mới có thể thả, vì đây là những pet quý.', '-1', 1, NULL, NULL),
	(1477, 'Ngẫu nhiên nhận được 2 nguyên liệu trang bị và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 29537, 0, 'Cám ơn ngươi, bằng hữu ngươi có hứng thú gia nhập đại đội trị an Tinh Linh Thành chúng ta không?', 295, 2, 'Tiêu diệt 20 Quỷ Tham Ăn, sau đó tìm Vệ Sĩ Tinh Linh báo cáo tình hình.', NULL, -1, 79, 70, 0, 2, 'Quỷ Tham Ăn', 1, NULL, 'all', 0, 0, NULL, -1, 'Tiêu diệt Tí Hon Đốn Gỗ tại Vân Lộc Sơn sau đó tìm Trưởng Cận Vệ Tinh Linh Thành báo cáo tình huống.', '9-7', 9, NULL, NULL),
