	(3012, NULL, 1, 79107, 0, 'Người thanh niên, cho ta xem thứ ở trên tay ngươi được không?', 98, 2, 'Thì ra hắn chẳng biết gì, lỗ to rồi, hay cứ quay lại Quân Cổ Đạo tiếp tục điều tra vậy', NULL, -1, 160, 81, 50000, 2, 'Câu Đố Hiền Triết 16-6', 1, NULL, 'all', 0, 0, NULL, 277, 'Ta đã nghiên cứu rất lâu nhưng vẫn chưa tìm ra được bí ẩn của nó, ngươi hãy tìm người khác thỉnh giáo đi.', '-1', 4, NULL, NULL),
	(3013, NULL, 1, 79107, 0, 'Phản ứng nhanh thật!', 98, 2, 'Vào Trúc Lâm tiêu diệt 60 Thỏ Chiến Tướng', NULL, -1, 160, 81, 50000, 2, 'Câu Đố Hiền Triết 16-7', 1, NULL, 'all', 0, 0, NULL, 98, 'Dường như ta đã thấy vật này trước đây rồi, để ta nghĩ lại xem. Gần đây Thỏ Chiến Tướng thường hay quấy phá, ngươi có đồng ý giúp ta xử lý không?', '-1', 4, NULL, NULL),
	(3014, NULL, 1, 79107, 0, 'Grrrr', 119, 2, 'Đi điều tra theo chỉ thị của Trúc Lâm Tiên Tử, cẩn thận mãnh thú xuất hiện', NULL, -1, 160, 81, 50000, 2, 'Câu Đố Hiền Triết 16-8', 1, NULL, 'all', 0, 0, NULL, 98, 'Nhiều năm trước, ta đã thấy qua vật này ở một nơi sâu trong rừng trúc, ngươi có thể đến đó tìm kiếm vận may.', '-1', 4, NULL, NULL),
	(3015, NULL, 1, 3006097, 0, 'Hu hu hu', 119, 2, 'Chiến thắng Trúc Lâm Mãnh Thú', NULL, -1, 160, 81, 500000, 2, 'Câu Đố Hiền Triết 16-9', 1, NULL, 'all', 0, 0, NULL, 119, 'Grrrr', '-1', 4, NULL, NULL),
	(3018, NULL, 1, 1526725, 0, 'Ừm, khá lắm, tha cho ngươi đó', 650, 2, 'Giúp ông lão bắt 1 Cây Nắp Ấm', NULL, -1, 160, 81, 150000, 2, 'Câu Đố Hiền Triết 16-12', 1, NULL, 'all', 0, 0, NULL, 650, 'Tiểu tử, ngươi muốn tìm gặp Lão Bất Tử trong truyền thuyết à? Ta sẽ chỉ cho ngươi, nhưng hãy giúp ta bắt 1 Cây Nắp Ấm đã.', '-1', 4, NULL, NULL),
	(3019, NULL, 1, 1898587, 0, 'Làm tốt lắm!', 650, 2, 'Để nghe ngóng được tin tức, hãy nhẫn nhịn, tiếp tục giúp ông lão tiêu diệt 60 Búp Bê Đầu To ', NULL, -1, 160, 81, 150000, 2, 'Câu Đố Hiền Triết 16-13', 1, NULL, 'all', 0, 0, NULL, 650, 'Tiểu tử, giúp ta tiêu diệt bọn Búp Bê trước cổng đi nào!', '-1', 4, NULL, NULL),
	(3021, NULL, 1, 3164313, 0, 'Người thanh niên, công phu khá đấy!', 118, 2, 'Chiến thắng Trúc Lâm Hiền Triết', NULL, -1, 160, 81, 500000, 2, 'Câu Đố Hiền Triết 16-15', 1, NULL, 'all', 0, 0, NULL, 118, 'Oa! Ngươi biết ám hiệu bí mật này! Lại đây, chúng ta cùng thử sức nào!', '-1', 4, NULL, NULL),
	(3023, NULL, 1, 79107, 0, 'Aaaa, lạnh quá, đau quá!', 120, 2, 'Đến Tuyết Lâm tìm Nhóm Tuần Tra, tìm hiểu nguyên do Băng Cung hỗn loạn.', NULL, -1, 160, 81, 50000, 2, 'Loạn Băng Cung 15-1', 1, NULL, 'all', 0, 0, NULL, 446, 'Gần đây có tin Băng Cung ở  Tây Cực Địa xảy ra một số chuyện, nhóm tuần tra ta phái đến đó cũng mất liên lạc, ta mong ngươi giúp ta đi tìm hiểu tình hình cụ thể ra sao.', '-1', 4, NULL, NULL),
	(3024, NULL, 1, 1898587, 0, 'Phù, an toàn rồi!', 120, 2, 'Giúp thành viên nhóm tuần tra đánh lùi 60 Tuyết Vực Mai Yêu đang bao vây', NULL, -1, 160, 81, 150000, 2, 'Loạn Băng Cung 15-2', 1, NULL, 'all', 0, 0, NULL, 120, 'Cứu mạng! Mau giúp ta với, lũ Mai Yêu này thật đáng ghét!', '-1', 4, NULL, NULL),
	(3026, NULL, 1, 79107, 0, 'Việc như thế nào?', 498, 2, 'Có dược dẫn rồi, mau quay về Tiên Lạp Thành gặp Danh Y Đắc Kỷ lấy thuốc.', NULL, -1, 160, 81, 50000, 2, 'Loạn Băng Cung 15-4', 1, NULL, 'all', 0, 0, NULL, 120, 'Tốt quá, có dược dẫn là tốt rồi. Dược phẩm mang đi đã dùng hết, hãy giúp ta về Tiên Lạp Thành lấy thêm một ít.', '-1', 4, NULL, NULL),
	(3027, NULL, 1, 79107, 0, 'Cuối cùng được cứu rồi!', 120, 2, 'Mau đem thuốc về cho thành viên nhóm tuần tra trị thương đi.', NULL, -1, 160, 81, 50000, 2, 'Loạn Băng Cung 15-5', 1, NULL, 'all', 0, 0, NULL, 498, 'Đây là tân dược ta vừa nghiên cứu được, nếu phối hợp với dược dẫn thì sẽ rất hiệu quả cho việc trị thương!', '-1', 4, NULL, NULL),
	(3029, NULL, 1, 79107, 0, 'Hả? Băng Cung?', 541, 2, 'Mang thư đến cho Tiên Lạp Thành Chủ phân tích tình hình', NULL, -1, 160, 81, 50000, 2, 'Loạn Băng Cung 15-7', 1, NULL, 'all', 0, 0, NULL, 120, 'Chắc chắn Băng Cung đã gặp chuyện! Mau đem thư này về báo cáo cho Tiên Lạp Thành Chủ.', '-1', 4, NULL, NULL),
	(3037, NULL, 1, 79107, 0, 'Làm rất tốt!', 446, 2, 'Loạn Băng Cung đã được dẹp yên, hãy quay về Tiên Lạp Thành báo cáo kết quả.', NULL, -1, 160, 81, 50000, 2, 'Loạn Băng Cung 15-15', 1, NULL, 'all', 0, 0, NULL, 105, 'Đa tạ thiếu hiệp đã giúp bình định phiến loạn.', '-1', 4, NULL, NULL),
	(3039, NULL, 1, 1740089, 0, 'Ồ, lão già đó quả không hổ danh, mới đó mà đã biết được suy nghĩ của ta, lần này được ăn ngon rồi!', 106, 2, 'Bắt 1 Thỏ Chiến Tướng giao cho Ảo Địa Hiền Triết', NULL, -1, 160, 86, 150000, 2, 'Di Tích Văn Minh Viễn Cổ 13-2', 1, NULL, 'all', 0, 0, NULL, 118, 'Lão già đó thèm lắm rồi, ngươi bắt cho hắn 1 Thỏ Chiến Tướng đi.', '-1', 4, NULL, NULL),
	(3040, NULL, 1, 1740089, 0, 'Tốt lắm, đúng là vật này, luôn lộ ra vẻ cổ quái.', 106, 2, 'Bắt 1 sinh vật bí ẩn hệ máy cho Hiền triết nghiên cứu', NULL, -1, 160, 86, 150000, 2, 'Di Tích Văn Minh Viễn Cổ 13-3', 1, NULL, 'all', 0, 0, NULL, 106, 'Ồ, mảnh đất này chứa đầy sự kỳ dị, dường như có mùi gì đó rất đặc biệt, thường xuyên ẩn hiện những vật thể không rõ ràng. Ngươi giúp ta tìm về đây 1 con, dường như chúng là máy móc thì phải', '-1', 4, NULL, NULL),
	(3042, NULL, 1, 2610133, 0, 'Khá lắm, phản ứng nhanh nhẹn, có việc gì muốn hỏi thì cứ nói.', 121, 2, 'Giúp Di Dân Viễn Cổ tiêu diệt 60 Bối Long đang làm loạn', NULL, -1, 160, 86, 150000, 2, 'Di Tích Văn Minh Viễn Cổ 13-5', 1, NULL, 'all', 0, 0, NULL, 121, 'Nhiều rồng quá, thật là phiền phức! Ngươi đến thật đúng lúc, có việc gì thì giúp ta giáo huấn chúng xong rồi nói.', '-1', 4, NULL, NULL),
	(7605, NULL, 1, 0, 0, 'Cảm ơn ngươi', 376, 2, 'Tìm 1 Mì Bò', NULL, -1, 160, 40, 0, 2, 'Tìm Mì Bò', 1, NULL, 'all', 0, 0, NULL, -1, 'Ta hơi đói, ngươi có thể giúp ta kiếm chút thức ăn được không?', '7-5', 7, NULL, NULL),
	(3046, NULL, 1, 217511, 0, 'Văn minh viễn cổ?', 118, 2, 'Mang Tiểu Thái Dương đến cho Hiền Triết nghiên cứu', NULL, -1, 160, 86, 50000, 2, 'Di Tích Văn Minh Viễn Cổ 13-9', 1, NULL, 'all', 0, 0, NULL, 106, 'Không ngờ lại có nền văn minh thần kỳ như vậy! Ngươi đưa Tiểu Thái Dương này cho Lão Bất Tử ở Trúc Lâm xem đi.', '-1', 4, NULL, NULL),
	(3048, NULL, 1, 2610133, 0, 'Làm xong rồi ư? Vậy hãy cầm lấy đi này!', 106, 2, 'Giúp Ảo Địa Hiền Triết đánh bại 60 Tí Hon Đào Đất', NULL, -1, 160, 86, 150000, 2, 'Di Tích Văn Minh Viễn Cổ 13-11', 1, NULL, 'all', 0, 0, NULL, 106, 'Muốn có được bảo bối của ta, giúp ta xử lý bọn Tí Hon phiền phức này trước đã!', '-1', 4, NULL, NULL),
	(3050, NULL, 1, 4350222, 0, 'Mãnh thú canh gác ư? Xem ra nền văn minh trong truyền thuyết này quả thực rất phát triển. Cảm ơn ngươi đã giúp ta nhiều việc như vậy, hãy nhận lấy phần quà này xem như lời cảm ơn nhé.', 106, 2, 'Đánh bại Viễn Cổ Thủ Hộ Thú', NULL, -1, 160, 86, 500000, 2, 'Di Tích Văn Minh Viễn Cổ 13-13', 1, NULL, 'all', 0, 0, NULL, 123, 'Kha kha', '-1', 4, NULL, NULL),
	(3067, NULL, 1, 6192018, 0, 'Nhanh thật!', 416, 2, 'Đến Kỳ Thạch Địa thu thập 20 Ốc Vít, Tiểu Thái Dương có thể đánh rơi.', NULL, -1, 160, 91, 150000, 2, 'Sửa Máy Ghi Âm', 1, NULL, 'all', 0, 0, NULL, 416, 'Ối? Sao không dùng được? À, thì ra linh kiện hongr rồi, ta sẽ sửa xong nhanh thôi, nhưng phải cần 20 Ốc Vít Tiểu Thái Dương ở Kỳ Thạch Địa. Ngươi có thể giúp ta đem về đây không?', '-1', 2, NULL, NULL),
	(3068, NULL, 1, 216334, 0, 'Máy Ghi Âm ư? Lần đầu tiên ta nghe thấy đấy!', 126, 2, 'Tiến Sĩ Ultra tặng Máy Ghi Âm cho bạn, hãy mau quay về tìm Tỵ Cốc Nhân đi.', NULL, -1, 160, 91, 50000, 2, 'Nhận Máy Ghi Âm', 1, NULL, 'all', 0, 0, NULL, 416, 'Tặng máy ghi âm cho ngươi này, ta giữ lại cũng không làm gì. (Đa tạ!)', '-1', 2, NULL, NULL),
	(3069, NULL, 1, 6490023, 0, 'Thật đúng là thông minh! Cách thế này cũng nghĩ ra được.', 669, 2, 'Dùng máy ghi âm để thu thập 99 Sư Tử Nộ Hống.', NULL, -1, 160, 91, 150000, 2, 'Thu thập Nộ Hống', 1, NULL, 'all', 0, 0, NULL, 126, 'Hay quá! Ngươi dùng xong rồi cho ta mượn máy ghi âm chơi vài ngày được không? Ngươi hỏi ta vì sao chưa từng thấy qua máy ghi âm mà lại biết được cách làm nhanh như vậy à? Đương nhiên là vì ta thông minh rồi!', '-1', 2, NULL, NULL),
	(3074, NULL, 1, 7057355, 0, '99 cái không thiếu cái nào!', 669, 2, 'Mang 99 Gai Xương Rồng Tinh về giao cho Lão Âu', NULL, -1, 160, 91, 150000, 2, 'Bạn Tốt', 1, NULL, 'all', 0, 0, NULL, 126, 'Ngươi là ngươi tốt của ta! Ta không đành lòng rời xa ngươi! Hu hu! Nhớ quay lại đây thăm ta nhé! Có vấn đề gì đều có thể đến tìm ta, ta thông minh mà! Hu hu!', '-1', 2, NULL, NULL),
	(3077, NULL, 1, 108167, 0, 'Kế hoạch này nguy hiểm quá! Để ta suy nghĩ thêm!', 272, 2, 'Tộc Trưởng Bối Tư có một kế hoạch mạo hiểm, Hắc lĩnh quân đoàn chưa biết độc trên người bạn đã được giải, vậy sao bạn không nhân cơ hội này xâm nhập vào làm nội gián trong quân đoàn?', NULL, -1, 160, 91, 50000, 2, 'Kế Hoạch Mạo Hiểm', 1, NULL, 'all', 0, 0, NULL, 272, 'Thì ra Danh Y ở Tinh Linh Thành đã giải độc cho con. Đây là vận may của con đó!', '-1', 2, NULL, NULL),
	(3079, NULL, 1, 3461345, 0, 'Khá lắm!', 128, 2, 'Tuân theo mệnh lệnh của Hỏa Ma Vương, đi bắt 1 Nham Quái về.', NULL, -1, 160, 91, 150000, 2, 'Bắt Nham Quái', 1, NULL, 'all', 0, 0, NULL, 128, 'Haha, tiểu tử, ngươi đến đây làm gì? (Ngươi trả lời: “Ta đến đây để nhận mệnh lệnh.”) Rất tốt! Linh Lan Tà Tâm làm rất tốt! Hạ độc không tồi. Vậy được, ta ra lệnh cho ngươi bắt 1 Nham Quái về đây.', '-1', 2, NULL, NULL),
	(3080, NULL, 1, 5192018, 0, 'Biết nghe lời lắm!', 128, 2, 'Đến Linh Lan lấy Trầm Hương Mộc trên người Gấu Trúc Hồ Lô.', NULL, -1, 160, 91, 150000, 2, 'Gỗ Trầm Hương', 1, NULL, 'all', 0, 0, NULL, 128, 'Mệnh lệnh tiếp theo: Lấy Trầm Hương Mộc trên người Hùng Mao Ngủ Ngày.', '-1', 2, NULL, NULL),
	(3226, NULL, 1, 12465391, 0, 'Khá lắm', 218, 2, 'Tiêu diệt Vua Bùa Chú', NULL, -1, 160, 96, 500000, 2, 'Trục Trừ Yêu Ma 14-8', 1, NULL, 'all', 0, 0, NULL, 218, 'Lần này có 3 con yêu quái thoát ra, Vua Bùa Chú vẫn lảng vảng ngoài kia, mau đi tiêu diệt đi.', '-1', 4, NULL, NULL),
	(3086, NULL, 1, 216334, 0, 'Thứ này mà cũng lấy được.', 128, 2, 'Giao Thần Vận Thủy cho Hỏa Ma Vương', NULL, -1, 160, 91, 50000, 2, 'Thần Vận Thủy', 1, NULL, 'all', 0, 0, NULL, 435, 'Ta xem nào! Thì ra là cần Thần Vận Thủy, không vấn đề gì, cầm lấy đi, ta tin tưởng ngươi.', '-1', 2, NULL, NULL),
	(3089, NULL, 1, 6057355, 0, 'Kiến tươi quá!', 128, 2, 'Đến Linh Lan thu thập 40 Đầu Kiến Miệng Rộng.', NULL, -1, 160, 91, 150000, 2, 'Canh Kiến', 1, NULL, 'all', 0, 0, NULL, 128, 'Ngươi mệt rồi phải không? Ta không phải là người đối xử tệ bạc với thuộc hạ. Ngươi đến Linh Lan tìm 40 Đầu Kiến Miệng Rộng về đây, tối nay chúng ta nấu canh Đầu Kiến. (Thức ăn của quái vật thật ghê tởm…)', '-1', 2, NULL, NULL),
	(3090, NULL, 2, 8220696, 0, 'A!', 128, 2, 'Bạn bị Hỏa Ma Vương phát hiện ra là nội gián, xem ra khó tránh khỏi một trận đại chiến.', NULL, -1, 160, 91, 500000, 2, 'Hỏa Ma Vương', 1, NULL, 'all', 0, 0, NULL, 128, 'Sao ngươi không ăn? Lẽ nào ngươi…(Hỏa Ma Vương vung tay đánh về phía ngươi, ngươi né tránh theo bản năng) Quả nhiên, độc của ngươi đã được giải! Chẳng trách lần trước tấn công Bàng Bối Thành thất bại, thì ra là do ngươi báo tin!', '-1', 2, NULL, NULL),
	(3091, NULL, 1, 108167, 0, 'Bị phát hiện rồi ư?', 272, 2, 'Hỏa Ma Vương đang đánh giữa chừng thì bỏ chạy, hãy mau quay về báo cho Tộc Trưởng.', NULL, -1, 160, 91, 50000, 2, 'Hỏa Ma Vương Bỏ Chạy', 1, NULL, 'all', 0, 0, NULL, 128, 'Ngươi mãi mãi sẽ không biết được Hắc Lĩnh Thánh Chủ sống lại như thế nào đâu. Ngươi chờ mà xem!', '-1', 2, NULL, NULL),
	(3095, NULL, 1, 7355360, 0, 'Khá đấy!', 129, 2, 'Tiêu diệt 30 Thiên Diện Quái, Ma Linh, Phục Ma Thủ Vệ và Yêu Hồ.', NULL, -1, 160, 91, 150000, 2, 'Quét Sạch Quái Vật', 1, NULL, 'all', 0, 0, NULL, 129, 'Gần đây, Phục Ma Cốc xuất hiện thêm rất nhiều quái vật, con sau lại mạnh hơn con trước. Hãy giúp ta tiêu diệt chúng đi!', '-1', 2, NULL, NULL),
	(3096, NULL, 1, 4461345, 0, 'Làm rất tốt!', 129, 2, 'Bắt 1 Thiên Diện Quái', NULL, -1, 160, 91, 150000, 2, 'Bắt Thiên Diện Quái', 1, NULL, 'all', 0, 0, NULL, 129, 'Có thể bắt 1 Thiên Diện Quái về đây không? Ta muốn xét hỏi hắn.', '-1', 2, NULL, NULL),
	(3098, NULL, 1, 7922691, 0, 'Đa tạ ngươi! Ta đỡ nhiều rồi!', 295, 2, 'Thu thập Linh Dược Trấn Ma trên người Ma Linh.', NULL, -1, 160, 91, 150000, 2, 'Bệnh Tình Vệ Sĩ', 1, NULL, 'all', 0, 0, NULL, 290, 'Vệ Sĩ lâm trọng bệnh, chỉ có thể dùng 70 Linh Dược Trấn Ma để điều trị, tất cả nhờ vào ngươi đó!', '-1', 2, NULL, NULL),
	(3306, '""', 1, 238076, 0, 'Ngươi quả thực là người tài!', 457, 2, 'Phần thưởng của Trưởng Thương Hội', NULL, -1, 160, 91, 50000, 2, 'Thất Lạc Thần Bí 14-14', 1, NULL, 'all', 0, 0, NULL, 457, 'Rất cảm ơn, đây là phần thưởng của ngươi', '-1', 4, NULL, NULL),
	(3104, NULL, 1, 108167, 0, 'Đã bảo đừng cứu ta mà!', 126, 2, 'Hắc Lĩnh Ác Ma do mới hồi sinh nên sức lực còn yếu, hãy mau chóng nhân cơ hội này đưa Tỵ Cốc Nhân về Chỉ Phong Cốc.', NULL, -1, 160, 91, 50000, 2, 'Bỏ Chạy', 1, NULL, 'all', 0, 0, NULL, 130, '(Do vừa mới sống lại, Hắc Lĩnh Ác Ma còn hơi yếu, nhân cơ hội này, mọi người mau trốn khỏi đây đi.)', '-1', 2, NULL, NULL),
	(3108, NULL, 1, 108167, 0, 'Ôi… Tuyết Liên Công Chúa đã rời xa chúng ta hơn 200 năm rồi! Bây giờ chúng ta cần người quay trở lại!', 290, 2, 'Hỏi Tinh Linh Thành Chủ cách hồi sinh Công Chúa Tuyết Liên', NULL, -1, 160, 91, 50000, 2, 'Thám Thính Tinh Linh Thành', 1, NULL, 'all', 0, 0, NULL, 295, 'Ta chỉ nghe nói việc Tuyết Liên Công Chúa cứu cả thế giới chứ không hề biết bí mật Tuyết Liên Công Chúa sống lại như Tộc Trưởng nói. Ngươi nên đến bái kiến Thành Chủ đi, không ai hiểu rõ lịch sử của thế giới này bằng ông ta đâu!', '-1', 2, NULL, NULL),
	(3111, NULL, 1, 6490023, 0, 'Ngươi quả nhiên đã tìm được những vật liệu này! Quả thực quá lợi hại!', 291, 2, '10 Ngón Chân Thanh Oa, 10 Ma Thạch Hề, 30 Mặt Nạ Thiên Diện Quái. Trên công thức chỉ ghi những nguyên liệu này, lại không chỉ cho biết là đến đâu để tìm, bạn tự nghĩ cách đi vậy.', NULL, -1, 160, 91, 150000, 2, 'Công Thức Chìa Khóa 1', 1, NULL, 'all', 0, 0, NULL, -1, '10 Ngón Chân Thanh Oa, 10 Ma Thạch Hề, 30 Mặt Nạ Thiên Diện Quái. Trên công thức chỉ ghi những nguyên liệu này, lại không chỉ cho biết là đến đâu để tìm, các ngươi tự nghĩ cách đi vậy.', '-1', 2, NULL, NULL),
	(3112, NULL, 1, 108167, 0, 'Trên đường nhớ cẩn thận!', 418, 2, 'Tìm Thương Nhân Tiệm Thuốc để biết công thức chìa khóa thứ 2.', NULL, -1, 160, 91, 50000, 2, 'Công Thức Chủ Tiệm Thuốc', 1, NULL, 'all', 0, 0, NULL, 291, 'Công thức thứ 2 nằm ở chỗ tiệm thuốc, mau đến tìm ông ta đi!', '-1', 2, NULL, NULL),
	(3114, NULL, 1, 108167, 0, 'Để ta nghĩ xem có nên giao công thức cho ngươi không!', 423, 2, 'Tìm Thương Nhân Tiệm Pet để lấy công thức chìa khóa tiếp theo.', NULL, -1, 160, 91, 50000, 2, 'Công Thức Tiếp Theo', 1, NULL, 'all', 0, 0, NULL, 418, 'Tìm tiệm pet để đòi công thức tiếp theo đi!', '-1', 2, NULL, NULL),
	(3118, NULL, 1, 108167, 0, 'Thì ra có người còn nhớ đến ta!', 131, 2, 'Đến tìm Phục Ma Chiến Thần để lấy công thức chìa khóa tiếp theo.', NULL, -1, 160, 91, 50000, 2, 'Công Thức Phục Ma Thần Bí', 1, NULL, 'all', 0, 0, NULL, 423, 'Công thức tiếp theo nằm trong tay Phục Ma Chiến Thần ở Phục Ma Cốc, mau đến đó đi!', '-1', 2, NULL, NULL),
	(3119, NULL, 1, 3081670, 0, 'Đúng rồi Chính là nửa trang này!', 131, 2, 'Lấy lại nửa trang công thức từ tay Phục Ma Thủ Vệ.', NULL, -1, 160, 91, 150000, 2, 'Công Thức Bị Mất', 1, NULL, 'all', 0, 0, NULL, 131, 'Ngày công chúa ra đi thì trái tim ta cũng chết theo nàng, không ngờ lại có người muốn giúp nàng sống lại. Nhưng ta chỉ có 1 nửa công thức, nửa còn lại đã bị bọn Thủ Vệ dưới trướng cướp đi rồi, hãy giúp ta tìm lại nhé!', '-1', 2, NULL, NULL),
	(3122, NULL, 1, 108167, 0, 'Ta chỉ có công thức chìa khóa mà chẳng ai hiểu này!', 469, 2, 'Đến tìm Dược Sĩ để lấy công thức chìa khóa 5', NULL, -1, 160, 91, 50000, 2, 'Công Thức Chìa Khóa Y Thánh', 1, NULL, 'all', 0, 0, NULL, 131, 'Công thức cuối cùng, hãy đến tìm Dược Sĩ ở Tinh Linh Thành đi.', '-1', 2, NULL, NULL),
	(3124, NULL, 1, 108167, 0, '…', 132, 2, 'Từ chỗ của Tỵ Cốc Nhân biết được Y Tiên có thể đã đến Linh Lan.', NULL, -1, 160, 91, 50000, 2, 'Hành Tung Y Tiên', 1, NULL, 'all', 0, 0, NULL, 126, 'Y Tiên? Ý ngươi nói vị đại thúc khắp người toàn là mùi thuốc ấy à? Từ sau khi ông ta đến Linh Lan thì không thấy quay lại tìm ta nữa!', '-1', 2, NULL, NULL),
	(3125, NULL, 1, 108167, 0, 'Tìm được sư phụ thì tốt!', 469, 2, 'Phải nghĩ cách phục hồi ký ức lại cho Y Tiên. Nếu chưa có cách gì thì trước tiên hãy quay về báo cho Dược Sĩ trước đã!', NULL, -1, 160, 91, 50000, 2, 'Y Tiên Mất Ký Ức', 1, NULL, 'all', 0, 0, NULL, 132, 'Ngươi là ai? Ta là ai? (Xem ra Y Tiên đã mất đi trí nhớ )', '-1', 2, NULL, NULL),
	(3127, NULL, 1, 216334, 0, 'Chà! Thuốc này là do đồ đệ ta làm cho ta đây mà!', 132, 2, 'Đưa Thuốc Hồi Ký Ức cho Y Tiên uống', NULL, -1, 160, 91, 50000, 2, 'Thuồc Hồi Ký Ức', 1, NULL, 'all', 0, 0, NULL, 469, 'Mang nó qua cho Sư phụ đi! Đảm bảo thuốc vào là hết bệnh ngay.', '-1', 2, NULL, NULL),
	(3128, NULL, 1, 108167, 0, 'Đi cẩn thận nhé! Ta phải tiếp tục nghiên cứu loại thuốc này!', 132, 2, 'Đưa công thức chìa khóa 5 cho Y Tiên dịch.', NULL, -1, 160, 91, 50000, 2, 'Công Thưc Chìa Khóa Phiên Dịch', 1, NULL, 'all', 0, 0, NULL, 132, 'Không ngờ còn đánh thức cả Tuyết Liên Công Chúa nữa! Văn tự trên công thức là ngôn ngữ Tinh Linh cổ xưa, ta dịch cho ngươi nghe ngay!', '-1', 2, NULL, NULL),
	(3130, NULL, 1, 108167, 0, 'Sắp xong rồi! Cố đợi thêm lát nữa nhé!', 421, 2, 'Tìm Đại Thánh Hiền Fetocci để làm chìa khóa.', NULL, -1, 160, 91, 50000, 2, 'Chìa Khóa Bí Điển Truyền Thuyết', 1, NULL, 'all', 0, 0, NULL, 469, 'Đại Thánh Hiền đang chế tạo chìa khóa, đến tìm ông ta đi!', '-1', 2, NULL, NULL),
	(3131, NULL, 1, 108167, 0, 'Thần linh quả không chọn lầm ngươi!', 290, 2, 'Giao chìa khóa cho Tinh Linh Thành Chủ.', NULL, -1, 160, 91, 50000, 2, 'Tặng Chìa Khóa', 1, NULL, 'all', 0, 0, NULL, 421, 'Giao Chìa khóa cho Thành Chủ đi! Mọi người đang náo nức chờ đợi khoảnh khắc Bí Điển được mở ra đó!', '-1', 2, NULL, NULL),
	(3135, NULL, 1, 108167, 0, 'Nếu có tai nạn gì thì xin cứ giáng xuống đầu ta! Ta đồng ý!', 310, 2, 'Giao Thương Nghị Thư của Tộc Trưởng cho 6 vị Sứ Giả và mang thư hồi âm của họ về.', NULL, -1, 160, 91, 50000, 2, 'Đưa Thư Cho Đạo Sư Bàn Địa', 1, NULL, 'all', 0, 0, NULL, 272, 'Mời Sứ Giả 6 đại gia tộc đến cùng quyết định việc này vậy! Phiền ngươi chuyển 6 Thương Nghị Thư này đến cho họ và đem thư hồi âm của họ về cho ta.', '-1', 2, NULL, NULL),
	(3259, '""', 1, 249308, 0, 'Viên đá thật là kỳ lạ!', 421, 2, 'Đưa Quái Thạch cho Đại Thánh Hiền xem thử', NULL, -1, 160, 96, 50000, 2, 'Linh Hồn Lảng Vảng 14-11', 1, NULL, 'all', 0, 0, NULL, 131, 'Đây là vật gì? Ta cũng không rõ, Đại Hiền Triết thấy nhiều biết nhiều, hay là mang đến gặp ông ấy hỏi thử xem.', '-1', 4, NULL, NULL),
	(3137, NULL, 1, 108167, 0, 'Phương thuốc trị thương hữu hiệu nhất trên thế gian chính là tình yêu! Ta đồng ý!', 311, 2, 'Giao Thương Nghị Thư của Tộc Trưởng cho 6 vị Sứ Giả và mang thư hồi âm của họ về.', NULL, -1, 160, 91, 50000, 2, 'Đưa Thư Cho Đạo Sư Linh Vũ', 1, NULL, 'all', 0, 0, NULL, 272, 'Mời Sứ Giả 6 đại gia tộc đến cùng quyết định việc này vậy! Phiền ngươi chuyển 6 Thương Nghị Thư này đến cho họ và đem thư hồi âm của họ về cho ta.', '-1', 2, NULL, NULL),
	(3219, NULL, 1, 124654, 0, 'Ta biết', 129, 2, 'Tế Đàn ở đây trông thật quái dị, hãy đi tìm Hộ Cốc Thần Thú hỏi thử xem.', NULL, -1, 160, 96, 50000, 2, 'Trục Trừ Yêu Ma 14-1', 1, NULL, 'all', 0, 0, NULL, 130, 'Tế Đàn trông thật quái dị', '-1', 4, NULL, NULL),
	(3139, NULL, 1, 108167, 0, 'Ta thay mặt cho linh hồn vạn vật đồng ý!', 312, 2, 'Giao Thương Nghị Thư của Tộc Trưởng cho 6 vị Sứ Giả và mang thư hồi âm của họ về.', NULL, -1, 160, 91, 50000, 2, 'Đưa Thư Cho Đạo Sư Liêu Vân', 1, NULL, 'all', 0, 0, NULL, 272, 'Mời Sứ Giả 6 đại gia tộc đến cùng quyết định việc này vậy! Phiền ngươi chuyển 6 Thương Nghị Thư này đến cho họ và đem thư hồi âm của họ về cho ta.', '-1', 2, NULL, NULL),
	(3141, NULL, 1, 108167, 0, 'Xem ra mọi người đều đã hạ quyết tâm rồi!', 290, 2, 'Trả lời cho Tinh Linh Thành Chủ biết quyết định phục sinh Tuyết Liên Công Chúa.', NULL, -1, 160, 91, 50000, 2, 'Hồi Báo Tinh Linh Thành Chủ', 1, NULL, 'all', 0, 0, NULL, 272, 'Trở về nói với Tinh Linh Thành Chủ, cho dù dùng cách nào, Tuyết Liên Công Chúa nhất định phải sống lại!', '-1', 2, NULL, NULL),
	(3144, NULL, 1, 7355360, 0, 'Ngươi đúng là niềm tự hào của Đông Huyền!', 272, 2, 'Tìm Trí Thạch của Búp Bê Máy ở Quân Cổ Đạo.', NULL, -1, 160, 91, 150000, 2, 'Truy Tìm Trí Thạch', 1, NULL, 'all', 0, 0, NULL, 272, 'Trước mắt chỉ có 9 Trí Thạch hoành chỉnh, ta liên tục thu được 8 viên, viên còn lại nằm trên người Búp Bê Máy nào đó ở Quân Cổ Đạo, nhưng Búp Bê Máy nào cũng giống như nhau, thực tế rất khó có thể phân biệt ra nó ở trên người con nào! Phiền ngươi hãy kiên nhẫn để tìm ra nó nhé!', '-1', 2, NULL, NULL),
	(3146, NULL, 1, 216334, 0, 'Quả không hổ danh là dũng sĩ do Bí điển chọn ra!', 290, 2, 'Tộc Trưởng đem các mảnh vỡ luyện thành viên Trí Thạch thứ 10, hãy quay về Tinh Linh Thành xem hướng dẫn tiếp theo của Bí Điển.', NULL, -1, 160, 91, 50000, 2, 'Luyện Thành Trí Thạch', 1, NULL, 'all', 0, 0, NULL, 272, 'Ta đã khóa kỹ 10 Trí Thạch ở trong Bảo Hộp này rồi, đưa nó đến cho Bí Điển đi, xem chỉ thị của bước tiếp theo là gì!', '-1', 2, NULL, NULL),
	(3149, NULL, 1, 5192018, 0, 'Mùi hôi thối này có thể bảo vệ cho thân thể ta!', 133, 2, 'Đoạt lấy Ma Bào của Y Ma.', NULL, -1, 160, 91, 150000, 2, 'Chuẩn Bị Trước Triệu Hồi 1', 1, NULL, 'all', 0, 0, NULL, 133, 'Chúng ta hãy chuẩn bị để triệu hồi lần nữa! Chuẩn bị cho ta 1 Ma Bào, nó ở trên người của Y Ma!', '-1', 2, NULL, NULL),
	(3150, NULL, 1, 3461345, 0, 'Khá lắm!', 133, 2, 'Bắt 1 Lang Nha Vương', NULL, -1, 160, 91, 150000, 2, 'Chuẩn Bị Trước Triệu Hồi 2', 1, NULL, 'all', 0, 0, NULL, 133, 'Chuẩn bị 1 con lợn béo để tế các vong linh nào! Lợn chính là Lang Nha Vương đó.', '-1', 2, NULL, NULL),
	(3154, NULL, 1, 108167, 0, 'Nhớ mang phản hồi của họ lại cho ta đấy!', 272, 2, 'Tộc Trưởng nhờ bạn đưa 6 Thương Nghị Thư cho 6 vị Sứ Giả các tộc.', NULL, -1, 160, 91, 50000, 2, 'Tộc Trưởng Thương Nghị Thư', 1, NULL, 'all', 0, 0, NULL, 272, 'Ta phải thương nghị với các vị Sứ Giả của 6 tộc, cùng mọi người quyết định việc này. Ngươi hãy giúp ta chuyển 6 Thương Nghị Thư này cho họ nhé!', '-1', 2, NULL, NULL),
	(3156, NULL, 1, 0, 4, 'Đây là kim phiếu của ngươi!', 425, 2, 'Dùng Vải cấp 5 và 30 điểm năng nổ (điểm năng nổ có thể nhận được bằng việc thực hiện nhiệm vụ hàng ngày. Có thể xem thêm tại bảng [Cách chơi} - [Điểm năng nổ]) đến chỗ Thương Hội Trưởng đổi lấy Kim Phiếu', NULL, -1, 160, 40, 30, 3, '[Vải Cấp 5] Đổi Kim Phiếu', 1, NULL, 'all', 30, 13, NULL, 425, 'Gần đây Thương Hội Trưởng đang gấp rút thu thập nguyên liệu, một nguyên liệu thông thường có thể đổi lấy 30 kim phiếu, ngươi hãy mau nhân cơ hội này mà kiếm thật nhiều tiền đi!', '-1', 6, NULL, NULL),
