INSERT INTO data.data_tbl_quest (id, a_script_text, at, award_exp_re, color, complete_text, finish_npc, gender, info, is_rebirth, lm, max_level, min_level, money_num, money_type, name, pre_quest_type, qtest, req_class, rn, rt, script_give_up, start_npc, start_text, sub_type, type, start_grant_item, start_grant_qty) VALUES
	(30517, NULL, 1, 0, 0, 'Tốt lắm! Bọn ta đang cần thứ này!', 1069, 2, 'Đến Thiên Lục Châu bắt Độc Nhãn Ốc Đảo', NULL, -1, 160, 30, 0, 2, 'Bắt Pet', 1, NULL, 'all', 0, 0, NULL, -1, 'Để xây dựng bang hội cần một số pet này. Hãy mang về ngay nhé!', '7-2', 7, NULL, NULL),
	(3618, 'Phần thưởng kinh nghiệm', 1, 0, 4, 'Đây là phần thưởng của ngươi', 234, 2, 'Thu thập chữ "Chúc", "Mừng", "Sinh", "Nhật", "Vua", "Pháp", "Thuật" "Lần 4"để đổi quà', NULL, -1, 160, 30, 0, 1, 'Đổi chữ [Chúc Mừng Sinh Nhật Vua Pháp Thuật Lần 4]', 1, NULL, 'all', 0, 0, NULL, 234, 'Trong thời gian sự kiện, khi đánh quái ở khu vực hoang dã sẽ có cơ hội nhận được các chữ \"Chúc\", \"Mừng\", \"Sinh\", \"Nhật\", \"Vua\", \"Pháp\", \"Thuật\", \"Lần 4\", đem các chữ này đến gặp Thiên Sứ Sự Kiện sẽ nhận được phần thưởng. Số lượng chữ đổi mỗi lần càng nhiều thì phần thưởng sẽ càng lớn', '-1', 6, NULL, NULL),
	(5400, NULL, 1, 8039922, 0, 'Ta chính là biểu tưởng của cổ thành', 1690, 2, 'Đến trung tâm Cổ Thành điều tra', NULL, -1, 160, 141, 100000, 2, 'Điều Tra Di Tích', 1, NULL, 'all', 0, 0, NULL, 295, 'Trung tâm cổ thành là 1 nơi thần bí, chiến ma cũng từ đó mà sinh ra. Ngươi điều tra xem năng lượng ấy từ đâu ra và cách tiêu diệt như thế nào?', '-1', 2, NULL, NULL),
	(5402, NULL, 1, 8337697, 0, 'Thật không hổ danh là một thủ hộ tài ba!', 272, 2, 'Giao viên đá bí ẩn của điêu tượng cho Bối Tư thẩm định', NULL, -1, 160, 141, 100000, 2, 'Năng Lực Dũng Sĩ', 1, NULL, 'all', 0, 0, NULL, 1690, 'Ta đã bị yêu ma yếm khí vào người. Tuy có khả năng tinh hóa nhưng ma khí ngày càng dày đặc làm sức mạnh của ta cũng càng yếu đi. Ngươi có thể giúp ta giải trừ ma khí được không?', '-1', 2, NULL, NULL),
	(5405, NULL, 1, 9231021, 0, 'Ta biết rồi, đưa cho ta đi!', 421, 2, 'Tìm Đại Hiền Triết gia tăng sức mạnh', NULL, -1, 160, 141, 100000, 2, 'Duy Trì Năng Lượng', 1, NULL, 'all', 0, 0, NULL, 272, 'Quả nhiên không phải là Minh Trí Thạch thật, nhưng năng lượng của nó cũng đủ tiêu diệt bọn quỷ Cổ Thành. Ngươi đi tìm Đại Hiền Triết Tih Linh Thành để được hướng dẫn sử dụng sức mạnh này. Đừng làm  ta thất vọng nhé!', '-1', 2, NULL, NULL),
	(5409, NULL, 1, 0, 0, 'Được, khá lắm! Khá lắm!', 600, 2, 'Giao 500 Lệnh Bài Treo Thưởng, 5000 Điểm Chiến Tích chứng minh đủ tư cách là tông sư. (cấp độ nghề phải là  chuyên gia và học đủ tất cả kỹ năng tu luyện thì mới có thể hoàn thành nhiệm vụ)', NULL, -1, 200, 150, 0, 2, 'Nhiệm Vụ Nghề Tông Sư 3-1', 1, NULL, '|3|', 5000, 10, NULL, 311, 'Chỉ có thành viên có điểm chiến tích xuất sắc, có kinh nghiệm mới đủ tư cách nhận đẳng cấp nghề nghiệp. Trong thời gian ta thu nhận ngươi cần 500 Lệnh Bài Treo Thưởng và 5000 Điểm Chiến Tích', '-1', 1, NULL, NULL),
	(22108, NULL, 1, 0, 0, 'Tốt lắm! Bọn ta đang cần thứ này!', -1, 2, 'Đến Phục Ma Cốc bắt Yêu Hồ ', NULL, -1, 160, 100, 0, 2, 'Bắt Pet', 1, NULL, 'all', 0, 0, NULL, -1, 'Để xây dựng bang hội cần một số pet này. Hãy mang về ngay nhé!', '11-1', 11, NULL, NULL),
	(5374, NULL, 1, 2977749, 0, 'Ta cuũng mới vừa nhận được tin, thật bí hiểm!', 435, 2, 'Tìm Thành Chủ Bàng Bối quan sát tình hình Đăng Vân Địa', NULL, -1, 160, 141, 100000, 2, 'Câu Đố Đăng Vân', 1, NULL, 'all', 0, 0, NULL, 272, 'Tuần tra Bàng Bối Thành đã phát hiện ở Chỉ Phong Cốc các Cự Thạch trên đỉnh núi đã bị phá vỡ, hình thành nên các đám mây đỏ kỳ lạ. Ngươi đến đó xem có phải quái vật đã xuất hiện?', '-1', 2, NULL, NULL),
	(5411, NULL, 1, 0, 0, 'Được, khá lắm! Khá lắm!', 600, 2, 'Giao 500 Lệnh Bài Treo Thưởng, 5000 Điểm Chiến Tích chứng minh đủ tư cách là tông sư. (cấp độ nghề phải là  chuyên gia và học đủ tất cả kỹ năng tu luyện thì mới có thể hoàn thành nhiệm vụ)', NULL, -1, 200, 150, 0, 2, 'Nhiệm Vụ Nghề Tông Sư 3-1', 1, NULL, '|5|', 5000, 10, NULL, 427, 'Chỉ có thành viên có điểm chiến tích xuất sắc, có kinh nghiệm mới đủ tư cách nhận đẳng cấp nghề nghiệp. Trong thời gian ta thu nhận ngươi cần 500 Lệnh Bài Treo Thưởng và 5000 Điểm Chiến Tích', '-1', 1, NULL, NULL),
	(5412, NULL, 1, 0, 0, 'Được, khá lắm! Khá lắm!', 600, 2, 'Giao 500 Lệnh Bài Treo Thưởng, 5000 Điểm Chiến Tích chứng minh đủ tư cách là tông sư. (cấp độ nghề phải là  chuyên gia và học đủ tất cả kỹ năng tu luyện thì mới có thể hoàn thành nhiệm vụ)', NULL, -1, 200, 150, 0, 2, 'Nhiệm Vụ Nghề Tông Sư 3-1', 1, NULL, '|6|', 5000, 10, NULL, 639, 'Chỉ có thành viên có điểm chiến tích xuất sắc, có kinh nghiệm mới đủ tư cách nhận đẳng cấp nghề nghiệp. Trong thời gian ta thu nhận ngươi cần 500 Lệnh Bài Treo Thưởng và 5000 Điểm Chiến Tích', '-1', 1, NULL, NULL),
	(5413, NULL, 1, 0, 0, 'Quả nhiên ngươi không làm ta thất vọng!', 600, 2, 'Đánh bại Solomon ở Mị Hoặc Lâm', NULL, -1, 200, 150, 0, 2, 'Nhiệm Vụ Nghề Tông Sư 3-2', 2, NULL, 'all', 0, 0, NULL, 600, 'Chuẩn bị chiến đấu chưa? Solomon và 72 tên ma thần là những tên độc ác nhất Vô Ưu đấy! Hãy cẩn thận', '-1', 1, NULL, NULL),
	(5415, NULL, 1, 0, 0, 'Cho ngươi!', 1698, 2, 'Dùng Bí Chế Tương Khoa và Gà Tây Sống để chế thức ăn', NULL, -1, 160, 50, 0, 2, 'Bí Chế Gà Tây (1)', 1, NULL, 'all', 0, 0, NULL, 1698, 'Hãy cho ta Bí Chế Tương Khoa và Gà Tây Sống, ta sẽ cho ngươi thưởng thức mỹ vị của cuộc đời', '-1', 6, NULL, NULL),
	(30062, NULL, 1, 0, 0, 'Tốt lắm! Bọn ta đang cần thứ này!', 1069, 2, 'Tìm Thái Dương Thủy mang về Bang hội', NULL, -1, 160, 50, 0, 2, 'Thu Thập Vật Tư', 1, NULL, 'all', 0, 0, NULL, -1, 'Để xây dựng bang hội cần lượng lớn vật phẩm này. Hãy mang về ngay nhé!', '7-2', 7, NULL, NULL),
