	(3677, NULL, 1, 10453556, 0, 'Làm khá lắm.', 895, 2, 'Tiêu diệt Mê Hồn Giáo Chủ và Cánh Tay Viễn Cổ', NULL, -1, 160, 110, 150000, 2, 'Trấn Hồn Kiếm 19-5', 1, NULL, 'all', 0, 0, NULL, 895, 'Đúng là ta biết. Có điều ngươi phải đi Tiêu diệt Mê Hồn Giáo Chủ và Cánh Tay Viễn Cổ trước.', '-1', 4, NULL, NULL),
