	(4378, 'Ngẫu nhiên nhận được 2 nguyên liệu và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím<cam) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 101350, 0, 'Nhớ đến mua hàng ủng hộ cho ta nhé! O(∩_∩)O~', 940, 2, 'Mang 1 Liệt Văn Lực Thạch giao cho Lang Mộc ở tiệm vũ khí để lãnh thưởng.', NULL, -1, 129, 120, 0, 2, 'Tiệm Vũ Khí Thu Hồi Bảo Thạch', 1, NULL, 'all', 0, 0, NULL, -1, 'Tiệm vũ khí Lang Mộc ở Quyến Cố Thành gần đây đang thu thập bảo thạch để cường hóa vũ khí, mau mang bảo thạch đến đó lĩnh thưởng đi!', '9-12', 9, NULL, NULL),
	(4380, 'Ngẫu nhiên nhận được 2 nguyên liệu và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím<cam) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 101350, 0, 'Nhớ đến mua hàng ủng hộ cho ta nhé! O(∩_∩)O~', 940, 2, 'Mang 1 Liệt Văn Trí Thạch giao cho Lang Mộc ở tiệm vũ khí để lãnh thưởng.', NULL, -1, 129, 120, 0, 2, 'Tiệm Vũ Khí Thu Hồi Bảo Thạch', 1, NULL, 'all', 0, 0, NULL, -1, 'Tiệm vũ khí Lang Mộc ở Quyến Cố Thành gần đây đang thu thập bảo thạch để cường hóa vũ khí, mau mang bảo thạch đến đó lĩnh thưởng đi!', '9-12', 9, NULL, NULL),
	(4532, NULL, 1, 144844, 0, 'Ha ha, lâu lắm rồi không có ai đến đây.', 1125, 2, 'Đến Thần Di Cảnh điều tra', NULL, -1, 160, 111, 50000, 2, 'Di Tích Thần Thánh 13-1', 1, NULL, 'all', 0, 0, NULL, 946, 'Thần Di Cảnh nằm cạnh Mê Quang Tự là một nơi từng được thần linh phù hộ, nhưng tiếc thay hiện nay đã bị ác ma chiếm cứ, ngươi hãy đến đó tìm di tích của thần linh, chắc chắn sẽ có ích.', '-1', 4, NULL, NULL),
