	(4709, NULL, 1, 0, 0, 'Hi vọng ngươi sẽ dùng nó thật tốt.', 272, 2, 'Tộc Trưởng Bối Tư muốn gặp ngươi, hình như có việc quan trọng cần bàn.', NULL, -1, 160, 50, 0, 2, 'Trấn Hồn Nhạc Phổ', 1, NULL, '|2|', 0, 0, NULL, 312, 'Trấn Hồn Nhạc Phổ này là thần khí chí thượng của Liêu Vân Tộc, sẽ giúp ích rất nhiều cho ngươi, hôm nay ta tặng nó cho ngươi.', '-1', 10, NULL, NULL),
	(4711, NULL, 1, 0, 0, 'Hi vọng ngươi sẽ dùng nó thật tốt.', 272, 2, 'Tộc Trưởng Bối Tư muốn gặp ngươi, hình như có việc quan trọng cần bàn.', NULL, -1, 160, 50, 0, 2, 'Tinh Hỏa Trụy', 1, NULL, '|4|', 0, 0, NULL, 489, 'Tinh Hỏa Trụy này là thần khí chí thượng của Thiên Khung Tộc, sẽ giúp ích rất nhiều cho ngươi, hôm nay ta tặng nó cho ngươi.', '-1', 10, NULL, NULL),
	(4741, NULL, 1, 195857, 0, 'Để ta phái người đi kiểm tra', 541, 2, 'Đi xem tình hình Tiên Lạp Thành', NULL, -1, 160, 126, 50000, 2, 'Trợ Giúp Của Ác Ma 11-10', 1, NULL, 'all', 0, 0, NULL, 272, 'Ngươi đi xem thử tình hình ở Tiên Lạp Thành như thế nào rồi', '-1', 4, NULL, NULL),
	(4714, NULL, 1, 0, 0, 'Hãy sử dụng thần khí cho tốt nhé, năng lực của nó vượt xa sức tưởng tượng của ngươi đấy', 929, 2, 'Nhấp đôi sử dụng Kết Tinh Thần Tu, sau đó thử thăng cấp Thần Khí trong giao diện Rèn rồi đặt lên người, giao diện Thần khí nằm trong giao diện Nhân vật', NULL, -1, 160, 50, 0, 2, 'Thăng Cấp Thần Khí', 1, NULL, 'all', 0, 0, NULL, 929, 'Làm khá lắm, hãy nhận lấy viên Thâm Lam Tinh này, đây là vật không thể thiếu khi sửa chữa thần khí. Ta chỉ có thể giúp ngươi vậy thôi, những bước sau này phải xem khả năng của ngươi thế nào.', '-1', 10, NULL, NULL),
	(4715, NULL, 1, 173813, 0, 'Lâu quá không gặp!', 663, 2, 'Mực nước ở Tiên Lạp đột nhiên dâng cao, hãy mau điều tra nguyên nhân', NULL, -1, 160, 121, 50000, 2, 'Băng Tan 9-1', 1, NULL, 'all', 0, 0, NULL, 541, 'Gần đây mực nước đột nhiên dâng cao, không biết nguyên nhân vì sao, phiền ngươi hãy đi về phía nam điều tra xem sao', '-1', 4, NULL, NULL),
	(14545, NULL, 1, 0, 0, 'Cảm ơn ngươi', 423, 2, 'Đi tìm Tiệm Pet Amy', NULL, -1, 160, 10, 0, 2, 'Chuyển Lời', 1, NULL, 'all', 0, 0, NULL, -1, 'Chuyển lời đến cho Tiệm Pet Amy', '7-9', 7, NULL, NULL),
	(4718, NULL, 1, 10428829, 0, 'Việc mực nước dâng cao khiến cho mọi người hốt hoảng, hiện giờ tình hình thế nào rồi?', 290, 2, 'Bắt 1 Tinh Linh Cực Quang, điều tra tình hình', NULL, -1, 160, 121, 150000, 2, 'Băng Tan 9-4', 1, NULL, 'all', 0, 0, NULL, 120, 'Làm thế này cũng không hẳn là cách hay, tốt nhất nên bắt 1 con quái vật để điều tra. À phải rồi, ngươi hãy đi bắt 1 Tinh Linh Cực Quang giao cho Thành Chủ Tinh Linh điều tra xem sao, đều là tinh linh với nhau, chắc sẽ hiểu ngôn ngữ của nhau.', '-1', 4, NULL, NULL),
	(4720, NULL, 1, 10428829, 0, 'Xem ra người ngoài hành tinh cũng không khó đối phó', 541, 2, 'Tiêu diệt 100 Tộc Navi', NULL, -1, 160, 121, 150000, 2, 'Băng Tan 9-6', 1, NULL, 'all', 0, 0, NULL, 541, 'Dốc toàn lực tấn công người ngoài hành tinh! Mỗi người hãy tiêu diệt 100 tên Tộc Navi!', '-1', 4, NULL, NULL),
	(4722, NULL, 1, 17381382, 0, 'Làm tốt lắm!', 272, 2, 'Tiêu diệt 10 Đại Sứ Băng Tuyết', NULL, -1, 160, 121, 500000, 2, 'Băng Tan 9-8', 1, NULL, 'all', 0, 0, NULL, 272, 'Chỉ đánh bọn quái vật cũng không ổn, cần phải đánh bọn chỉ huy của chúng, ngươi hãy đi tiêu diệt 10 tên Đại Sứ Băng Tuyết đi', '-1', 4, NULL, NULL),
	(4726, NULL, 1, 10428829, 0, 'Như thế này cũng chưa khiến ta hả cơn giận', 944, 2, 'Tiêu diệt 60 Tộc Navi và 60 Người Máy Navi', NULL, -1, 160, 121, 150000, 2, 'Bất Cẩn Của Ác Ma 8-3', 1, NULL, 'all', 0, 0, NULL, 944, 'Sao??? Trái tim quan trọng nhất của Ma Vương Đại Nhân đã bị người ngoài hành tinh cướp đi rồi sao? Thật không thể tha thứ! Ta ra lệnh: Tất cả ác ma hãy xông lên Đoạn Cốc dạy cho bọn không biết trời cao đất dày đó một bài học, ngươi cũng hãy đi cùng, tiêu diệt 60 Tộc Navi và Người Máy Navi cho ta!', '-1', 4, NULL, NULL),
	(4729, NULL, 1, 17381382, 0, 'Ngươi đã mạnh hơn trước nhiều!', 1130, 2, 'Chiến đấu với sư huynh', NULL, -1, 160, 121, 500000, 2, 'Bất Cẩn Của Ác Ma 8-6', 1, NULL, 'all', 0, 0, NULL, 1130, 'Rốt cuộc cũng bị hắn phát hiện! Cũng đúng lúc ta đang muốn thử thực lực hiện tại của ngươi, đã lâu không gặp, chắc hẳn ngươi phải lợi hại hơn trước nhiều. Phải đánh cho ra trò đấy, ác ma đang đứng ở xa quan sát kia kìa…', '-1', 4, NULL, NULL),
	(7643, NULL, 1, 0, 0, 'Cảm ơn ngươi', 523, 2, 'Bắt 1 Hổ Bì Dương Xanh', NULL, -1, 160, 40, 0, 2, 'Bắt Hổ Bì Dương Xanh', 1, NULL, 'all', 0, 0, NULL, -1, 'Ta muốn có pet này, ngươi có thể giúp ta bắt 1 con không?', '7-5', 7, NULL, NULL),
