INSERT INTO data.data_tbl_quest (id, a_script_text, at, award_exp_re, color, complete_text, finish_npc, gender, info, is_rebirth, lm, max_level, min_level, money_num, money_type, name, pre_quest_type, qtest, req_class, rn, rt, script_give_up, start_npc, start_text, sub_type, type, start_grant_item, start_grant_qty) VALUES
	(7660, NULL, 1, 0, 0, 'Cảm ơn ngươi', 377, 2, 'Bắt 1 Nham Quái', NULL, -1, 160, 100, 0, 2, 'Bắt Nham Quái', 1, NULL, 'all', 0, 0, NULL, -1, 'Ta muốn có pet này, ngươi có thể giúp ta bắt 1 con không?', '7-5', 7, NULL, NULL),
	(4733, NULL, 1, 195857, 0, 'Vẫn cứ tăng à?', 272, 2, 'Tìm kế sách vẹn toàn', NULL, -1, 160, 126, 50000, 2, 'Trợ Giúp Của Ác Ma 11-2', 1, NULL, 'all', 0, 0, NULL, 541, 'Tuy tốc độ tăng có giảm nhưng hiệu quả cũng không rõ rệt lắm, ngươi hãy đi tìm Tộc Trưởng Bối Tư để nghĩ kế sách vẹn toàn.', '-1', 4, NULL, NULL),
	(4735, NULL, 1, 195857, 0, 'Chào', 1131, 2, 'Đánh rắn phải đánh vào đầu', NULL, -1, 160, 126, 50000, 2, 'Trợ Giúp Của Ác Ma 11-4', 1, NULL, 'all', 0, 0, NULL, 944, 'Việc này… Nguyên tắc trước nay của Ma giới là đánh rắn phải đánh vào đầu, ngươi hãy giữ vững quan điểm này và đến Đoạn Cốc điều tra xem sao', '-1', 4, NULL, NULL),
	(4737, NULL, 1, 10428829, 0, 'Cảm ơn ngươi nhé', 1131, 2, 'Mua Mì thịt bò', NULL, -1, 160, 126, 150000, 2, 'Trợ Giúp Của Ác Ma 11-6', 1, NULL, 'all', 0, 0, NULL, 1131, 'Ta vừa lạnh vừa đói, ngươi giúp ta mua 1 tô mì thịt bò được không? Ta sẽ đổi cho ngươi 1 tấm bản đồ kho báu, ta tìm được nó trong một cái hang ngập nước, ta sợ gặp nguy hiểm nên chưa dám dùng nó', '-1', 4, NULL, NULL),
	(4739, NULL, 1, 195857, 0, 'Thì ra là thế', 272, 2, 'Đại vương ngoài hành tinh mỗi ngày xuất hiện 1 lần', NULL, -1, 160, 126, 50000, 2, 'Trợ Giúp Của Ác Ma 11-8', 1, NULL, 'all', 0, 0, NULL, 1131, 'Avatar mỗi ngày đến đây 1 lần, thời gian cụ thể thì ta không biết', '-1', 4, NULL, NULL),
	(4742, NULL, 1, 195857, 0, 'Đây là phần thưởng của ngươi', 541, 2, 'Mực nước đã hạ', NULL, -1, 160, 126, 50000, 2, 'Trợ Giúp Của Ác Ma 11-11', 1, NULL, 'all', 0, 0, NULL, 541, 'Mực nước hiện tại đã hạ xuống gần bằng với trước kia rồi!', '-1', 4, NULL, NULL),
	(4745, NULL, 1, 42405669, 0, NULL, 288, 2, 'Thu thập 40 Hàn Băng trên người Sứ Giả Băng Tuyết', NULL, -1, 160, 131, 150000, 2, 'Thu Thập 40 Hàn Băng', 1, NULL, 'all', 0, 0, NULL, 288, 'Để ta đi tìm 1 vài quyển sách giúp tìm hiểu thông tin về phù chú này, nhưng mấy hôm nay thời tiết nóng bức quá, ta khó mà làm việc, hi vọng người có thể giúp ta đến Đoạn Cốc thu thập 40 mảnh Hàn Băng để ta làm mát.', '-1', 2, NULL, NULL),
	(10017, NULL, 1, 0, 0, 'Cảm ơn ngươi', 311, 2, 'Bắt 1 Khổng Lồ Vân Thiên', NULL, -1, 160, 60, 0, 2, 'Bắt Khổng Lồ Vân Thiên', 1, NULL, 'all', 0, 0, NULL, -1, 'Đạo Sư Linh Vũ cần 1 Khổng Lồ Vân Thiên, ngươi hãy tìm giúp nhé', '7-9', 7, NULL, NULL),
	(4748, NULL, 1, 42405669, 0, 'Thân thủ khá lắm!', 416, 2, 'Bắt 1 Tiểu Thái Dương và 1 Xương Rồng Tinh', NULL, -1, 160, 131, 150000, 2, 'Nguồn Năng Lượng', 1, NULL, 'all', 0, 0, NULL, 416, 'Cái máy này đã lâu rồi không dùng, muốn khởi động lại cần có nguồn năng lượng đặc biệt. Ngươi giúp ta bắt 1 Tiểu Thái Dương và 1 Xương Rồng Tinh.', '-1', 2, NULL, NULL),
	(4750, NULL, 1, 848113, 0, 'Phù dịch chuyển ra ngoài Vô Ưu Đại Lục?', 566, 2, 'Đưa cho chuyên gia trong lĩnh vực dịch chuyển xem phù', NULL, -1, 160, 131, 50000, 2, 'Đưa Phù Cho Người Dịch Chuyển', 1, NULL, 'all', 0, 0, NULL, 416, 'Bây giờ phù đã được khôi phục về nguyên trạng, nhưng ta không biết có thể dùng được hay không. Ngươi hãy đi tìm Dịch Chuyển Mark để xem ông ta có dùng được nó không.', '-1', 2, NULL, NULL),
	(4752, NULL, 1, 848113, 0, 'Muốn ta giúp ư?', 274, 2, 'Tìm Tiệm Vũ Khí Mark để giải quyết vấn đề bay một đoạn ngắn', NULL, -1, 160, 131, 50000, 2, 'Bay Một Đoạn Ngắn', 1, NULL, 'all', 0, 0, NULL, 272, 'Ngươi đi gặp Tiệm Vũ Khí Mark hỏi xem sao, anh ta chuyên chế ra các món trang bị lợi hại, chắc sẽ có cách giúp ngươi giải quyết được vấn đề bay trong 1 thời gian ngắn.', '-1', 2, NULL, NULL),
	(4754, NULL, 1, 42405669, 0, 'Số lượng mà ngươi thu thập được cũng khá đấy', 274, 2, 'Đánh bại Bạch Kim Thuẫn và thu thập 30 Vỏ Bạch Kim Thuẫn', NULL, -1, 160, 131, 150000, 2, 'Thu Thập 30 Vỏ Bạch Kim Thuẫn', 1, NULL, 'all', 0, 0, NULL, 274, 'Bạch Kim Thuẫn rất cứng nhưng trọng lượng lại nhẹ, là dụng cụ bay rất tốt. Hãy giúp ta thu thập 30 Vỏ Bạch Kim Thuẫn nhé.', '-1', 2, NULL, NULL),
	(4756, NULL, 1, 848113, 0, 'Xong cả rồi ư?', 272, 2, 'Phù dịch chuyển đã sửa xong, hãy đi gặp Tộc Trưởng báo tin', NULL, -1, 160, 131, 50000, 2, 'Phù Chú Hoàn Chỉnh', 1, NULL, 'all', 0, 0, NULL, 566, 'Phù này đã sửa xong rồi, có thể giúp ngươi dịch chuyển. Ngươi hãy đến gặp Tộc Trưởng hỏi xem ông ấy còn có dặn dò gì không.', '-1', 2, NULL, NULL),
	(4759, NULL, 1, 42405669, 0, 'Trước đây bọn rồng rất hiền lành, không hiểu sao giờ lại…!', 1165, 2, 'Tiêu diệt 80 Bạo Liệt Long', NULL, -1, 160, 131, 150000, 2, 'Tiêu Diệt Bạo Liệt Long', 1, NULL, 'all', 0, 0, NULL, 1165, 'Gọi là Vô Ưu Đại Lục ư? Tên hay quá! Ngươi được phái đến vùng đất đầy tai ương này, vậy chắc ngươi phải lợi hại lắm! Lính tiên phong ư? Chà! Vậy ngươi giúp ta tiêu diệt  số Bạo Liệt Long ở Mị Hoặc Lâm được không? Gia súc trong thôn thường hay bị chúng ăn thịt, thật là bực mình', '-1', 2, NULL, NULL),
	(4762, NULL, 1, 1696226, 0, 'Vất vả cho ngươi rồi', 1165, 2, 'Bắt 1 Nấm Lục', NULL, -1, 160, 131, 50000, 2, 'Mang Đến Nấm Lục', 1, NULL, 'all', 0, 0, NULL, 1165, 'Khi thôn gặp chuyện, chúng ta đã thành lập 1 đội quân bảo vệ, các thành viên còn lại của đội quân này khá là hung hăng, hay gây sự đánh nhau, ngươi phải cẩn thận đấy. Mấy hôm trước, bọn họ đánh nhau dẫm nát hết vườn nấm nhà ta. Ngươi có thể giúp ta mang 1 ít nấm từ Vô Ưu Đại Lục sang được không?', '-1', 2, NULL, NULL),
	(4765, NULL, 1, 848113, 0, 'Ngươi là ai?', 1166, 2, 'Chăm sóc Reck - cháu trai của trưởng thôn', NULL, -1, 160, 131, 50000, 2, 'Ủy Thác Của Thôn Trưởng', 1, NULL, 'all', 0, 0, NULL, 1165, 'Ta có việc phải đi vài ngày, ngươi giúp ta chăm sóc cháu trai của ta với. Nó hơi nghịch ngợm, thật là làm phiền ngươi rồi.', '-1', 2, NULL, NULL),
	(4767, NULL, 2, 84811339, 0, 'Đúng rồi, chính là cái này', 1166, 2, 'Đến Mị Hoặc Lâm tìm đồ chơi bị mất', NULL, -1, 160, 131, 500000, 2, 'Tìm Rương Đồ Chơi', 1, NULL, 'all', 0, 0, NULL, 1166, 'Lần trước lúc ta đang chơi ở Mị Hoặc Lâm thì bị một con khủng long truy đuổi, đánh rơi mất món đồ chơi mà ta ưa thích, ngươi có thể giúp ta tìm lại được không? Rơi ở chỗ nào ta cũng không nhớ nữa…', '-1', 2, NULL, NULL),
	(4770, NULL, 1, 42405669, 0, 'Bọn gấu đáng ghét này đúng là đã cướp khá nhiều!', 1168, 2, 'Đoạt lại 40 phần Mật Ong', NULL, -1, 160, 131, 150000, 2, 'Đoạt Lại 40 Phần Mật Ong', 1, NULL, 'all', 0, 0, NULL, 1168, 'Trong rừng có 1 bọn gấu rất đáng ghét, thường hay lấy trộm mật ong ta giấu trên cây, giờ ta hết cả mật ong để ăn, ngươi giúp ta đoạt về lại 40 phần được không?', '-1', 2, NULL, NULL),
	(4773, NULL, 2, 42405669, 0, 'Ngươi muốn lấy bảo vật nào?', 1168, 2, 'Sử dụng Bản Vẽ C và hoàn thành nhiệm vụ bản vẽ', NULL, -1, 160, 131, 150000, 2, 'Nhận Được Bản Vẽ C', 1, NULL, 'all', 0, 0, NULL, 1168, 'Đây là bản vẽ thứ 3, ngươi cầm lấy', '-1', 2, NULL, NULL),
	(4775, NULL, 1, 848113, 0, 'Ngươi chính là quân tiên phong đến từ Vô Ưu Đại Lục?', 1167, 2, 'Gặp Tướng Quân Cô Thôn', NULL, -1, 160, 131, 50000, 2, 'Tướng Quân Có Lời Mời', 1, NULL, 'all', 0, 0, NULL, 1166, 'Tướng Quân Cô Thôn phái người đến nói: Nếu ngươi quay lại thì mời ngươi đến gặp.', '-1', 2, NULL, NULL),
	(4778, NULL, 1, 848113, 0, 'Sao rồi?', 1167, 2, 'Hỏi rõ giấc mơ của Tướng quân', NULL, -1, 160, 131, 50000, 2, 'Hỏi Tướng Quân Tường Tận', 1, NULL, 'all', 0, 0, NULL, 669, 'Ngươi kể rõ cho ta nghe xem nào! Việc này khá giống việc Vệ Sĩ từng gặp trước đây, có điều lần này là trong mơ. Ngươi đi hỏi tướng quân xem gần đây anh ta từng đi qua những chỗ nào.', '-1', 2, NULL, NULL),
	(4779, NULL, 1, 848113, 0, 'Việc này, để ta nghĩ xem sao.', 1165, 2, 'Hỏi trưởng lão trong thôn: Thôn Trưởng Điêu Linh', NULL, -1, 160, 131, 50000, 2, 'Hỏi Thôn Trưởng Điêu Linh', 1, NULL, 'all', 0, 0, NULL, 1167, 'Gần đây ta đâu có đi đâu, suốt 1 tháng nay ta chỉ ở trong thôn. Hay ngươi tìm Trưởng thôn hỏi xem sao, ta bị mất ngủ, giờ mệt mỏi quá.', '-1', 2, NULL, NULL),
	(4781, NULL, 1, 42405669, 0, 'Đúng là thứ nước này', 434, 2, 'Tiêu diệt Mộng Lão Ông và thu thập 25 Nước Giấc Mơ', NULL, -1, 160, 131, 150000, 2, 'Thu Thập 25 Phần Nước Giấc Mơ', 1, NULL, 'all', 0, 0, NULL, 434, 'Trước tiên cần phải đi vào giấc mơ của người khác, việc này cần có Nước Giấc Mơ trên người Mộng Lão Ông, ngươi hãy đi thu thập 25 phần đi nào.', '-1', 2, NULL, NULL),
	(4783, NULL, 1, 848113, 0, 'Hả? Thật sự có cách ư?', 1167, 2, 'Có cơ hội rồi, mau về báo cho Tướng quân', NULL, -1, 160, 131, 50000, 2, 'Vấn Đề Có Thể Được Giải Quyết', 1, NULL, 'all', 0, 0, NULL, 434, 'Được rồi, các vật phẩm đã thu thập đủ. Việc còn lại có làm được hay không thì cần phải xem vận may của ngươi… Hãy đến gặp Tướng quân báo mọi việc đi', '-1', 2, NULL, NULL),
	(4785, NULL, 1, 848113, 0, 'Không đùa chứ? Ngươi đánh bại được cả Ác Mộng Quái? Thật khó tin!', 1165, 2, 'Đến gặp Thôn trưởng', NULL, -1, 160, 131, 50000, 2, 'Tướng Quân Buồn Ngủ Rồi', 1, NULL, 'all', 0, 0, NULL, 1167, 'Ta rất muốn ngủ một giấc cho đã, xin lỗi vì không thể tiếp ngươi thêm được, ngươi đến chỗ Thôn trưởng chơi 1 lát đi. Tỉnh dậy rồi ta sẽ cảm tạ ngươi đầy đủ.', '-1', 2, NULL, NULL),
	(10018, NULL, 1, 0, 0, 'Cảm ơn ngươi', 310, 2, 'Bắt 1 Cát Hải Tinh', NULL, -1, 160, 60, 0, 2, 'Bắt Cát Hải Tinh', 1, NULL, 'all', 0, 0, NULL, -1, 'Đạo Sư Bàn Địa cần 1 Cát Hải Tinh, ngươi hãy tìm giúp nhé', '7-9', 7, NULL, NULL),
	(4789, NULL, 2, 84811339, 0, 'Tốt quá! Hu hu tội nghiệp con pet của ta!', 1168, 2, 'Tiêu diệt quái vật bay trên bầu trời Mị Hoặc Lâm', NULL, -1, 160, 131, 500000, 2, 'Tiêu Diệt Phi Ma', 1, NULL, 'all', 0, 0, NULL, 1168, 'Không phải là ngươi có 1 dụng cụ bay sao? Chỉ cần bay trên không thì sẽ rất dễ gặp nó! Giúp ta tiêu diệt nó đi! Lần trước nó đã bắt đi pet mà ta định tặng cho Reck!! Bọn ta gọi nó là Phi Ma.', '-1', 2, NULL, NULL),
