	(9003, 'Phần thưởng chưa biết', 1, -1, 4, 'Ta quả thực không nhìn nhầm người, ngươi đã thực hiện được thử thách, giờ ta sẽ chúc phúc cho ngươi.', 304, 2, 'Thiên Sứ hiện thân ngay trước mặt bạn, ban cho bạn lời chúc phúc, hãy đi tìm 10 viên Thăng Tinh Thạch, sau đó đến chỗ Khả Vi ở tiệm trang sức Đông Huyền Thành lãnh thưởng.', NULL, -1, 160, 20, 0, 2, 'Thiên Sứ Hạ Phàm', 1, NULL, 'all', 0, 0, NULL, -1, 'Chào ngươi, ngươi là người may mắn được ta chọn chúc phúc trong số hàng ngàn người, để nhận được sự chúc phúc của ta, ngươi hãy thực hiện điều sau:  hãy đi tìm 10 viên Thăng Tinh Thạch sau đó về giao cho Tiệm Trang Sức Khả Vi Nhi để lãnh thưởng.', '12-3', 12, NULL, NULL),
	(9005, 'Phần thưởng chưa biết', 1, -1, 4, 'Ngươi thật tài giỏi, đã thực hiện được thử thách, giờ ta sẽ chúc phúc cho ngươi.', 304, 2, 'Thiên Sứ hiện thân ngay trước mặt bạn, ban cho bạn lời chúc phúc, hãy đi thu thập 2 viên Liệt Văn Mệnh Thạch, sau đó đến chỗ Khả Vi ở tiệm trang sức Đông Huyền Thành lãnh thưởng.', NULL, -1, 160, 20, 0, 2, 'Thiên Sứ Hạ Phàm', 1, NULL, 'all', 0, 0, NULL, -1, 'Chào ngươi, ngươi là người may mắn được ta chọn chúc phúc trong số hàng ngàn người, để nhận được sự chúc phúc của ta, ngươi hãy thực hiện điều sau:  hãy đi thu thập 2 viên Liệt Văn Mệnh Thạch sau đó về giao cho Tiệm Trang Sức Khả Vi Nhi để lãnh thưởng.', '12-3', 12, NULL, NULL),
