	(31516, 'Phần thưởng kinh nghiệm và vật phẩm ngẫu nhiên', 1, 0, 1, 'Rất tốt, tiếp theo là phần 【Đuôi Rồng Lớn】', 1730, 2, 'Đến Thế Giới Hải Dương tìm gặp Long Vương mang về 1 【Thân Rồng Lớn】', NULL, -1, 200, 200, 0, 1, 'Vận Chuyển 【Thân Rồng】', 1, NULL, 'all', 0, 0, NULL, 1730, 'Mỗi năm cứ đến ngày Tết Đoan Ngọ là lúc đại hội Long Đan cũng bắt đầu, nhưng những nguyên liệu để luyện nên Long Đan vẫn còn thiếu, để bảo đảm cho Đại Hội được diễn ra suôn sẻ, hãy mang đến 【Thân Rồng Lớn】đến cho ta!', '-1', 6, NULL, NULL),
	(5449, 'Phần thưởng kinh nghiệm và ngân phiếu', 1, 0, 4, 'Ngươi làm rất tốt! Hãy mau đi giải phong ấn cho thần khí khác đi!', 1742, 2, 'Giúp Thợ Săn Muỗi giáo huấn Muỗi Tướng Quân và hóa giải phong ấn cho Vợt Muỗi', NULL, -1, 200, 120, 0, 1, 'Thần Khí Hủy Diệt? Vợt Muỗi!', 1, NULL, 'all', 0, 0, NULL, 1742, 'Muỗi Tướng Quân đang canh giữ Thần Khí Vợt Muỗi, hãy đuổi hắn đi và hóa giải phong ấn cho Thần Khí!', '-1', 6, NULL, NULL),
	(5451, 'Phần thưởng kinh nghiệm và ngân phiếu', 1, 0, 4, 'Đáng ghét! Lại để hắn chạy thoát! Mau bắt hắn lại mau!', 1742, 2, 'Giúp Thợ Săn Muỗi giáo huấn Muỗi Đại Vương', NULL, -1, 200, 120, 0, 1, 'Tóm Gọn Thủ Lĩnh', 1, NULL, 'all', 0, 0, NULL, 1742, '2 Thần Khí đã được hóa giải, trước mắt hãy còn 1 Quân Đoàn Muỗi và Muỗi Đại Vương. Hắn cực kỳ xảo quyệt! Hãy cẩn thận!', '-1', 6, NULL, NULL),
	(31535, NULL, 1, 0, 1, 'Kinh nghiệm, Bạc', 237, 2, 'Đến Xuất Vân Thôn hù dọa Tôn Mỹ Mỹ 1 phen, haha!', NULL, -1, 160, 50, 0, 0, 'Hù Dọa Tôn Mỹ Mỹ', 1, NULL, 'all', 0, 0, NULL, -1, 'Các ngươi thật nghịch ngợm!', '7-10', 7, NULL, NULL),
	(5453, NULL, 1, 0, 1, 'Các ngươi có thể đến tìm Thợ Săn Muỗi ở Vĩnh Dạ Cảng để vào phụ bản', 200, 2, 'Tiến về Vĩnh Dạ Cảng, tìm gặp Thợ Săn Muỗi, mở nhiệm vụ phụ bản Quỷ Hút Máu', NULL, 1, 200, 120, 0, 1, 'Mở Nhiệm Vụ Quỷ Hút Máu', 1, NULL, 'all', 900000, 2, NULL, 200, 'Thợ Săn Muỗi đưa cho ta Thư Cầu Cứu, nghe đâu trước đó đã phát hiện ra 1 nơi gọi là sào huyệt của Quỷ Hút Máu. Hãy đến xem giúp ông ấy!', '-1', 6, NULL, NULL),
	(5455, NULL, 1, 0, 0, NULL, 1698, 2, 'Chỉ cần đem đến Gà Tây May Mắn đến cho ta phóng sinh là có thể nhận Huy Chương Đôi Cánh Gà Tây!', NULL, -1, 200, 200, 0, 2, 'Đổi Huy Chương Đôi Cánh Gà Tây', 1, NULL, 'all', 0, 0, NULL, 1698, 'Cho ngươi!', '-1', 6, NULL, NULL),
	(31519, NULL, 1, 0, 4, 'Vì 1 ngày hè không có muỗi!', 1742, 2, 'Giúp Thợ Săn Muỗi thu thập Tiêu Bản Máu của Muỗi Đại Vương', NULL, -1, 160, 50, 0, 1, 'Vệ Sĩ Mùa Hè', 1, NULL, 'all', 0, 0, NULL, -1, 'Cứ mỗi độ hè về là Quân Đoàn Muỗi đến tấn công cư dân Vô Ưu, quấy phá giấc ngủ mọi người, lan truyền bệnh dịch. Ta đang nghiên cứu một loại vũ khí có thể tiêu diệt được bọn chúng nhưng ta có quá ít Tiêu Bản Máu Muỗi Đại Vương, hãy giúp ta!', '-1', 6, NULL, NULL),
	(31528, 'Phần thưởng kinh nghiệm và ngân phiếu', 1, 0, 2, 'Rất tốt, ngươi đã vượt qua vòng thử thách thứ 2!', 1761, 2, 'Vòng thử thách thứ 2, Đạo Sư Huyền Lâm và Đạo Sư Linh Vũ cần 1 lượng lớn các tiêu bản để nghiên cứu. Hãy đi thu thập 10 tiêu bản đến giao cho Đạo Sư Huyền Lâm hoặc Đạo Sư Linh Vũ (45,78) l', NULL, -1, 160, 50, 0, 2, 'Tiêu Bản Thần Kỳ', 1, NULL, 'all', 0, 0, NULL, 1761, 'Ngày kỷ niệm thành lập Học Viên đã đến cũng là lúc để các dũng sĩ thể hiện tài năng cảu mình. Mỗi dũng sĩ cần phần lần lượt vượt qua các thử thách của các Đạo Sư thì mới có thể hoàn thành nhiệm vụ.', '-1', 6, NULL, NULL),
	(31545, NULL, 1, 0, 1, 'Kinh nghiệm, Bạc', 421, 2, 'Đến Tinh Linh Thành hù dọa Đại Hiền Triết Fetocci 1 phen, haha!', NULL, -1, 160, 50, 0, 0, 'Hù Dọa Đại Hiền Triết Fetocci', 1, NULL, 'all', 0, 0, NULL, -1, 'Các ngươi thật nghịch ngợm!', '7-10', 7, NULL, NULL),
	(31530, 'Phần thưởng kinh nghiệm và ngân phiếu', 1, 0, 2, 'Chúc mừng đã vượt qua tất cả thử thách! Vinh quang này là của ngươi!', 1761, 2, 'Vòng thử thách cuối cùng là phải vượt qua đội quân hùng mạnh nhất, tinh anh nhất của 6 gia tộc! Hãy đi tìm Tộc Trưởng Bối Tư (115,54) để nghênh chiến', NULL, -1, 160, 50, 0, 2, 'Cuộc Chiến Cuối Cùng', 1, NULL, 'all', 0, 0, NULL, 1761, 'Ngày kỷ niệm thành lập Học Viên đã đến cũng là lúc để các dũng sĩ thể hiện tài năng cảu mình. Mỗi dũng sĩ cần phần lần lượt vượt qua các thử thách của các Đạo Sư thì mới có thể hoàn thành nhiệm vụ.', '-1', 6, NULL, NULL),
