	(50675, NULL, 1, 6000, 1, 'Nước ở Lê Dương có vấn đề? Không phải chứ?', 468, 2, 'Đến Lê Dương Đảo tìm Quan Tuần Tra Lê Dương', NULL, -1, 160, 50, 3600, 1, 'Tình Hình Căng Thẳng 2', 1, NULL, 'all', 0, 0, NULL, 272, 'Xem kết quả điều tra của Nghiên Cứu Gia XX hinh như nguồn nước ở Đông Xuất Vân đã bị nhiễm khuẩn. Nước ở Đông Xuất Vân đều sủi bọt trắng xóa, e là Lê Dương xuất hiện biến cố gì đó, ngươi hãy tìm Quan Tuần Tra Lê Dương tìm hiểu tình hình', '-1', 6, NULL, NULL),
	(50677, NULL, 1, 60000, 1, 'Cuối cùng cũng hít thở thoải mái', 454, 2, 'Quét sạch hồ tặc ở Lê Dương Thôn', NULL, -1, 160, 50, 36000, 1, 'Tình Hình Căng Thẳng 4', 1, NULL, 'all', 0, 0, NULL, 454, 'Hồ tặc đột nhiên đột kích, hãy đánh lùi chúng rồi hẵng tính tiếp chuyện khác', '-1', 6, NULL, NULL),
	(50679, NULL, 1, 30000, 1, 'Có manh mối rồi à?', 272, 2, 'Mang Thư Thần Bí đến Đông Huyền Thành giao cho Tộc Trưởng Bối Tư', NULL, -1, 160, 50, 18000, 1, 'Tình Hình Căng Thẳng 6', 1, NULL, 'all', 0, 0, NULL, 454, 'Chữ viết trong thư tuy rất quen nhưng ta xem không hiểu gì hết, chắc là đã cài thêm mật mã. Ngươi mang về giao cho Tộc Trưởng Bối Tư xem, có thể ông ta biết được huyền cơ gì đó', '-1', 6, NULL, NULL),
	(50681, NULL, 1, 60000, 1, 'Ngươi đã tìm được mảnh vỡ bản mật mã rồi à? Tốt lắm, để ta xem xem', 288, 2, 'Tiêu diệt hồ tặc xem xem có thể tìm được manh mối gì không', NULL, -1, 160, 50, 36000, 1, 'Tình Hình Căng Thẳng 8', 1, NULL, 'all', 0, 0, NULL, 288, 'Chỉ nhìn cái thư này thì chẳng hiểu gì cả, ngươi xem xem có thể tìm ra manh mối gì không', '-1', 6, NULL, NULL),
	(50684, NULL, 1, 60000, 1, 'Nhiệm vụ mới à? Đưa ta xem', 468, 2, 'Tạo Kỳ Tích Thủy', NULL, -1, 160, 50, 36000, 1, 'Tình Hình Căng Thẳng 11', 1, NULL, 'all', 0, 0, NULL, 272, 'Theo thư nhận tôi của Gấu Trúc LK, loại thuốc này đã được tịnh hóa cần lượng lớn  Kỳ Tích Thủy, ngươi hãy mau đi thu thập rồi giao cho Quan Tuần Tra Lê Dương.', '-1', 6, NULL, NULL),
	(50685, NULL, 1, 30000, 1, 'Mọi việc đã ổn thỏa chưa?', 272, 2, 'Đến Đông Huyền Thành tìm Tộc Trưởng Bối Tư', NULL, -1, 160, 50, 18000, 1, 'Tình Hình Căng Thẳng 12', 1, NULL, 'all', 0, 0, NULL, 468, 'Ta sẽ dựa theo hướng dẫn này mà làm, sẽ tốn ít thời gian, ngươi trước mắt về tìm Tộc Trưởng Bối Tư báo cáo đi', '-1', 6, NULL, NULL),
	(50687, NULL, 1, 30000, 1, 'Sự tình đã rõ, hãy giúp ta mang thư hồi đáp', 435, 2, 'Đem thư của Tộc Trưởng Bối Tư đến giao cho Thành Chủ Bàng Bối Thành', NULL, -1, 160, 50, 18000, 1, 'Tình Hình Căng Thẳng 14', 1, NULL, 'all', 0, 0, NULL, 435, 'Thư của Tộc Trưởng Bối Tư? Để ta xem xem', '-1', 6, NULL, NULL),
