	(302, NULL, 1, 6166, 0, 'Thật là sự giúp đỡ lớn khi khó khăn', 274, 2, 'Thu 20 Kim Loại Sáng từ Sa Tặc Cuồng Phong và Kẻ Lang Thang đưa cho Mark tiệm vũ khí thành Đông Huyền', NULL, -1, 29, 20, 0, 1, 'Kim Loại Hiếm', 1, NULL, 'all', 0, 0, NULL, -1, 'Giúp Mark tiệm vũ khí thành Đông Huyền sưu tầm một ít kim loại sáng, gần đây thành viên mới tăng nhiều kim loại luyện vũ khí không đủ dùng', '9-2', 9, NULL, NULL),
	(303, NULL, 1, 6166, 0, 'Thật là sự giúp đỡ lớn khi khó khăn', 304, 2, 'Thu thập 20 viên Ngọc Hoàn Chỉnh đưa cho Khả Vi  tiệm trang sức thành Đông Huyền, nghe nói trên thân Tiểu Hải Tinh tại Lê Dương Bắc và Cát Hải Tinh ở ốc đảo Thiên Lục Châu cũng có ngọc này.', NULL, -1, 29, 20, 0, 1, 'Trang Sức Thủy Tinh', 1, NULL, 'all', 0, 0, NULL, -1, 'Giúp Khả Vi  tiệm trang sức thành Đông Huyền sưu tầm một ít kim loại sáng, gần đây thành viên mới tăng nhiều kim loại luyện vũ khí không đủ dùng', '9-2', 9, NULL, NULL),
