	(343, NULL, 1, 6166, 0, 'Rất tốt, tên thợ săn này sẽ không làm phiền được ta nữa rồi, ha ha....', 446, 2, 'Giúp thợ săn Tiêu diệt 20 Độc Nhãn Da Xanh vùng Tiên Lạp Thành rồi đến chỗ đội trưởng bảo vệ Tiên Lạp Thành lĩnh thưởng', NULL, -1, 29, 20, 0, 1, 'Yêu Quái Màu Xanh', 1, NULL, 'all', 0, 0, NULL, -1, 'Người rừng và gấu lông nâu ở vùng Tiên Lạp Thành hoạt động thường xuyên, đã uy hiếp thợ săn và xuất hành của khách du lịch. Hy vọng các thành viên ở đó chú ý an toàn', '9-2', 9, NULL, NULL),
	(3669, NULL, 1, 130669, 0, 'Há???', 947, 2, 'Gặp Hắc Long Vương tìm Vảy Long Vương', NULL, -1, 160, 106, 50000, 2, 'Nguồn Sinh Mệnh 13-10', 1, NULL, 'all', 0, 0, NULL, 948, 'Tiếp theo phải có Vảy Long Vương, chỗ Hắc Long Vương có đấy, ngươi đến hỏi xem ông ta có đồng ý cho hay không.', '-1', 4, NULL, NULL),
	(344, NULL, 1, 6166, 0, 'Rất tốt, tên thợ săn này sẽ không làm phiền được ta nữa rồi, ha ha....', 446, 2, 'Đến vùng Tiên Lạp Thành Tiêu diệt 1 Đại Gấu Tuyết, đến chỗ đội trưởng bảo vệ Tiên Lạp Thành lĩnh thưởng', NULL, -1, 29, 20, 0, 1, 'Pet Của Thợ Săn', 1, NULL, 'all', 0, 0, NULL, -1, 'Người rừng và gấu lông nâu ở vùng Tiên Lạp Thành hoạt động thường xuyên, đã uy hiếp thợ săn và xuất hành của khách du lịch. Hy vọng các thành viên ở đó chú ý an toàn', '9-2', 9, NULL, NULL),
	(655, NULL, 1, 6166, 0, 'Bằng hữu, ngươi thật lợi hại, ngay cả thủ vệ của ta cũng phải bội phục ngươi.', 277, 2, 'Tiêu diệt 10 Phỉ Thúy Tinh ở Lê Dương Đảo, 10 Ốc Vệ Sĩ, sau đó đến Đông Huyền Thành gặp Đội Trưởng Cận Vệ lãnh thưởng ', NULL, -1, 29, 20, 0, 1, 'Tiêu Diệt Ốc Và Phỉ Thúy Tinh', 1, NULL, 'all', 0, 0, NULL, -1, 'Gần đây ở Lê Dương Đảo quái vật sinh sôi nảy nỡ, khiến cư dân ở đó tạo thành 1 uy hiếp đáng sợ', '9-2', 9, NULL, NULL),
	(346, 'Ngẫu nhiên nhận được 2 nguyên liệu và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím<cam) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 9515, 0, 'Phen này có thể cùng vợ đi ngắm hoa anh đào được rồi', 498, 2, '  Nghe nói trên người Yêu Hoa ở Anh Vũ Cảnh có nhiều nguyên liệu chế thuốc thượng hạng, giúp Dược Sĩ ở Tiên Lạp Thành đến Anh Vũ Cảnh và thu thập 20 Nhụy Hoa Mê Hoặc.', NULL, -1, 39, 30, 0, 1, 'Nhị Hoa Mê Hoặc', 1, NULL, 'all', 0, 0, NULL, -1, 'Nghe nói toàn thân bọn Yêu Hoa ở Anh Vũ Cảnh đều là những nguyên liệu thuốc thượng đẳng. Hãy giúp Danh Y Tiên Lạp Thành tới Anh Vũ Cảnh xem sao', '9-3', 9, NULL, NULL),
	(349, 'Ngẫu nhiên nhận được 2 nguyên liệu trang bị và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 9515, 0, 'Quả nhiên không phải là người thường', 446, 2, '  Thu thập 20 Kính Cận trên người Mèo Kính Đen ở Anh Vũ Cảnh, sau đó đến chỗ Trưởng Cận Vệ Tiên Lạp Thành nhận thưởng.', NULL, -1, 39, 30, 0, 1, 'Chứng Minh Người Dũng Cảm', 1, NULL, 'all', 0, 0, NULL, -1, 'Giúp thanh toán Mèo Kính Đen và thu thập Kính Cận trên người chúng để chứng minh', '9-3', 9, NULL, NULL),
	(350, NULL, 1, 6166, 0, 'Thôi, hy vọng mọi người lấy đây làm gương, đừng có hại mình hại người', 277, 2, 'Đến đảo Lê Dương tìm Tiêu diệt Ốc Tiểu Đội Trưởng rồi đến đội bảo vệ thành Đông Huyền lĩnh thưởng', NULL, -1, 29, 20, 0, 1, 'Khởi Nguồn Tội Ác', 1, NULL, 'all', 0, 0, NULL, -1, 'Truy nã Ốc Tiểu Đội Trưởng và chân tay của hắn, khởi nguồn tội ác do lôi kéo ốc tạo phản khiến loài người và ốc bị thương nặng nề. Chúng ta phải tìm cho ra kẻ cầm đầu tạo phản, Tiêu diệt nó', '9-2', 9, NULL, NULL),
	(351, NULL, 1, 6166, 0, 'Nhiều hải sản tươi sống quá trời!', 465, 2, 'Thu thập thịt Bạch Tuộc Lục trên đảo Lê Dương và Thịt Thỏ Điên, sau đó đến chỗ ông chủ quán rượu thành Tiên Lạp Thành lĩnh thưởng', NULL, -1, 29, 20, 0, 1, 'Thức Ăn', 1, NULL, 'all', 0, 0, NULL, -1, 'Quán rượu trong Tiên Lạp Thành cần lượng thực phẩm rất lớn', '9-2', 9, NULL, NULL),
	(353, NULL, 1, 6166, 0, 'Mọi người về sau đừng bị mê hoặc bởi vẻ ngoài nhé!', 295, 2, 'Đến Quang Bình Nguyên Tiêu diệt Lang Bì Dương thu hồi tài sản. Sau đó đến chỗ Vệ Sĩ thành Tinh linh lĩnh thưởng', NULL, -1, 29, 20, 0, 1, 'Dê Mượn Oai Sói', 1, NULL, 'all', 0, 0, NULL, -1, 'Lang Bì Dương luôn dùng vẻ ngoài ngốc nghếch để chiếm lòng thương hại của loài người, theo thông báo đã rất nhiều người bị nó gạt tiền. Vệ Sĩ thành Tinh Linh mong có người dạy cho chúng bài học và thu hồi lại tiền tệ', '9-2', 9, NULL, NULL),
	(1036, NULL, 1, 4000, 0, 'Quá tốt, tin tức từ bức thư ngươi mang đến rất có ích.', 541, 2, 'Trở về Tiên Lạp Thành, đưa những tin tức đã tìm được giao cho thành chủ', NULL, -1, 160, 36, 3500, 2, 'Đao Của Kẻ Báo Thù 17-8', 1, NULL, 'all', 0, 0, NULL, 288, 'Từ trong sách cho thấy, Rink đi qua rất nhiều nơi, nhưng tại sao hắn lại mất tích? Với lại trong thư không có nhắc đến gia đình của hắn, trong thư có nói lần cuối cùng hắn có lẽ trở về quê hương của hắn, xem ra lại làm phiền ngươi đi 1 chuyến nữa', '-1', 4, NULL, NULL),
	(354, 'Ngẫu nhiên nhận được 2 nguyên liệu và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím<cam) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 9515, 0, 'Cái chết của Tướng Lĩnh Sói là đòn tấn công nặng nề với tộc sói, nhưng ta lại lo dẫn đến báo thù mới…', 462, 2, '  Tướng Lĩnh Sói là tinh anh của Lang tộc ở Kỵ Bình Nguyên, tiêu diệt chúng chính là đòn cảnh cáo đối với Lang tộc! Hãy hành động rồi đến chỗ Vệ Sĩ Bàng Bối Thành nhận thưởng.', NULL, -1, 39, 30, 0, 1, 'Thừa Thắng Truy Kích', 1, NULL, 'all', 0, 0, NULL, -1, 'Lần tấn công bọn Lang tộc đã thu được kết quả tốt, nay chúng ta hãy thừa thắng xông lên đập tan chúng một lần nữa', '9-3', 9, NULL, NULL),
	(357, NULL, 1, 6166, 0, 'Hy vọng thứ này có thể bù đắp những tổn thất của nhà thợ săn', 448, 2, 'Giúp thợ săn đến vùng Tiên Lạp Thành bắt 1 Hổ Bì Dương, 1 Độc Nhãn Da Xanh và Tiêu diệt Gấu Tuyết Thủ Lĩnh. Sau đó đến chỗ Lão Thợ Săn Tiên Lạp Thành lĩnh thưởng', NULL, -1, 29, 20, 0, 1, 'Anh Chàng Màu Xanh', 1, NULL, 'all', 0, 0, NULL, -1, 'Gấu Tuyết Thủ Lĩnh dạo này xuất hiện thường xuyên, thợ săn không ai dám đi săn, bọn họ cần tìm một vật màu xanh nghe nói đổi được rất nhiều tiền', '9-2', 9, NULL, NULL),
	(359, 'Ngẫu nhiên nhận được 2 nguyên liệu trang bị và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 9515, 0, 'Tốt nhất là chúng nên tránh đi, cái này...., ngươi không phải là hồ ly biến thành chứ? Ha ha.....', 446, 2, '  Đến Anh Vũ Cảnh thu thập 20 Kính Cận trên người Mèo Kính Đen, sau đó đến chỗ Trưởng Cận Vệ Tiên Lạp Thành nhậh thưởng.', NULL, -1, 39, 30, 0, 1, 'Hồ Ly Gian Xảo', 1, NULL, 'all', 0, 0, NULL, -1, 'Theo phản ánh có hiện tượng hồ ly hại người ở khu vực tiên cảnh Anh vũ, vì hồ ly có khả năng biến hình nhanh nên rất nhiều người bị nó lừa là làm hại. Chúng ta phải cảnh giác', '9-3', 9, NULL, NULL),
	(362, NULL, 1, 6166, 0, 'Cần phải giáo huấn cho đám yêu tinh cây này mới được', 295, 2, 'Đến Quang Bình Nguyên Tiêu diệt Cổ Thụ Thủ Lĩnh, sau đó đến Vệ Sĩ thành Tinh Linh lĩnh thưởng', NULL, -1, 29, 20, 0, 1, 'Tinh Anh Cổ Thụ', 1, NULL, 'all', 0, 0, NULL, -1, 'Cổ Thụ Thủ Lĩnh hành ác dưới lệnh của kẻ địch của thành Tinh Vũ, làm loạn khắp nơi, thành chủ ra lệnh trọng thưởng cho người Tiêu diệt được kẻ đáng ghê tởm kia', '9-2', 9, NULL, NULL),
	(364, 'Ngẫu nhiên nhận được 2 nguyên liệu và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím<cam) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 9515, 0, 'Cái chết của Tướng Lĩnh Sói là đòn tấn công nặng nề với tộc sói, nhưng ta lại lo dẫn đến báo thù mới…', 462, 2, '  Tướng Lĩnh Sói là tinh anh của Lang tộc ở Kỵ Bình Nguyên, tiêu diệt chúng chính là đòn cảnh cáo đối với Lang tộc! Hãy hành động rồi đến chỗ Vệ Sĩ Bàng Bối Thành nhận thưởng.', NULL, -1, 39, 30, 0, 1, 'Tinh Anh Lang Tộc', 1, NULL, 'all', 0, 0, NULL, -1, 'Lần tấn công bọn Lang tộc đã thu được kết quả tốt, nay chúng ta hãy thừa thắng xông lên đập tan chúng một lần nữa', '9-3', 9, NULL, NULL),
	(3671, NULL, 1, 261339, 0, 'Khá lắm, cuối cùng đã thu thập đủ.', 948, 2, 'Giao Vảy Long Vương cho Thổ Long', NULL, -1, 160, 106, 50000, 2, 'Nguồn Sinh Mệnh 13-12', 1, NULL, 'all', 0, 0, NULL, 947, 'Xong rồi, ngươi cầm lấy vật này đi.', '-1', 4, NULL, NULL),
	(367, NULL, 1, 6166, 0, 'Hy vọng thứ này có thể bù đắp những tổn thất của nhà thợ săn', 448, 2, 'Giúp thợ săn bắt 1 Hổ Bì Dương, 1 Gấu Mật ở vùng Lạp Tuyết Địa, sau đó đến chỗ Lão Thợ Săn lĩnh thưởng', NULL, -1, 29, 20, 0, 1, 'Thợ Săn Tham Lam', 1, NULL, 'all', 0, 0, NULL, -1, 'Thủ lĩính gấu dạo này xuất hiện thường xuyên, thợ săn không ai dám đi săn, bọn họ cần tìm một vật màu xanh nghe nói đổi được rất nhiều tiền', '9-2', 9, NULL, NULL),
	(368, 'Ngẫu nhiên nhận được 2 nguyên liệu và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím<cam) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 9515, 0, 'Dũng sĩ chân chính phải dũng cảm đối mặt với thách chiến của Hoa Yêu, ta luôn luôn nói như vậy', 446, 2, '  Đến Anh Vũ Cảnh tiêu diệt Yêu Hoa Vương, sau đó đến chỗ Trưởng Cận Vệ Tiên Lạp Thành nhận thưởng.', NULL, -1, 39, 30, 0, 1, 'Vinh Quang Tột Đỉnh', 1, NULL, 'all', 0, 0, NULL, -1, 'Yêu Hoa Vương ở Anh Vũ Cảnh là tinh anh của yêu hoa, trong nhiều năm qua đã có rất nhiều người mong muốn giết được ả. Không biết các dũng sỹ thời nay liệu có cùng mong muốn đó không?', '9-3', 9, NULL, NULL),
	(370, 'Ngẫu nhiên nhận được 2 nguyên liệu trang bị và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 9515, 0, 'Thôi, hy vọng mọi người lấy đây làm gương, đừng có hại mình hại người', 277, 2, '  Đến Lê Dương Đảo tìm và tiêu diệt Ốc Tiểu Đội Trưởng, sau đó đến chỗ Trưởng Cận Vệ Đông Huyền Thành nhận thưởng.', NULL, -1, 39, 30, 0, 1, 'An Ninh Trong Đảo', 1, NULL, 'all', 0, 0, NULL, -1, 'Truy nã Ốc Tiểu Đội Trưởng và chân tay của hắn, khởi nguồn tội ác do lôi kéo ốc tạo phản khiến loài người và ốc bị thương nặng nề. Chúng ta phải tìm cho ra kẻ cầm đầu tạo phản, Tiêu diệt nó', '9-3', 9, NULL, NULL),
	(371, 'Ngẫu nhiên nhận được 2 nguyên liệu và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím<cam) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 9515, 0, 'Cảm ơn sự giúp đỡ chính nghĩa của người', 295, 2, 'Đến Quang Bình Nguyên tiêu diệt Thủ Lĩnh Cổ Thụ, sau đó đến chỗ Vệ Sĩ  Tinh Linh Thành nhận thưởng.', NULL, -1, 39, 30, 0, 1, 'Cái Giá Tội Ác', 1, NULL, 'all', 0, 0, NULL, -1, 'Thủ Lĩnh Cổ Thụ đã đem Độc Nhãn Tinh đi khắp nơi quậy phá. Thành chủ hạ lệnh, sẽ trao phần thưởng hậu hĩnh cho ai giết được thứ đáng ghét này', '9-3', 9, NULL, NULL),
	(374, 'Ngẫu nhiên nhận được 2 nguyên liệu trang bị và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 9515, 0, 'Dũng sĩ chân chính phải dũng cảm đối mặt với thách chiến của Hoa Yêu, ta luôn luôn nói như vậy', 446, 2, 'Đến Anh Vũ Cảnh tiêu diệt Hoa Yêu Vương, sau đó đến chỗ Trưởng Cận Vệ Tiên Lạp Thành nhận thưởng.', NULL, -1, 39, 30, 0, 1, 'Hoa Yêu Làm Loạn', 1, NULL, 'all', 0, 0, NULL, -1, 'Thì ra tiên cảnh anh vũ lãng mạn kia lại là thánh địa Lữ du, bị Yêu Hoa Vương làm cho khói đen đầy trời, phải đi dạy cho Yêu Hoa Vương một bài học thôi', '9-3', 9, NULL, NULL),
	(383, NULL, 1, 2994, 0, 'Ngươi hãy thử xem sao!', 274, 2, 'Học các tri thức liên quan đến việc dung hợp bảo thạch. Cũng giống như việc dung hợp nguyên liệu, các bảo thạch cao cấp có thể có được thông qua dung hợp nhiều bảo thạch cấp thấp. Trong giao diện Chế tạo, có một hạng mục là Thăng cấp Bảo Thạch, quy tắc ở ', NULL, -1, 160, 10, 500, 1, 'Học Thăng Cấp Bảo Thạch', 1, NULL, 'all', 0, 0, NULL, 274, 'Cũng giống như việc dung hợp nguyên liệu, các bảo thạch cao cấp có thể có được thông qua dung hợp nhiều bảo thạch cấp thấp. Trong giao diện Chế tạo, có một hạng mục là Thăng cấp Bảo Thạch, quy tắc ở đây cũng giống như trong mục Dung hợp nguyên liệu. Hãy thử dung hợp bằng những bảo thạch lúc nãy được tặng xem.', '-1', 1, NULL, NULL),
	(385, NULL, 1, 3309, 0, 'Hãy thử ngay đi!', 274, 2, 'Học các tri thức liên quan đến việc đục lỗ trang bị. Bảo thạch có nhiều rồi, nhưng lỗ trên trang bị thì lại quá ít, vậy phải làm sao? Rất đơn giản, trong giao diện Chế tạo có một hạng mục là Cải tạo trang bị, chọn phần Đục lỗ trong mục này và đặt trang bị', NULL, -1, 160, 10, 500, 1, 'Học Đục Lỗ Trang Bị', 1, NULL, 'all', 0, 0, NULL, 274, 'Bảo thạch có nhiều rồi, nhưng lỗ trên trang bị thì lại quá ít, vậy phải làm sao? Rất đơn giản, trong giao diện Chế tạo có một hạng mục là Cải tạo trang bị, chọn phần Đục lỗ trong mục này và đặt trang bị bạn muốn đục lỗ vào đó, cấp độ và số lượng kim cương cần dùng sẽ hiện lên. Có thể dung hợp kim cương cấp thấp để tạo Kim cương cấp cao trong phần Dung hợp nguyên liệu.', '-1', 1, NULL, NULL),
	(640, NULL, 1, 30000, 0, 'Ha ha, hoan nghênh!', 600, 2, 'Đến Tiên Lạp Thành tìm khảo quan viên (cấp độ nghề phải là sơ cấp thì mới có thể hoàn thành nhiệm vụ)', NULL, -1, 160, 40, 1000, 2, 'Thăng Cấp Trung Cấp 3-1', 1, NULL, '|4|', 0, 0, NULL, 490, 'Trong thời gian tập luyện này, ngươi biểu hiện rất xuất sắc, ta rất hài lòng, ngươi đã đạt tư cách để tìm khảo quan viên ở Tiên Lạp Thành.', '-1', 1, NULL, NULL),
	(642, NULL, 1, 0, 0, 'Ta và thôn dân cám ơn ngươi.', 453, 2, 'Tiêu diệt 25 con Ốc Tiểu Binh', NULL, 3, 20, 16, 2500, 1, 'Nguy Cơ Ốc', 1, NULL, 'all', 0, 0, NULL, 453, 'Thời gian gần đây, những con ốc tụ tập lại thành 1 đội, cư dân ở Ngư Thôn thường bị công kích, ngươi giúp ta giải quyết chúng được chứ?', '-1', 6, NULL, NULL),
