	(3295, '""', 1, 119038, 0, 'Lão này cứ hay mất đồ lung tung!', 462, 2, 'Đến gặp Vệ Sĩ Bàng Bối để tìm hiểu tình hình', NULL, -1, 160, 91, 50000, 2, 'Thất Lạc Thần Bí 14-3', 1, NULL, 'all', 0, 0, NULL, 506, 'Hiện ta không thể rời khỏi đây, ngươi có thể giúp ta đến gặp Vệ Sĩ hỏi thử không? Chắc ông ta biết được tình hình.', '-1', 4, NULL, NULL),
	(3297, '""', 1, 119038, 0, 'À, là việc này sao?', 508, 2, 'Đến gặp Dịch Chuyển Trương Chân Nhân hỏi xem rốt cuộc đã xảy ra chuyện gì', NULL, -1, 160, 91, 50000, 2, 'Thất Lạc Thần Bí 14-5', 1, NULL, 'all', 0, 0, NULL, 462, 'Mấy ngày trước Dịch Chuyển Viên hớt hơ hớt hải chạy đến gặp ta, bào là nhìn thấy những túi đồ chạy lung tung trên đường, lúc đó ta nghĩ ông ta uống say nên hoa mắt, giờ ngươi thử đến tìm ông ta hỏi lại xem sao', '-1', 4, NULL, NULL),
	(3299, '""', 1, 9523050, 0, 'Xem ra ngươi cũng có thành ý, vậy ta sẽ nói cho ngươi biết', 126, 2, 'Tiêu diệt 80 Ma Cát', NULL, -1, 160, 91, 150000, 2, 'Thất Lạc Thần Bí 14-7', 1, NULL, 'all', 0, 0, NULL, 126, 'Gần đây cát thổi ngày càng nhiều, khiến cho nhà ta đâu đâu cũng có cát, chắc hẳn là do bọn Ma Cát làm loạn rồi, ngươi hãy giúp ta tiêu diệt 80 con nhé', '-1', 4, NULL, NULL),
	(3300, '""', 1, 9523050, 0, 'Bọn chúng xuất quỷ nhập thần, phải hết sức cẩn thận đấy!', 126, 2, 'Bắt 1 Nham Quái, tiêu diệt 80 Nham Quái', NULL, -1, 160, 91, 150000, 2, 'Thất Lạc Thần Bí 14-8', 1, NULL, 'all', 0, 0, NULL, 126, 'Ta biết Nham Quái có khả năng đi xuyên qua nham thạch, thường hay phá hoại tường nhà ta, ngươi hãy giúp ta tiêu diệt 80 con, sau đó bắt 1 con mang về đây', '-1', 4, NULL, NULL),
	(3302, NULL, 1, 11903813, 0, 'Ta là ma vương, không bao giờ nuốt lời, hãy cầm về đi', 128, 2, 'Đánh bại Hỏa Ma Vương', NULL, -1, 160, 91, 500000, 2, 'Thất Lạc Thần Bí 14-10', 1, NULL, 'all', 0, 0, NULL, 128, 'Hôm nay bổn đại vương đang vui, chúng ta hãy tỉ thí một phen, nếu ngươi có thể thắng ta thì ta sẽ trả đồ lại cho ngươi, còn nếu như ngươi thua thì phải ở lại đây hầu hạ ta', '-1', 4, NULL, NULL),
	(3304, NULL, 1, 7142288, 0, 'Lần này ta kịp giao hàng cho Thương Hội Trưởng, không bị mất uy tín, thật đa tạ ngươi, đây là phần thưởng của ngươi', 506, 2, 'Bắt 1 Sư Tử Khổng Lồ và mang về 1 Roi Luyện Sư', NULL, -1, 160, 91, 150000, 2, 'Thất Lạc Thần Bí 14-12', 1, NULL, 'all', 0, 0, NULL, 506, 'Quả thật là nhiều hàng quá, một mình ta không thể chuyển nổi, ngươi giúp ta bắt về 1 con Sư Tử Khổng Lồ rồi dến tìm Vua Ma Cát mượn Roi Luyện Sư về nhé', '-1', 4, NULL, NULL),
	(3307, '""', 1, 124930, 0, 'Là ngươi sao?', 218, 2, 'Đến Linh Lan tìm Ngọc Lam', NULL, -1, 160, 100, 60000, 2, 'Phượng Hoàng Phong Ấn 19-1', 1, NULL, 'all', 0, 0, NULL, 421, 'Phong ấn của Phượng Hoàng trong truyền thuyết cần phải có đủ 6 loại ngọc mới có thể mở, nghe nói ở Chỉ Phong Cốc có loại ngọc này, ngươi đi tìm thử xem.', '-1', 4, NULL, NULL),
