	(3836, NULL, 1, 68416, 0, 'Thay mặt dân chúng cám ơn ngài!', 277, 2, 'Tiêu diệt 15 Bạch Kim Thuẫn và 15 Thánh Kiếm, sau đó báo cáo tình hình với Trưởng Cận Vệ Đông Huyền Thành.', NULL, -1, 119, 110, 0, 2, 'Nguy Cơ', 1, NULL, 'all', 0, 0, NULL, -1, 'Nghe nói gần đây tình hình ở Thánh Ước Địa và Thần Di Cảnh khá bất ổn, ngươi hãy đến đó giải quyết.', '9-11', 9, NULL, NULL),
	(3838, NULL, 1, 68416, 0, 'Thay mặt dân chúng cám ơn ngài!', 277, 2, 'Tiêu diệt 15 Bạch Kim Thuẫn và 15 Lợi Trảo Long, sau đó báo cáo tình hình với Trưởng Cận Vệ Đông Huyền Thành.', NULL, -1, 119, 110, 0, 2, 'Nguy Cơ', 1, NULL, 'all', 0, 0, NULL, -1, 'Nghe nói gần đây tình hình ở Thánh Ước Địa và Thần Di Cảnh khá bất ổn, ngươi hãy đến đó giải quyết.', '9-11', 9, NULL, NULL),
	(3842, NULL, 1, 68416, 0, 'Thay mặt dân chúng cám ơn ngài!', 277, 2, 'Tiêu diệt 15 Chim Ưng Cổ và 15 Thần Quan Mất Trí, sau đó báo cáo tình hình với Trưởng Cận Vệ Đông Huyền Thành.', NULL, -1, 119, 110, 0, 2, 'Nguy Cơ', 1, NULL, 'all', 0, 0, NULL, -1, 'Nghe nói gần đây tình hình ở Thánh Ước Địa và Thần Di Cảnh khá bất ổn, ngươi hãy đến đó giải quyết.', '9-11', 9, NULL, NULL),
	(3844, NULL, 1, 68416, 0, 'Thay mặt dân chúng cám ơn ngài!', 277, 2, 'Tiêu diệt 15 Sứ Giả Thánh Quan và 15 Mộng Lão Ông, sau đó báo cáo tình hình với Trưởng Cận Vệ Đông Huyền Thành.', NULL, -1, 119, 110, 0, 2, 'Nguy Cơ', 1, NULL, 'all', 0, 0, NULL, -1, 'Nghe nói gần đây tình hình ở Thánh Ước Địa và Thần Di Cảnh khá bất ổn, ngươi hãy đến đó giải quyết.', '9-11', 9, NULL, NULL),
