	(5215, 'Phần thưởng kinh nghiệm', 1, 0, 1, 'Đây là phần thưởng của ngươi', 280, 2, 'Đến Tuyết Lâm câu 5 con cá Ảo Long', NULL, 2, 160, 50, 0, 2, 'Hồ Đông Huyền - Cá Ảo Long', 1, NULL, 'all', 0, 0, NULL, 280, 'Ao hồ ở Đông Huyền Thành chưa được đẹp lắm, nếu ngươi mang được vài con cá đẹp đến thả vào hồ thì tốt quá!', '-1', 6, NULL, NULL),
	(5218, 'Phần thưởng kinh nghiệm, có xác suất nhận được hạt giống quý hiếm và vật phẩm nhuộm', 1, 0, 1, 'Đây là phần thưởng cho ngươi', 1263, 2, 'Đến nông trường trồng Đậu Nành và Đậu Phộng', NULL, 2, 160, 50, 0, 2, 'Nông Trường Pháp Thuật - Cấp 3', 1, NULL, 'all', 0, 0, NULL, 1263, 'Nông trường hiện đang cần gấp một số Đậu Phộng và Đậu Nành, nếu ngươi giúp ta trồng được một ít thì tốt quá!', '-1', 6, NULL, NULL),
