	(5223, 'Phần thưởng kinh nghiệm, có xác suất nhận được hạt giống quý hiếm và vật phẩm nhuộm', 1, 0, 1, 'Đây là phần thưởng cho ngươi', 1263, 2, 'Đến nông trường trồng Lúa Mạch và Lúa Gạo', NULL, 2, 200, 180, 0, 2, 'Nông Trường Pháp Thuật - Cấp 8', 1, NULL, 'all', 0, 0, NULL, 1263, 'Nông trường hiện đang cần gấp một số Lúa Mạch và Lúa Gạo, nếu ngươi giúp ta trồng được một ít thì tốt quá!', '-1', 6, NULL, NULL),
	(5230, 'Phần thưởng kinh nghiệm', 1, 0, 1, 'Đây là phần thưởng của ngươi', 412, 2, 'Đến Cổ Đạo hoặc Ngọc Phong Lâm thu thập 5 Quy Tâm Thảo', NULL, 2, 160, 50, 0, 2, 'Tiệm Thuốc Đông Huyền - Quy Tâm Thảo', 1, NULL, 'all', 0, 0, NULL, 412, 'Tiệm thuốc ở Đông Huyền Thành đang cần một số dược liệu quý, nếu ngươi có thể giúp thu thập 1 số Quy Tâm Thảo thì tốt quá.', '-1', 6, NULL, NULL),
	(5231, 'Phần thưởng kinh nghiệm', 1, 0, 1, 'Đây là phần thưởng của ngươi', 412, 2, 'Đến Quân Cổ Đạo hoặc Băng Tuyết Nguyên thu thập 5 Thường Thanh Căn', NULL, 2, 160, 50, 0, 2, 'Tiệm Thuốc Đông Huyền - Thường Thanh Căn', 1, NULL, 'all', 0, 0, NULL, 412, 'Tiệm thuốc ở Đông Huyền Thành đang cần một số dược liệu quý, nếu ngươi có thể giúp thu thập 1 số Thường Thanh Căn thì tốt quá.', '-1', 6, NULL, NULL),
	(5233, 'Phần thưởng kinh nghiệm', 1, 0, 1, 'Đây là phần thưởng của ngươi', 412, 2, 'Đến Đông Xuất Vân hoặc Lê Dương Bắc thu thập 5 Khô Diệp Đằng', NULL, 2, 200, 180, 0, 2, 'Tiệm Thuốc Đông Huyền - Khô Diệp Đằng', 1, NULL, 'all', 0, 0, NULL, 412, 'Tiệm thuốc ở Đông Huyền Thành đang cần một số dược liệu quý, nếu ngươi có thể giúp thu thập 1 số Khô Diệp Đằng thì tốt quá.', '-1', 6, NULL, NULL),
	(5235, 'Phần thưởng kinh nghiệm', 1, 0, 1, 'Đây là phần thưởng của ngươi', 412, 2, 'Đến Đông Xuất Vân hoặc Lê Dương Bắc thu thập 5 Ảo Tử Đằng', NULL, 2, 200, 180, 0, 2, 'Tiệm Thuốc Đông Huyền - Ảo Tử Đằng', 1, NULL, 'all', 0, 0, NULL, 412, 'Tiệm thuốc ở Đông Huyền Thành đang cần một số dược liệu quý, nếu ngươi có thể giúp thu thập 1 số Ảo Tử Đằng thì tốt quá.', '-1', 6, NULL, NULL),
	(5237, 'Phần thưởng kinh nghiệm và ngân phiếu, và các phần thưởng bí mật khác', 1, 0, 1, 'Đây là thù lao cho ngươi', 1599, 2, 'Giúp Sứ Giả Sự Kiện Tết Thiếu Nhi đến Lê Dương Bắc, Quang Bình Nguyên, Đông Xuất Vân và Thiên Lục Châu thu hoạch 1 ít quả hạch.', NULL, 5, 200, 200, 0, 1, 'Thu Nhặt Quả Hạch (15 Quả)', 1, NULL, 'all', 0, 0, 'CharLogic.restoreRes(player);', 1599, 'Ở Lê Dương Bắc, Quang Bình Nguyên, Đông Xuất Vân và Thiên Lục Châu có rất nhiều quả hạch chín, có thể dùng làm thức ăn cho Nhím Xanh của ta, ngươi có thể giúp ta nhặt 1 ít không? Tốt nhất cần biến hình thành Nhím Xanh mới nhặt được!', '-1', 6, NULL, NULL),
	(5240, 'Phần thưởng bất ngờ', 1, 0, 0, 'Thu thập nhanh đến thế sao? Ngày Mê Huyễn Động thanh tịnh trở lại không còn xa!', 1617, 2, 'Thu thập 20 tên Tiểu Quỷ Mê Huyễn ở tầng 3 Mê Huyễn Động', NULL, 1, 160, 50, 0, 2, 'Mê Huyễn Động (1)', 1, NULL, 'all', 0, 0, NULL, 1617, 'Cuối cùng các dũng sĩ  cũng đã đến!Sự thanh tịnh vô ưu vốn có ở Mê Huyễn Động đã bị biến đổi thành nơi tà ma nguy hiểm! Muốn đánh bại Cự Ma Mê Huyễn phải thu thập được 20 tên Tiểu Quỷ Mê Huyễn!', '-1', 6, NULL, NULL),
	(5242, 'Phần thưởng bất ngờ', 1, 0, 0, 'Hỡi các dũng sĩ, hãy đánh bại Cự Ma Mê Huyễn!', 1618, 2, 'Sau khi đánh thắng 2 trận với Cự Ma Mê Huyễn hãy thu thập 20 Hoa Linh Hồn để giải trừ bùa chú!', NULL, 1, 160, 50, 0, 2, 'Mê Huyễn Động (3)', 1, NULL, 'all', 0, 0, NULL, 1618, 'Ngươi đã trúng bùa chú của các vong hồn rồi sao? Mau tìm cách giải trừ đi! Nếu không ngươi sẽ bị kiệt sức! Chỉ có Hoa Linh Hồn mới có thể giải trừ bùa chú nhưng nó đang nằm trong tay các Cự Ma. Hãy đánh bại chúng!', '-1', 6, NULL, NULL),
	(5244, 'Kinh nghiệm, ngân phiếu và xác suất nhận thêm Giấy Ước Nguyện, Thư Tỏ Tình', 1, 0, 1, 'Đa tạ! Mong rằng những người yêu nhau sẽ được thành đôi!', 1627, 2, 'Giúp Sứ Giả Thất Tịch bắt 1 vài con côn trùng ở Đông Xuất Vân, Lê Dương Bắc, Anh Vũ Cảnh, Vân Đài làm thức ăn cho Hỷ Thước nhé!', NULL, -1, 160, 30, 0, 1, 'Cho Hỷ Thước ăn', 1, NULL, 'all', 0, 0, NULL, 1627, 'Trong ngày Lễ Thất Tịch, ở Đông Xuất Vân, Lê Dương Bắc, Anh Vũ Cảnh, Vân Đài sẽ xuất hiện 1 đàn Bươm Bướm và Đom Đóm. Hãy bắt chúng để làm thức ăn bắt Hỷ Thước xây cầu Ô Thước giúp Ngưu Lang Chức Nữ gặp nhau bạn nhé!', '-1', 6, NULL, NULL),
	(5246, 'Phần thưởng kinh nghiệm, ngân phiếu và lễ vật cúng bái', 1, 0, 1, 'Đây là Lễ vật cúng bái của người. Hãy thành tâm cúng bái đi nhé!', 1633, 2, 'Giúp Kẻ Gác Cổng Địa Ngục thu thập 1 số Táo, Lúa Gạo và Cá Bống để tạo lễ vật cúng bái nha! Táo có thể tìm hái ở Đông Xuất Vân, Lê Dương Bắc, Anh Vũ Cảnh và Thiên Lục Châu.', NULL, 5, 160, 1050, 0, 1, 'Tạo Lễ Vật Cúng Bái', 1, NULL, 'all', 0, 0, NULL, -1, 'Trong thời gian sự kiện Hàng Phục Yêu Ma, các cư dân cần phải dâng lễ vật cúng bái. Ta cần Lúa Gạo, Táo và Cá Bống để tạo thành lễ vật. Lúa Gạo có thể thu hoạch trên Nông Trường Pháp Thuật. Cá Bống có thể câu được ở Đông Xuất Vân, Lê Dương Bắc. Táo có thể tìm hái ở Đông Xuất Vân, Lê Dương Bắc, Anh Vũ Cảnh và Thiên Lục Châu.', '-1', 6, NULL, NULL),
	(5249, NULL, 1, 0, 1, 'Khá lắm! Khá lắm!', 1633, 2, 'Hoàn thành nhiệm vụ [Tạo Lễ Vật Cúng Bái], sau khi đánh bại lũ quỷ tham ăn sẽ nhận được [Hồn Phách Chi Tinh],khi đã thu thập 1 lượng nhất định Hồn Phách Chi Tinh  hãy đến tìm ta để nhận Danh hiệu Vu Lan nhé! ', NULL, -1, 160, 50, 0, 1, 'Nhận Huân Chương "Đại Sư Trừ Tà"', 1, NULL, 'all', 0, 0, NULL, -1, 'Ngày Lễ Vu Lan đã đến! Hàng trăm quỷ dữ đang vất vưởng trên đất Vô Ưu. Đánh bại chúng sẽ nhận được Hồn Phách Chi Tinh đấy!', '-1', 6, NULL, NULL),
	(5250, 'Nhận được lượng lớn kinh nghiệm, ngân phiếu và pháo hoa Quốc Khánh', 1, 0, 1, 'Haha, hãy đợi xem màn trình diễn pháo hoa buổi tối nhé! Đó là phần thưởng cho ngươi!', 1673, 2, 'Giúp Sứ Giả Quốc Khánh thu thập cánh hoa làm pháo hoa', NULL, -1, 1500, 200, 0, 1, 'Thu Thập Cánh Hoa', 1, NULL, 'all', 0, 0, 'CharLogic.restoreRes(player);', 1673, 'Trong thời gian sự kiện, cần rất nhiều pháo hoa. Nhưng pháo hoa của Vô Ưu không còn nhiều. Cần phải thu thập cánh hoa làm pho hoa ở trên người các niên thú tại Lê Dương Bắc, Lê Dương Đảo, Lạp Tuyết Địa, Anh Vũ !', '-1', 6, NULL, NULL),
	(5251, NULL, 1, 0, 0, 'Mừng trở lại!!!', 1069, 2, 'Vật phẩm thu thập cho bang có thể đem đổi phần thưởng ở đây!', NULL, -1, 160, 10, 0, 2, 'Nhiệm Vụ Đổi Nguyên Liệu Bang 15', 1, NULL, 'all', 0, 0, NULL, 1069, 'Vật phẩm thu thập cho bang có thể đem đổi phần thưởng ở đây!', '-1', 11, NULL, NULL),
	(5278, 'Ngẫu nhiên nhận được 2 nguyên liệu và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím<cam) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 421634, 0, 'Ngươi có thể vượt qua ải sao? Ta thật đã quá xem thường ngươi!', 277, 2, 'Tiêu diệt 1 Thủ Lĩnh Tí Hon, sau khi hoàn thành quay về báo cho Trưởng Cận Vệ Đông Huyền.', NULL, -1, 149, 140, 0, 2, 'Thủ Lĩnh Tí Hon Đáng Ghét', 1, NULL, 'all', 0, 0, NULL, -1, 'Hãy tiêu diệt kẻ cầm đầu của bọn nổi loạn, trả lại sự bình yên cho nơi đây!', '9-14', 9, NULL, NULL),
	(5254, 'Ngẫu nhiên nhận được 2 nguyên liệu và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím<cam) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 421634, 0, 'Cảm ơn ngươi, dũng sĩ của ta!', 1167, 2, 'Giáo huấn 30 Điêu Linh Danh Y, sau khi hoàn thành quay về báo cho Tướng Quân Cô Thôn.', NULL, -1, 149, 140, 0, 2, 'Điêu Linh Danh Y', 1, NULL, 'all', 0, 0, NULL, -1, 'Tướng Quân Cô Thôn thông báo, bắt đầu chỉnh đốn lại trị an ở Điêu Linh Thôn, hi vọng mọi người ra tay giúp sức, sẽ có phần thưởng xứng đáng!', '9-14', 9, NULL, NULL),
	(5257, 'Ngẫu nhiên nhận được 2 nguyên liệu và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím<cam) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 421634, 0, 'Tất cả đều an toàn, cảm tạ ngươi!', 277, 2, 'Giáo huấn 1 Điêu Linh Cuồng Chiến, sau khi hoàn thành quay về báo cho Trưởng Cận Vệ Đông Huyền.', NULL, -1, 149, 140, 0, 2, 'Điêu Linh Cuồng Chiến', 1, NULL, 'all', 0, 0, NULL, -1, 'Nghe nói Điêu Linh Cuồng Chiến là kẻ cầm đầu nổi loạn ở Điêu Linh Thôn, Trưởng Cận Vệ cần người đến đó tiêu diệt hắn.', '9-14', 9, NULL, NULL),
	(5307, NULL, 1, 848113, 0, 'Chuẩn bị lên đường chưa nào?', 427, 2, 'Đi tìm bí mật chuyển sinh trong truyền thuyết', NULL, -1, 200, 200, 50000, 2, 'Chuyển Sinh Lộ 8-1', 1, NULL, '|5|', 15000, 10, NULL, 1666, 'Cổng Ma Giớ đã mở, càng lúc có nhiều yêu ma đến xâm nhập Vô Ưu Đại Lục. Ta cần nâng cao năng lực để chống lại thế giới hắc ám. Hãy đi tìm đạo sư của ngươi. Hắn sẽ cho ngươi biết nên làm gì!', '-1', 10, NULL, NULL),
	(5259, 'Ngẫu nhiên nhận được 2 nguyên liệu và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím<cam) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 421634, 0, 'Rất cảm ơn, người bạn mới của ta!', 1171, 2, 'Tiêu diệt 30 Gấu Mật Mị Hoặc, sau khi hoàn thành quay về báo cho Người Chăm Sóc Rừng.', NULL, -1, 149, 140, 0, 2, 'Gấu Mật Mị Hoặc', 1, NULL, 'all', 0, 0, NULL, -1, 'Người Chăm Sóc Rừng cho biết hiện tại trong Mị Hoặc Lâm có rất nhiều quái vật quấy phá, cần phải chỉnh đốn lại tình hình trị an, hi vọng mọi người hãy ra tay tương trợ, sẽ có phần thưởng xứng đáng!', '9-14', 9, NULL, NULL),
	(5260, 'Ngẫu nhiên nhận được 2 nguyên liệu và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím<cam) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 421634, 0, 'Rất cảm ơn, người bạn mới của ta!', 1171, 2, 'Tiêu diệt 30 Tí Hon Rừng Rậm, sau khi hoàn thành quay về báo cho Người Chăm Sóc Rừng.', NULL, -1, 149, 140, 0, 2, 'Tí Hon Rừng Rậm', 1, NULL, 'all', 0, 0, NULL, -1, 'Người Chăm Sóc Rừng cho biết hiện tại trong Mị Hoặc Lâm có rất nhiều quái vật quấy phá, cần phải chỉnh đốn lại tình hình trị an, hi vọng mọi người hãy ra tay tương trợ, sẽ có phần thưởng xứng đáng!', '9-14', 9, NULL, NULL),
	(5261, 'Ngẫu nhiên nhận được 2 nguyên liệu và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím<cam) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 421634, 0, 'Rất cảm ơn, người bạn mới của ta!', 1171, 2, 'Tiêu diệt 30 Người Rơm, sau khi hoàn thành quay về báo cho Người Chăm Sóc Rừng.', NULL, -1, 149, 140, 0, 2, 'Người Rơm', 1, NULL, 'all', 0, 0, NULL, -1, 'Người Chăm Sóc Rừng cho biết hiện tại trong Mị Hoặc Lâm có rất nhiều quái vật quấy phá, cần phải chỉnh đốn lại tình hình trị an, hi vọng mọi người hãy ra tay tương trợ, sẽ có phần thưởng xứng đáng!', '9-14', 9, NULL, NULL),
	(5264, 'Ngẫu nhiên nhận được 2 nguyên liệu và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím<cam) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 421634, 0, 'Màu sắc cũng không tệ, đáng thu hoạch!', 3, 2, 'Thu thập 5 Đồng Vàng Cổ giao cho Quan Quân Nhu Đông Huyền Thành', NULL, -1, 149, 140, 0, 2, 'Đồng Vàng Cổ', 1, NULL, 'all', 0, 0, NULL, -1, 'Nghe nói gần đây Quan Quân Nhu đang cần một số món đồ cổ, ngươi đến đó thử xem sao!', '9-14', 9, NULL, NULL),
	(5267, 'Ngẫu nhiên nhận được 2 nguyên liệu và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím<cam) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 421634, 0, 'Anh bạn trẻ, cảm ơn đã giúp ta!', 272, 2, 'Thu thập 2 Ngũ Sắc Thần Thạch rồi chuyển đến cho tộc trưởng Bối Tư.', NULL, -1, 149, 140, 0, 2, 'Ngũ Sắc Thần Thạch', 1, NULL, 'all', 0, 0, NULL, -1, 'Tộc Trưởng Bối Tư đang thu thập một số Ngũ Sắc Thần Thạch, ông ấy đã có tuổi, ngươi nên đi giúp ông ấy.', '9-14', 9, NULL, NULL),
	(5270, 'Ngẫu nhiên nhận được 2 nguyên liệu và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím<cam) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 421634, 0, 'Tuy có hơi nhỏ nhưng cũng không tệ, cảm ơn ngươi!', 274, 2, 'Thu thập 3 Toái Liệt Lực Thạch giao cho Mark ở tiệm vũ khí Đông Huyền Thành.', NULL, -1, 149, 140, 0, 2, 'Toái Liệt Lực Thạch', 1, NULL, 'all', 0, 0, NULL, -1, 'Mark ở tiệm vũ khí Đông Huyền Thành đang cần thu thập các loại Bảo Thạch nhưng lại bận quá, thử đến giúp anh ta xem!', '9-14', 9, NULL, NULL),
	(5273, 'Ngẫu nhiên nhận được 2 nguyên liệu và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím<cam) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 421634, 0, 'Tiểu tử thật không đơn giản. Xem ra ngươi vẫn còn tiền đồ phía trước đó. Hãy cố gắng nâng cao nhé!', 277, 2, 'Đến Điêu Linh Thôn tiêu diệt 20 Điêu Linh Chiến Sĩ, rồi đến Mị Hoặc Lâm tiêu diệt 20 Bạo Liệt Long, sau khi hoàn thành thì về báo cho Trưởng Cận Vệ Đông Huyền.', NULL, -1, 149, 140, 0, 2, 'Diễn Tập Cấp Cao', 1, NULL, 'all', 0, 0, NULL, -1, 'Cuộc diễn tập cấp cao ở Đông Huyền Thành, tự nguyện báo danh, chính thức bắt đầu!', '9-14', 9, NULL, NULL),
	(5275, 'Ngẫu nhiên nhận được 2 nguyên liệu và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím<cam) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 421634, 0, 'Tiểu tử thật không đơn giản. Xem ra ngươi vẫn còn tiền đồ phía trước đó. Hãy cố gắng nâng cao nhé!', 277, 2, 'Đến Điêu Linh Thôn tiêu diệt 20 Điêu Linh Danh Y, rồi đến Mị Hoặc Lâm tiêu diệt 20 Gấu Mật Mị Hoặc, sau khi hoàn thành thì về báo cho Trưởng Cận Vệ Đông Huyền.', NULL, -1, 149, 140, 0, 2, 'Báo Danh Diễn Tập', 1, NULL, 'all', 0, 0, NULL, -1, 'Cuộc diễn tập cấp cao ở Đông Huyền Thành, tự nguyện báo danh, chính thức bắt đầu!', '9-14', 9, NULL, NULL),
	(5277, 'Ngẫu nhiên nhận được 2 nguyên liệu và 1 Lệnh bài treo thưởng, phẩm chất nhiệm vụ càng cao (trắng<lục<xanh<tím<cam) thì xác suất nhận được nguyên liệu cấp cao càng cao', 1, 421634, 0, 'Ngươi có thể vượt qua ải sao? Ta thật đã quá xem thường ngươi!', 277, 2, 'Tiêu diệt 1 Điêu Linh Cuồng Chiến, sau khi hoàn thành quay về báo cho Trưởng Cận Vệ Đông Huyền.', NULL, -1, 149, 140, 0, 2, 'Quét Sạch Điêu Linh Cuồng Chiến', 1, NULL, 'all', 0, 0, NULL, -1, 'Hãy tiêu diệt kẻ cầm đầu của bọn nổi loạn, trả lại sự bình yên cho nơi đây!', '9-14', 9, NULL, NULL),
