	(5474, 'Kinh nghiệm, ngân phiếu, phần thưởng, thức ăn, danh hiệu', 1, 0, 1, 'Hãy thưởng thức hương vị bánh trung thu tuyệt hảo của Đại Lục Vô Ưu', 1943, 2, 'Cần 3 Lúa mạch và 3 Đậu Nành<font color="#FF0000">(Túi cần ít nhất 1 ô trống)</font>', NULL, 3, 160, 50, 0, 1, 'Làm Bánh Trung Thu', 1, NULL, 'all', 0, 0, NULL, 1943, 'Trung Thu thì phải có bánh trung thu. Hãy thu thập các nguyên liệu, ta sẽ giúp ngươi nấu bánh.', '-1', 6, NULL, NULL),
	(5476, 'Phần thưởng chưa biết', 1, 0, 0, 'Làm tốt lắm! Ta còn có 1 nhiệm vụ khác giao cho mọi người!', 1948, 2, 'Tiêu diệt tất cả Tiểu Binh Quân Địch xung quanh cứ điểm của ta', NULL, 1, 160, 50, 0, 2, 'Cứ Điểm Vĩnh Dạ', 1, NULL, 'all', 0, 0, NULL, 1948, 'Các dũng sĩ, mọi người đến thật đúng lúc. Chắc mọi người cũng đã biết tình hình nghiêm trọng thế nào. Hãy mau giúp ta tiêu diệt tất cả Tiểu Binh Quân Địch xung quanh cứ điểm của chúng ta!', '-1', 6, NULL, NULL),
	(5478, 'Phần thưởng chưa biết', 1, 0, 0, 'Đúng là thần dũng! Tin rằng nhiệm vụ sau mọi người cũng sẽ hoàn thành tốt!', 1950, 2, 'Tìm vật tư và chuyển đến cho Binh Sĩ Tiền Tuyến (nhấp đôi vào Định Vị Phù để hiển thị địa điểm của vật tư)', NULL, 1, 160, 50, 0, 2, 'Vận Chuyển Vĩnh Dạ', 1, NULL, 'all', 0, 0, NULL, 1948, 'Ở đây còn ẩn giấu rất nhiều vật tư. Định Vị Phù sẽ giúp tìm ra vị trí của chúng. Hãy dựa vào các chỉ thị trên đây tìm vật tư', '-1', 6, NULL, NULL),
	(5481, 'Phần thưởng chưa biết', 1, 0, 0, 'Rất tốt!', 1959, 2, 'Giúp Pháp Sư bố trí Bảo Thạch Năng Lượng và yểm trợ cho ông ấy an toàn rời khỏi chiến trường (nhấp đôi vào Bảo Thạch Năng Lượng để hiển thị địa điểm và chuyển đến đó)', NULL, 1, 160, 50, 0, 2, 'Rút Binh Vĩnh Dạ', 1, NULL, 'all', 0, 0, NULL, 1959, 'Hệ thống phòng ngự đã mở, bây giờ chỉ cần đặt Năng Lượng Bảo Thạch đúng vị trí nữa là được. Chỉ cần nhấp chọn sử dụng, sẽ hiển thị vị trí này', '-1', 6, NULL, NULL),
