	(7440, 'Kinh nghiệm, bạc', 1, 0, 0, 'Các ngươi làm rất tốt.', 246, 2, 'Hãy cùng với người yêu đi đến một nơi phong cảnh hữu tình để du ngoạn (Nhấp đôi vào 【Hướng Dẫn Danh Lam】 để xem thông tin chi tiết)', NULL, -1, 160, 50, 0, 2, 'Ngao Du Sơn Thủy', 1, NULL, 'all', 0, 0, NULL, -1, 'Các cặp tình nhân tâm sự thì cần đến một nơi phong cảnh hữu tình, cảnh sắc lãng mạn, giờ ta giao cho ngươi Hướng Dẫn Danh Lam, 2 người hãy cùng đi đến đó để thắt chặt thêm tình cảm.', '7-3', 7, NULL, NULL),
	(7442, 'Kinh nghiệm, bạc', 1, 0, 0, 'Các ngươi làm rất tốt.', 246, 2, 'Hãy cùng với người yêu đến địa điểm chỉ định để trồng hoa hồng (nhấp đôi vào 【Hạt Giống Hoa Hồng】 để xem thông tin chi tiết, nhóm trưởng trồng hạt giống trước, sau đó thành viên trong nhóm sẽ tưới nước)', NULL, -1, 160, 50, 0, 2, 'Trồng Hoa Hồng', 1, NULL, 'all', 0, 0, NULL, -1, 'Trong thời gian Lễ tình nhân, các cặp yêu nhau nên tặng hoa hồng cho nhau để bày tỏ tình cảm. Ta có vài hạt giống hoa hồng, ngươi hãy cùng đi trồng với người yêu đi. Hạt giống này cần 1 người trồng 1 người tưới, nhớ phân công công việc nhé.', '7-3', 7, NULL, NULL),
	(7536, NULL, 1, 0, 0, 'Làm khá lắm, ta quả không nhìn sai', 434, 2, 'So tài cao thấp với các đệ tử tinh anh của Tộc Huyền Lâm (độ khó cao, cần lập nhóm đủ thành viên để khiêu chiến)', NULL, -1, 160, 70, 0, 2, 'Tộc Huyền Lâm Tu Luyện', 1, NULL, 'all', 0, 0, NULL, -1, 'Đến Tộc Huyền Lâm để thách đấu với các đệ tử tinh anh của tộc và đánh bại họ', '7-6', 7, NULL, NULL),
