	(7662, 'Phần thưởng thần tu', 1, 0, 1, 'Cảm ơn ngươi! Đây là báo đáp của ta!', 929, 2, 'Dựa vào chỉ thị, đi tiêu diệt 72 tên ma thần của Solomon.', NULL, -1, 160, 50, 0, 2, 'Nhiệm Vụ Thần Tu', 1, NULL, 'all', 0, 2, NULL, -1, 'Thời thượng cổ, rất nhiều Ma Thần đã bị 6 vị Trưởng Lão phong ấn dưới lòng cực địa, không thể quay lại gây hại nhân gian. Nhưng nhiều năm sau, 1 số tên có ma pháp cao thâm đã có thể phá vỡ phong ấn, thoát ra ngoài làm loạn. Hi vọng sẽ có dũng sĩ lên đường tiêu diệt chúng.', '7-7', 7, NULL, NULL),
	(7663, 'Phần thưởng thần tu', 1, 0, 1, 'Cảm ơn ngươi! Đây là báo đáp của ta!', 929, 2, 'Dựa vào chỉ thị, đi tiêu diệt 72 tên ma thần của Solomon.', NULL, -1, 160, 50, 0, 2, 'Nhiệm Vụ Thần Tu', 1, NULL, 'all', 0, 2, NULL, -1, 'Thời thượng cổ, rất nhiều Ma Thần đã bị 6 vị Trưởng Lão phong ấn dưới lòng cực địa, không thể quay lại gây hại nhân gian. Nhưng nhiều năm sau, 1 số tên có ma pháp cao thâm đã có thể phá vỡ phong ấn, thoát ra ngoài làm loạn. Hi vọng sẽ có dũng sĩ lên đường tiêu diệt chúng.', '7-7', 7, NULL, NULL),
	(7664, 'Phần thưởng thần tu', 1, 0, 1, 'Cảm ơn ngươi! Đây là báo đáp của ta!', 929, 2, 'Dựa vào chỉ thị, đi tiêu diệt 72 tên ma thần của Solomon.', NULL, -1, 160, 50, 0, 2, 'Nhiệm Vụ Thần Tu', 1, NULL, 'all', 0, 2, NULL, -1, 'Thời thượng cổ, rất nhiều Ma Thần đã bị 6 vị Trưởng Lão phong ấn dưới lòng cực địa, không thể quay lại gây hại nhân gian. Nhưng nhiều năm sau, 1 số tên có ma pháp cao thâm đã có thể phá vỡ phong ấn, thoát ra ngoài làm loạn. Hi vọng sẽ có dũng sĩ lên đường tiêu diệt chúng.', '7-7', 7, NULL, NULL),
	(7667, 'Ngân phiếu', 1, 0, 0, 'Người là niềm tự hào của Đông Huyền', 277, 2, 'Theo chỉ thị tìm bắt Hải Tặc', NULL, -1, 160, 30, 0, 2, 'Phản Quân Hải Tặc', 1, NULL, 'all', 0, 2, NULL, -1, 'Gần đây, một số tướng địch đã dẫn theo các đội của mình xuất quỷ nhập thần xung quanh Đông Huyền, liên tục tấn công tuyến tiếp tế của chúng ta, gây ảnh hưởng lớn đến việc tiếp tế vật tư của chúng ta. Trong khi đó, mặt trận phía trước đang căng thẳng, không có đủ người để quay lại phòng thủ. Bạn là học viên xuất sắc nhất của Đông Huyền, hy vọng bạn có thể giúp tôi tiêu diệt họ, đảm bảo an toàn cho tuyến tiếp tế', '7-4', 7, NULL, NULL),
