	(9086, 'Phần thưởng chưa biết', 1, -1, 1, 'Ha ha, ta đợi ngươi lâu rồi, xem ra ngươi cũng đã hoàn thành nhiệm vụ, giờ ta sẽ ban phúc cho ngươi.', 272, 2, 'Thiên Sứ hiện thân ngay trước mặt bạn, ban cho bạn lời chúc phúc, hãy đi tiêu diệt 10 Nấm Cực Độc ở Tháp Khắc Nguyên, sau đó đến chỗ tộc trưởng Bối Tư ở Đông Huyền Thành lãnh thưởng.', NULL, -1, 160, 50, 0, 2, 'Thiên Sứ Hạ Phàm', 1, NULL, 'all', 0, 0, NULL, -1, 'Xin chào dũng sĩ của Vô Ưu Đại Lục, ta là Thiên Sứ Eva, ngươi là gười may mắn nhất trong hàng vạn người nhận được lời chúc phúc của Thánh Quang. Nhưng trước tiên, ngươi phải trải qua 1 thử nghiệm nhỏ: Đến Tháp Khắc Nguyên tiêu diệt 10 Nấm Cực Độc. Nếu ngươi hoàn thành được, tộc trưởng Bối Tư ở Đông Huyền Thành sẽ thay ta ban phúc cho ngươi.', '12-1', 12, NULL, NULL),
	(9087, 'Phần thưởng chưa biết', 1, -1, 1, 'Ha ha, ta đợi ngươi lâu rồi, xem ra ngươi cũng đã hoàn thành nhiệm vụ, giờ ta sẽ ban phúc cho ngươi.', 272, 2, 'Thiên Sứ hiện thân ngay trước mặt bạn, ban cho bạn lời chúc phúc, hãy đi tiêu diệt 10 Thủ Vệ Sói Mẹ ở Tháp Khắc Nguyên, sau đó đến chỗ tộc trưởng Bối Tư ở Đông Huyền Thành lãnh thưởng.', NULL, -1, 160, 50, 0, 2, 'Thiên Sứ Hạ Phàm', 1, NULL, 'all', 0, 0, NULL, -1, 'Xin chào dũng sĩ của Vô Ưu Đại Lục, ta là Thiên Sứ Eva, ngươi là gười may mắn nhất trong hàng vạn người nhận được lời chúc phúc của Thánh Quang. Nhưng trước tiên, ngươi phải trải qua 1 thử nghiệm nhỏ: Đến Tháp Khắc Nguyên tiêu diệt 10 Thủ Vệ Sói Mẹ. Nếu ngươi hoàn thành được, tộc trưởng Bối Tư ở Đông Huyền Thành sẽ thay ta ban phúc cho ngươi.', '12-1', 12, NULL, NULL),
