	(31515, 'Phần thưởng kinh nghiệm, ngân phiếu và vật phẩm bất ngờ!', 1, 0, 1, 'Rất cảm ơn ngươi! Đây là phần thưởng của ngươi!', 1729, 2, 'Giúp Sứ Giả Đoan Ngọ mang những nguyên liệu tạo túi thơm về', NULL, 5, 160, 30, 0, 1, 'Tạo Túi Thơm', 1, NULL, 'all', 0, 0, NULL, 1729, 'Tạo Túi Thơm trong ngày Tết Đoan Ngọ đã là phong tục của Đại Lục Vô Ưu, các bạn có thể giúp ta tìm nguyên liệu được không? Lá Ngải Cứu có thể tìm ở Lê Dương Bắc, Quang Bình Nguyên, Đông Xuất Vân, Thiên Lục Châu, đá Hùng Hoàng thì có thể mua ở ta.', '-1', 6, NULL, NULL),
	(31517, 'Phần thưởng kinh nghiệm và vật phẩm ngẫu nhiên', 1, 0, 2, 'Rất tốt, tiếp theo là phần 【Đầu Rồng Lớn】', 1730, 2, 'Đến Thế Giới Hải Dương tìm gặp Long Vương mang về 1 【Đuôi Rồng Lớn】', NULL, -1, 200, 200, 0, 1, 'Vận Chuyển 【Đuôi Rồng】', 1, NULL, 'all', 0, 0, NULL, 1730, 'Mỗi năm cứ đến ngày Tết Đoan Ngọ là lúc đại hội Long Đan cũng bắt đầu, nhưng những nguyên liệu để luyện nên Long Đan vẫn còn thiếu, để bảo đảm cho Đại Hội được diễn ra suôn sẻ, hãy mang đến 【Đuôi Rồng Lớn】đến cho ta!', '-1', 6, NULL, NULL),
	(31518, 'Phần thưởng kinh nghiệm và vật phẩm ngẫu nhiên', 1, 0, 3, 'Rất tốt, Long Đan đã được luyện thành!', 1730, 2, 'Đến Thế Giới Hải Dương tìm gặp Long Vương mang về 1 【Đầu Rồng Lớn】', NULL, -1, 200, 200, 0, 1, 'Vận Chuyển 【Đầu Rồng】', 1, NULL, 'all', 0, 0, NULL, 1730, 'Mỗi năm cứ đến ngày Tết Đoan Ngọ là lúc đại hội Long Đan cũng bắt đầu, nhưng những nguyên liệu để luyện nên Long Đan vẫn còn thiếu, để bảo đảm cho Đại Hội được diễn ra suôn sẻ, hãy mang đến 【Đầu Rồng Lớn】đến cho ta!', '-1', 6, NULL, NULL),
	(31526, NULL, 1, 0, 4, 'Người là anh hùng của Đại Lục Vô Ưu này', 272, 2, 'Tiêu diệt Mehdi Urboss và Fernando trong Sổ tay ma thú', NULL, -1, 200, 150, 0, 1, 'Cứu Giúp Đại Lục!', 1, NULL, 'all', 0, 0, NULL, 272, 'Mehdi Urboss và Fernando luôn tìm cách phá hoại Đại Lục Vô Ưu, trong thời khắc quan trọng này, chỉ có người mới có thể cứu giúp Vô Ưu thoát khỏi cảnh chết chóc hoang tàn. Hãy đến Cổ Thành để tiêu diệt bọn chúng giúp chúng tôi.', '-1', 4, NULL, NULL),
	(31527, 'Phần thưởng kinh nghiệm và ngân phiếu', 1, 0, 2, 'Rất tốt, ngươi đã vượt qua vòng thử thách đầu tiên!', 1761, 2, 'Vòng thử thách đầu tiên là đấu trí để xem trình độ học thức và lý luận của các dũng sĩ! Có thể đến (46,135) tìm Đạo Sư Lưu Hỏa hoặc Đạo Sư Liêu Vân để tham gia!', NULL, -1, 160, 50, 0, 2, 'Đấu Trí', 1, NULL, 'all', 0, 0, NULL, 1761, 'Ngày kỷ niệm thành lập Học Viên đã đến cũng là lúc để các dũng sĩ thể hiện tài năng cảu mình. Mỗi dũng sĩ cần phần lần lượt vượt qua các thử thách của các Đạo Sư thì mới có thể hoàn thành nhiệm vụ.', '-1', 6, NULL, NULL),
	(31529, 'Phần thưởng kinh nghiệm và ngân phiếu', 1, 0, 2, 'Rất tốt, ngươi đã vượt qua vòng thử thách thứ 3! Chiến thắng đang chờ phía trước', 1761, 2, 'Vòng thử thách thứ 3 là chiến đấu! Thực lực của mọi người như thế nào? Không thể quá sơ sài! Hãy đến tìm Đạo Sư Bàn Địa (258,95) để tham gia so tài!', NULL, -1, 160, 50, 0, 2, 'Chiến Cuộc 2', 1, NULL, 'all', 0, 0, NULL, 1761, 'Ngày kỷ niệm thành lập Học Viên đã đến cũng là lúc để các dũng sĩ thể hiện tài năng cảu mình. Mỗi dũng sĩ cần phần lần lượt vượt qua các thử thách của các Đạo Sư thì mới có thể hoàn thành nhiệm vụ.', '-1', 6, NULL, NULL),
	(31532, 'Phần thưởng kinh nghiệm và ngân phiếu', 1, 0, 2, 'Cố lên, chỉ cần vượt qua thử thách này, thắng lợi đang chờ trước mắt.', 1761, 2, 'Vòng thử thách thứ 4 khảo sát thực lực thật sự của các dũng sĩ! Hãy tìm Đạo Sư Thiên Khung (124,182) để thử sức nhé!', NULL, -1, 160, 50, 0, 2, 'Chiến Cuộc 2', 1, NULL, 'all', 0, 0, NULL, 1761, 'Ngày kỷ niệm thành lập Học Viên đã đến cũng là lúc để các dũng sĩ thể hiện tài năng cảu mình. Mỗi dũng sĩ cần phần lần lượt vượt qua các thử thách của các Đạo Sư thì mới có thể hoàn thành nhiệm vụ.', '-1', 6, NULL, NULL),
