	(50309, 'Phần thưởng bí mật', 1, 3275522, 0, 'Bầu không khí thật khác thường', 2400, 2, 'Chào mừng đến Thiên Không Thành, ta là Thành Chủ Thiên Không Thành', NULL, -1, 160, 151, 500000, 2, 'Yết Kiến Thành Chủ Thiên Không Thành', 1, NULL, 'all', 0, 0, NULL, 639, 'Ngươi đến để yết kiến Thiên Không Thành Chủ?', '-1', 2, NULL, NULL),
