	(50625, NULL, 1, 6000, 1, 'Nước bên Lê Dương có vấn đề sao? Không phải chứ', 468, 2, 'Đến Lê Dương Đảo tìm Quan Tuần Tra Lê Dương', NULL, -1, 200, 200, 3600, 1, 'Sơn Vũ Dục Lai 2', 1, NULL, 'all', 0, 0, NULL, 272, 'Theo kết quả điều tra của Nghiên Cứu Gia XX, hình như nguồn nước ở Xuất Vôn Thôn đang bị ô nhiễm. Nước ở Xuất Vân Thôn bắt nguồn từ Lê Dương , e là ở đó đã xảy ra chuyện. Ngươi đi tìm gặp Tuần Tra Lê Dương xem sao', '-1', 6, NULL, NULL),
	(50627, NULL, 1, 60000, 1, 'Phù, rốt cuộc cũng thảnh thơi', 454, 2, 'Tiêu diệt toàn bộ Lê Dương Hồ Tặc', NULL, -1, 200, 200, 36000, 1, 'Sơn Vũ Dục Lai 4', 1, NULL, 'all', 0, 0, NULL, 454, 'Hồ Tặc đột nhiên tập kích, có chuyện gì thì hãy đợi giải quyết bọn chung xong rồi nói', '-1', 6, NULL, NULL),
	(50628, NULL, 1, 90000, 1, 'Cái gì? Phát hiện một bức thư kỳ lạ à?', 454, 2, 'Tiêu diệt Thủ Lĩnh Hồ Tặc (Thủ Lĩnh Hồ Tặc đã rời khỏi đây, hiện đang phá hoại trong thôn, không kiêng nể ai)', NULL, -1, 200, 200, 54000, 1, 'Sơn Vũ Dục Lai 5', 1, NULL, 'all', 0, 0, NULL, 454, 'Muốn bắt trộm phải bắt tên đầu sỏ trước. Bây giờ tuy là tạm thời đẩy lùi được Hồ Tặc nhưng để phòng trường hợp chúng quay lại, ngươi hãy đi tiêu diệt Thủ Lĩnh Hồ Tặc đi', '-1', 6, NULL, NULL),
	(50633, NULL, 1, 90000, 1, 'Vất vả rồi', 272, 2, 'Tiêu diệt Vu Yêu Vương Gấu Trúc (Vu Yêu Vương Gấu Trúc có thể nghe được âm thanh trong góp, nên ẩn trốn dễ dàng. Hãy đến Trầm Thụy Lâm tìm thử)', NULL, -1, 200, 200, 54000, 1, 'Sơn Vũ Dục Lai 10', 1, NULL, 'all', 0, 0, NULL, 272, 'Đây là mật thư của Vu Yêu Vương Gấu Trúc, trong thư là các sử dụng một loại thuốc nào dó. Xem ra sự việc lần này không liên quan đến hắn. Ngươi hãy đi tìm hắn xem có nghe ngóng được các giải không', '-1', 6, NULL, NULL),
	(50635, NULL, 1, 30000, 1, 'Đã giải quyết ổn thoải rồi à?', 272, 2, 'Đến Đông Huyền Thành tìm Tộc Trưởng Bối Tư', NULL, -1, 200, 200, 18000, 1, 'Sơn Vũ Dục Lai 12', 1, NULL, 'all', 0, 0, NULL, 468, 'Ta sẽ dựa vào hướng dẫn mà làm, chắc phải tốn một khoảng thời gian. Ngươi hãy mau về báo cáo cho Tộc Trưởng Bối Tư trước đi', '-1', 6, NULL, NULL),
	(50637, NULL, 1, 30000, 1, 'Ta đã nắm tình hình, hãy giúp ta mang thư hồi đáp', 435, 2, 'Giao thư của Tộc Trưởng Bối Tư cho Thành Chủ Bàng Bối', NULL, -1, 200, 200, 18000, 1, 'Sơn Vũ Dục Lai 14', 1, NULL, 'all', 0, 0, NULL, 435, 'Thư của Tộc Trưởng Bối Tư? Đưa ta xem.', '-1', 6, NULL, NULL),
	(50640, NULL, 1, 300000, 1, 'Vất vả rồi, đây là phần thưởng của ngươi.', 272, 2, 'Đến Đông Huyền Thành tìm Tộc Trưởng Bối Tư', NULL, -1, 200, 200, 180000, 1, 'Sơn Vũ Dục Lai 17', 1, NULL, 'all', 0, 0, NULL, 272, 'Coi như cũng đã an tâm để đón lễ rồi. Vất vả cho ngươi rồi.', '-1', 6, NULL, NULL),
	(50642, NULL, 1, 0, 1, 'Đây là tinh linh của ngươi!', 1519, 2, 'Thu thập 4 Thẻ Bài Tinh Linh để đổi lấy 1 Tinh Linh', NULL, 1, 160, 50, 0, 2, 'Đổi Tinh Linh Halloween', 1, NULL, 'all', 0, 2, NULL, 1519, 'Thu thập 4 Thẻ Bài Tinh Linh sẽ đổi được 1 Tinh Linh', '-1', 6, NULL, NULL),
	(50645, 'Nhận 1 Socola Matcha', 1, 0, 1, 'Hãy thưởng thức tài nghệ của ta. Lễ Tình Nhân vui vẻ!', 376, 2, 'Mang Bột Cacao, Sữa Tươi, Bột Matcha giao cho Nhà Hàng Âu Dương, họ sẽ giúp bạn chế biến Socola Matcha的！', NULL, -1, 160, 50, 0, 2, 'Làm Socola Matcha', 1, NULL, 'all', 100000, 1, NULL, 376, 'Ngày lễ Tình Nhân đã đến,  muốn tự làm socola tặng người thương? Ok, chỉ cần Mang Bột Cacao, Sữa Tươi, Bột Matcha giao cho ta, ta sẽ giúp ngươi chế biến Socola Matcha miễn phí. Lẽ nào ngươi không tin vào tay nghề của ta?', '-1', 6, NULL, NULL),
	(50646, 'Nhận 1 Socola Tan Chảy', 1, 0, 1, 'Hãy thưởng thức tài nghệ của ta. Lễ Tình Nhân vui vẻ!', 376, 2, 'Mang Bột Cacao, Sữa Tươi, Rượu Rum giao cho Nhà Hàng Âu Dương, họ sẽ giúp bạn chế biến Socola Tan Chảy的！', NULL, -1, 160, 50, 0, 2, 'Làm Socola Tan Chảy', 1, NULL, 'all', 100000, 1, NULL, 376, 'Ngày lễ Tình Nhân đã đến,  muốn tự làm socola tặng người thương? Ok, chỉ cần Mang Bột Cacao, Sữa Tươi, Rượu Rum giao cho ta, ta sẽ giúp ngươi chế biến Socola Tan Chảy miễn phí. Lẽ nào ngươi không tin vào tay nghề của ta?', '-1', 6, NULL, NULL),
	(50648, 'Nhận 1 Socola Bạc Hà', 1, 0, 1, 'Hãy thưởng thức tài nghệ của ta. Lễ Tình Nhân vui vẻ!', 376, 2, 'Mang Bột Cacao, Sữa Tươi, Tinh Dầu Bạc Hà giao cho Nhà Hàng Âu Dương, họ sẽ giúp bạn chế biến Socola Bạc Hà的！', NULL, -1, 160, 50, 0, 2, 'Làm Socola Bạc Hà', 1, NULL, 'all', 100000, 1, NULL, 376, 'Ngày lễ Tình Nhân đã đến,  muốn tự làm socola tặng người thương? Ok, chỉ cần Mang Bột Cacao, Sữa Tươi, Tinh Dầu Bạc Hà giao cho ta, ta sẽ giúp ngươi chế biến Socola Bạc Hà miễn phí. Lẽ nào ngươi không tin vào tay nghề của ta?', '-1', 6, NULL, NULL),
	(50650, 'Nhận 10 Socola Tan Chảy', 1, 0, 1, 'Hãy thưởng thức tài nghệ của ta. Lễ Tình Nhân vui vẻ!', 376, 2, 'Mang Bột Cacao, Sữa Tươi, Rượu Rum giao cho Nhà Hàng Âu Dương, họ sẽ giúp bạn chế biến Socola Tan Chảy的！', NULL, -1, 160, 50, 0, 2, 'Làm Socola Tan Chảy (10 Viên)', 1, NULL, 'all', 1000000, 1, NULL, 376, 'Ngày lễ Tình Nhân đã đến,  muốn tự làm socola tặng người thương? Ok, chỉ cần Mang Bột Cacao, Sữa Tươi, Rượu Rum giao cho ta, ta sẽ giúp ngươi chế biến Socola Tan Chảy miễn phí. Lẽ nào ngươi không tin vào tay nghề của ta?', '-1', 6, NULL, NULL),
	(50678, NULL, 1, 90000, 1, 'Cái gì? Phát hiện được 1 bức thư kỳ quái?', 454, 2, 'Tiêu diệt Thủ Lĩnh Hồ Tặc (Thủ Lĩnh Hồ Tặc đã chạy thoát thân vào trong thôn, hãy đó đó mà tìm)', NULL, -1, 160, 50, 54000, 1, 'Tình Hình Căng Thẳng 5', 1, NULL, 'all', 0, 0, NULL, 454, 'Hiện tai tuy đã đẩy lùi được hồ tặc nhưng để đề phòng lịch sử lặp lại, ngươi dãy mau đi giáo huấn Thủ Lĩnh Hồ Tặc', '-1', 6, NULL, NULL),
	(50652, 'Nhận 10 Socola Bạc Hà', 1, 0, 1, 'Hãy thưởng thức tài nghệ của ta. Lễ Tình Nhân vui vẻ!', 376, 2, 'Mang Bột Cacao, Sữa Tươi, Tinh Dầu Bạc Hà giao cho Nhà Hàng Âu Dương, họ sẽ giúp bạn chế biến Socola Bạc Hà的！', NULL, -1, 160, 50, 0, 2, 'Làm Socola Bạc Hà (10 Viên)', 1, NULL, 'all', 1000000, 1, NULL, 376, 'Ngày lễ Tình Nhân đã đến,  muốn tự làm socola tặng người thương? Ok, chỉ cần Mang Bột Cacao, Sữa Tươi, Tinh Dầu Bạc Hà giao cho ta, ta sẽ giúp ngươi chế biến Socola Bạc Hà miễn phí. Lẽ nào ngươi không tin vào tay nghề của ta?', '-1', 6, NULL, NULL),
	(50654, 'Phần thưởng thần bí.', 1, 0, 1, 'Cảm ơn đã giúp đỡ. Đây là phần thưởng cảm ơn.', 2564, 2, 'Mang Socola Matcha,Socola Tan Chảy,Socola Hạt Dẻ,Socola Bạc Hà各10个 giao cho 情人节巧克力活动使者即可；', NULL, -1, 160, 50, 0, 2, 'Cung Cấp Hộp Socola Siêu Lớn (Mỗi Loại 10 Cái)', 1, NULL, 'all', 0, 1, NULL, 2564, 'Năm nào tôi cũng gửi cho người thương các loại Socola ngon; nhưng năm nay, Socola trong hộp của tôi đã bị những tinh linh nghịch ngợm ăn mất khá nhiều, bây giờ tôi đang rất buồn bạn có thể giúp tôi tìm thêm Socola được không?', '-1', 6, NULL, NULL),
	(50655, 'Phần thưởng thần bí.', 1, 0, 1, 'Cảm ơn đã giúp đỡ. Đây là phần thưởng cảm ơn.', 2564, 2, 'Mang Socola Matcha,Socola Tan Chảy,Socola Hạt Dẻ,Socola Bạc Hà各5个 giao cho 情人节巧克力活动使者即可；', NULL, -1, 160, 50, 0, 2, 'Cung Cấp Hộp Socola Lớn (Mỗi Loại 5 Cái)', 1, NULL, 'all', 0, 1, NULL, 2564, 'Năm nào tôi cũng gửi cho người thương các loại Socola ngon; nhưng năm nay, Socola trong hộp của tôi đã bị những tinh linh nghịch ngợm ăn mất khá nhiều, bây giờ tôi đang rất buồn bạn có thể giúp tôi tìm thêm Socola được không?', '-1', 6, NULL, NULL),
	(50656, 'Phần thưởng thần bí.', 1, 0, 1, 'Cảm ơn đã giúp đỡ. Đây là phần thưởng cảm ơn.', 2564, 2, 'Mang Socola Matcha, Socola Tan Chảy, Socola Hạt Dẻ, Socola Bạc Hà, mỗi loại 1 viên đến giao cho Sứ Giả sự kiện', NULL, -1, 160, 50, 0, 2, 'Cung Cấp Hộp Socola Trung (Mỗi Loại 1 Cái)', 1, NULL, 'all', 0, 1, NULL, 2564, 'Năm nào tôi cũng gửi cho người thương các loại Socola ngon; nhưng năm nay, Socola trong hộp của tôi đã bị những tinh linh nghịch ngợm ăn mất khá nhiều, bây giờ tôi đang rất buồn bạn có thể giúp tôi tìm thêm Socola được không?', '-1', 6, NULL, NULL),
	(50659, 'EXP, phần thưởng ngẫu nhiên', 1, 0, 1, 'Rất tốt, tiếp theo là phần 【Đuôi Rồng Lớn】', 1730, 2, 'Đến Tầng 5 Thế Giới Hải Dương gặp Long Vương mang về 1 【Thân Rồng Lớn】', NULL, -1, 200, 200, 0, 1, 'Vận Chuyển 【Thân Rồng】', 1, NULL, 'all', 0, 0, NULL, 1730, 'Mỗi năm cứ đến ngày Tết Đoan Ngọ là lúc đại hội Long Đan cũng bắt đầu, nhưng những nguyên liệu để luyện nên Long Đan vẫn còn thiếu, để bảo đảm cho Đại Hội được diễn ra suôn sẻ, hãy mang đến 【Thân Rồng Lớn】đến cho ta!', '-1', 6, NULL, NULL),
	(1807, NULL, 1, 78453, 0, 'Ngươi vất cả rồi!', 489, 2, 'Mang thư của Tộc Trưởng Bối Tư giao cho Đạo Sư Liêu Vân', NULL, -1, 160, 76, 40000, 2, 'Gửi Thư Cho Đạo Sư Thiên Khung', 1, NULL, 'all', 0, 0, NULL, 489, 'Hãy nói cho Tộc Trưởng, chúng ta mọi thời khắc đều đã chuẩn bị chiến đấu!
INSERT INTO data.data_tbl_quest (id, a_script_text, at, award_exp_re, color, complete_text, finish_npc, gender, info, is_rebirth, lm, max_level, min_level, money_num, money_type, name, pre_quest_type, qtest, req_class, rn, rt, script_give_up, start_npc, start_text, sub_type, type, start_grant_item, start_grant_qty) VALUES
	(5547, NULL, 1, 0, 3, 'Cảm ơn bạn đã giúp đỡ, đây là những dụng cụ nghi thức tôi thu thập được, có thể chia cho bạn một phần.', 2573, 2, 'Đến tầng 1 tiêu diệt Vua Bất Tử và Lãnh Chủ Kịch Độc', NULL, -1, 160, 50, 0, 2, 'Tìm Kho Báu (1)', 1, NULL, 'all', 0, 0, NULL, 2573, 'Khi tôi đang khám phá kho báu thì vô tình đánh thức một số quái vật, bạn có thể giúp tôi tiêu diệt chúng không?', '-1', 6, NULL, NULL),
	(5548, NULL, 1, 0, 3, 'Cảm ơn bạn, những dụng cụ nghi thức này xem như quà cảm ơn của tôi nhé.', 2576, 2, 'Thu thập 8 bản Ghi Chép Nghiên Cứu ', NULL, -1, 160, 50, 0, 2, 'Tìm Kho Báu (2)', 1, NULL, 'all', 0, 0, NULL, 2576, 'Đội nghiên cứu của chúng tôi đã gặp quái vật trong kho báu, trong lúc chạy trốn tôi làm rơi vài ghi chép nghiên cứu, có thể nhờ bạn tìm giúp không?', '-1', 6, NULL, NULL),
	(5549, NULL, 1, 0, 3, 'Tuyệt quá, bạn có thể giúp chúng tôi được không?', 2585, 2, 'Đến tầng 3 tìm Thành Viên Đội Nghiên Cứu', NULL, -1, 160, 50, 0, 2, 'Tìm Kho Báu (3)', 1, NULL, 'all', 0, 0, NULL, 2576, 'Các đồng đội của tôi vẫn chưa quay lại, họ có lẽ cũng cần hỗ trợ, bạn có thể đến tầng 3 tìm họ không?', '-1', 6, NULL, NULL),
	(5550, NULL, 1, 0, 3, 'Cảm ơn sự giúp đỡ của bạn, chúng tôi có thể tiếp tục nghiên cứu rồi, những dụng cụ nghi thức này giao cho bạn theo đúng thỏa thuận.', 2585, 2, NULL, NULL, -1, 160, 50, 0, 2, 'Tìm Kho Báu (4)', 1, NULL, 'all', 0, 0, NULL, 2585, 'Những thành viên khác bị quái vật nơi này giam giữ, xin hãy giải cứu họ, chúng tôi có thể đưa toàn bộ đồ tế lễ mà chúng tôi tìm được cho bạn.', '-1', 6, NULL, NULL),
	(1805, NULL, 1, 78453, 0, 'Ngươi vất cả rồi!', 639, 2, 'Đem thư của tộc trưởng Bối Tư giao cho tộc trưởng Đạo Sư Bàn Địa', NULL, -1, 160, 76, 40000, 2, 'Gửi Thư Cho Đạo Sư Lưu Hỏa', 1, NULL, 'all', 0, 0, NULL, 639, 'Hãy nói cho Tộc Trưởng, chúng ta mọi thời khắc đều đã chuẩn bị chiến đấu!
