	(50721, NULL, 1, 60000, 1, 'Ngươi đã tìm được mảnh vỡ bản mật mã rồi à? Tốt lắm, để ta xem xem', 288, 2, 'Tiêu diệt hồ tặc xem xem có thể tìm được manh mối gì không', NULL, -1, 200, 200, 36000, 1, 'Tình Hình Căng Thẳng 8', 1, NULL, 'all', 0, 0, NULL, 288, 'Chỉ nhìn cái thư này thì chẳng hiểu gì cả, ngươi xem xem có thể tìm ra manh mối gì không', '-1', 6, NULL, NULL),
	(50722, NULL, 1, 30000, 1, 'Cực cho ngươi quá!', 272, 2, 'Mang Thư Giải Mã đến Đông Huyền Thành giao cho Tộc Trưởng Bối Tư', NULL, -1, 200, 200, 18000, 1, 'Tình Hình Căng Thẳng 9', 1, NULL, 'all', 0, 0, NULL, 288, 'Giải mã xong rồi, ngươi hãy mau giao cho Tộc Trưởng Bối Tư.', '-1', 6, NULL, NULL),
